  const dx2 = (fr(k*6.7)*1.04 - .02 + Math.sin(T*.41 + ph)*.03 + stir*.02)*width;
  const dy2 = (fallv*1.1 - .05)*height;
  if (mode === 2) fill(216, 46, 52, 30*AL); else if (mode === 3) fill(32, 16, 40, 30*AL);
  else fill(44, 40, mode===1 ? 40 : 46, 34*AL);
  ellipse(dx2, dy2, u*.004*SC, u*.0065*SC);
}
blendMode(BLEND);

const D = { energy:.6, scale:1, density:.5, speed:1, hue:38, fold:5, bars:.5, phason:.35, x:.5, y:.5, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360;

// ---- the Fibonacci (Sturmian) chain --------------------------------------
// staircase of Z^2 under a line of slope 1/phi. step (1,0) -> short bar gap S,
// step (1,1) -> long gap L, with L/S = phi EXACTLY. This is the Ammann bar
// "musical sequence" LSLLSLSLL... ; normalised so the mean gap is 1 grid unit.
const TH = 0.6180339887498949;      // 1/phi
const C2 = 1 + TH*TH;
const pos = (m, r) => (m + TH*Math.floor(m*TH + r)) / C2;
const isL = (m, r) => (Math.floor((m+1)*TH + r) - Math.floor(m*TH + r)) === 1;

// ---- real-time drift: an exact rigid translation of the whole arrangement --
// (shifting a grid family by g.e_j translates the pattern by g -- de Bruijn)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const sp = .25 + .75*P.speed;
S.gx = (S.gx||0) + dt*sp*(.052 + .046*Math.sin(K.t*.037)      + .028*Math.sin(K.t*.091+1.1));
S.gy = (S.gy||0) + dt*sp*(.029 + .046*Math.sin(K.t*.043+2.3)  + .028*Math.cos(K.t*.113+.4));
S.ph = (S.ph||0) + dt*sp*(.06 + .34*P.phason);        // phason phase -> discrete bar flips
const rot = K.t*.0128*sp + .085*Math.sin(K.t*.0709+.6);

const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const trb  = (S.tb = (S.tb||0)*.86 + (A.treble||0)*.14);
const en = cl(P.energy,0,1), lift = .55 + .45*K.intensity;

// odd folds only: an even fold makes two families share a line direction
let NF = cl(Math.round(P.fold), 3, 9)|0; if (NF % 2 === 0) NF += 1;
const ax = cl(P.x,.15,.85)*width, ay = cl(P.y,.15,.85)*height;
const gu = u*.105*cl(P.scale,.6,2.4);
const R  = (Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay)) + u*.04) / gu;
const nl = cl(Math.ceil(R)+2, 4, Math.round(88/NF));

const EX=[], EY=[], RH=[], OF=[], M0=[];
for (let j=0;j<NF;j++){
  const a = 2*Math.PI*j/NF;
  EX[j] = Math.cos(a); EY[j] = Math.sin(a);
  RH[j] = fr(j*5.31+.7)*4.3 + S.ph*(1 + .23*fr(j*9.17));
  OF[j] = S.gx*EX[j] + S.gy*EY[j];
  M0[j] = Math.round(-(TH*RH[j] - TH*.5)/C2 - OF[j]);
}

// ---- style tables ---------------------------------------------------------
// VALUE DISCIPLINE (this is what the first cut got wrong): the ground is TONED, never
// near-white, and the bars are strong dark confident ink over it. Pale marks on a pale
// plate read as washed and empty; the whole point is the bars.
const addSty = (sty==='xray' || sty==='chalk');     // these two invert: light bars on a dark ground
function baseCol(){
  if (sty==='blueprint') return [212, 62, 34];      // prussian
  if (sty==='lapis')     return [238, 72, 40];      // deep lapis ground, gilt strapwork
  if (sty==='xray')      return [(H+186)%360, 52, 7];
  if (sty==='chalk')     return [214, 15, 21];      // slate
  return [ (H+2)%360, 15, 47 ];                     // plate: a TONED board, not bone paper
}
function barCol(){
  if (sty==='blueprint') return [190, 22, 99];
  if (sty==='lapis')     return [ (H+6)%360, 60, 93];
  if (sty==='xray')      return [ (H+170)%360, 34, 99];
  if (sty==='chalk')     return [ 46, 8, 96];
  return [ (H-16+360)%360, 62, 12 ];                // plate: near-black sepia ink
}

// ---- the coarse tonal field (fake-shader buffer, upscaled) ----------------
const bw = Math.max(360, Math.min(720, Math.round(width / 2.4))), bh = cl(Math.round(bw*height/Math.max(1,width)), 60, 720);
if (!S.g || S.gk !== bw+'x'+bh) { S.g = createGraphics(bw, bh); S.g.colorMode(HSB,360,100,100,100); S.gk = bw+'x'+bh; }
const g = S.g, bs = bw/width;
g.push(); g.noStroke(); g.blendMode(BLEND);
const bc = baseCol(); g.background(bc[0], bc[1], bc[2]);

// the six-tone aperiodic mosaic: how deep the L/S bands bite, and how many families carry them
const bandFams = cl(2 + Math.round(P.density*3), 1, NF);
const dep = (.13 + .24*P.density) * (.55 + .78*en);
g.push(); g.translate(ax*bs, ay*bs); g.rotate(rot);
g.blendMode(addSty ? ADD : MULTIPLY);
const gub = gu*bs, EB = (R+2.5)*gub;
for (let j=0;j<bandFams;j++){
  const ex=EX[j], ey=EY[j], r=RH[j], of=OF[j];
  for (let m=M0[j]-nl; m<=M0[j]+nl; m++){
    const d0 = pos(m,r)+of, d1 = pos(m+1,r)+of;
    if (d1 < -R-1.4 || d0 > R+1.4) continue;
    const L = isL(m,r);
    // L cells stay near the ground tone, S cells drop a clear step: the musical
    // sequence has to be legible as tone, not just as line spacing
    if (addSty) g.fill(L ? (H+8)%360 : (H+40)%360, L?36:58, (L ? 32 : 14)*(.5+.9*en), 100);
    else        g.fill((H+(L?4:26))%360, L?14:28, 100*(1 - dep*(L?.30:1.05)), 100);
    const a0=d0*gub, a1=d1*gub;
    g.quad(a0*ex - EB*ey, a0*ey + EB*ex,
           a1*ex - EB*ey, a1*ey + EB*ex,
           a1*ex + EB*ey, a1*ey - EB*ex,
           a0*ex + EB*ey, a0*ey - EB*ex);
  }
}
g.pop();

// chiaroscuro: sink the plate GENTLY, then relight with a wandering raking pool.
// (the first cut sank it 44% and then stacked ~10 additive white ellipses back on top,
//  which is exactly how it ended up at lum 0.865 — a pale field with faint lines.)
g.blendMode(MULTIPLY);
g.fill(0, 0, 100 - (10 + 16*en));
g.rect(0, 0, bw, bh);
g.blendMode(ADD);
const lx = (.5 + .30*Math.sin(K.t*.083) + .13*Math.sin(K.t*.211+1.9))*bw;
const ly = (.5 + .26*Math.cos(K.t*.067+.9) + .12*Math.sin(K.t*.173+2.6))*bh;
const pw = (3.4 + 4.2*en + 3.0*bass) * (.7 + .5*lift);
for (let i=0;i<8;i++){
  const q = i/7, rr = Math.max(bw,bh)*(1.30 - q*1.02);
  g.fill(addSty ? (H+150)%360 : (H+8)%360, addSty ? 30 : 22, 100, pw*(.30 + .70*q*q));
  g.ellipse(lx, ly, rr*2, rr*2);
}
g.blendMode(BLEND); g.pop();

// ---- cached plate grain --------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw = 460, th = 300, t = createGraphics(tw, th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2600;i++){
    const rr = .35 + fr(i*5.91)*1.7;
    t.fill(32, 7, 100 - fr(i*7.13)*26, 52);
    t.ellipse(fr(i*1.73)*tw, fr(i*3.37+9.1)*th, rr, rr);
  }
  t.stroke(32, 5, 95, 24); t.strokeWeight(1);
  for (let i=0;i<th;i+=4) t.line(0, i+fr(i*.31)*.7, tw, i+fr(i*.53+3)*.7);
  S.tex = t; S.texk = tk;
}

// ---- composite ------------------------------------------------------------
noStroke();
image(g, 0, 0, width, height);
blendMode(MULTIPLY);
image(S.tex, 0, 0, width, height);
blendMode(BLEND);

// ---- the Ammann bars themselves, crisp, at full resolution -----------------
push(); translate(ax, ay); rotate(rot);
strokeCap(SQUARE); noFill();
const bcl = barCol();
// heavy enough to be a STRUCTURE, not a hairline: ~2.2px at u=720 by default,
// up to real strapwork at bars=1
const bwt = (u/430) * (.6 + 1.4*cl(P.bars,0,1)) * (.85 + .3*en);
const EL = (R+.6)*gu;
for (let j=0;j<NF;j++){
  const ex=EX[j], ey=EY[j], r=RH[j], of=OF[j];
  const fam = .82 + .18*fr(j*3.7+2.1);
  for (let m=M0[j]-nl; m<=M0[j]+nl; m++){
    const d = pos(m,r)+of;
    if (d < -R-.4 || d > R+.4) continue;
    const L = isL(m,r);                       // the gap that OPENS at this bar
    const w = bwt*fam*(L ? 1 : .70);          // long bars carry more weight -> the sequence reads
    if (addSty) {
      const br = bcl[2] * (L?1:.72) * (.62+.42*trb+.30*en);
      stroke(bcl[0], bcl[1], cl(br,0,100), 84);
    } else {
      stroke(bcl[0], bcl[1], cl(bcl[2]*(L?1:1.9),0,100), 82 + 16*en);
    }
    strokeWeight(w);
    const dx = d*gu;
    line(dx*ex - EL*ey, dx*ey + EL*ex, dx*ex + EL*ey, dx*ey - EL*ex);
    if (sty==='blueprint' && L) {             // doubled rule on the long bars
      strokeWeight(w*.42); stroke(bcl[0], bcl[1], bcl[2], 34);
      const o = gu*.028;
      line(dx*ex - EL*ey + o*ex, dx*ey + EL*ex + o*ey, dx*ex + EL*ey + o*ex, dx*ey - EL*ex + o*ey);
    }
  }
}
pop();

noStroke();
if (P.alpha < 100) { fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
noFill();
blendMode(BLEND); drawingContext.shadowBlur = 0;

const D = { density: .5, scale: 1, energy: .62, speed: 1, hue: 205, x: .5, y: .5, glow: .55, style: 'quasi-octagon', act: 'sweep', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity != null ? K.intensity : .6);
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat; S.lastBeat = K.beat;

const SQ = Math.SQRT1_2, H = (1 + Math.SQRT2) / 2;
const BS = Math.ceil(1.5 * Math.max(width, height));
const dens = Math.min(1, Math.max(0, P.density));
let edgePx = BS * 0.085 * P.scale / (0.55 + dens * 1.4);
const minEdge = BS * 0.72 / 22;
if (edgePx < minEdge) edgePx = minEdge;
const genR = BS * 0.75;
const Rphys = genR / edgePx;

const key = [BS, edgePx.toFixed(2), st, P.seed].join('|');
if (S.key !== key) {
  S.key = key;
  const gx = (fr(1) - 0.5) * 0.5, gy = (fr(2) - 0.5) * 0.5;
  const N = Math.ceil(Rphys) + 3;
  const cc = BS * 0.5;
  const map = new Map(), verts = [];
  const accept = (a, b, c, d) => {
    const yx = a - SQ * b + SQ * d + gx;
    const yy = b * SQ - c + d * SQ + gy;
    if (Math.abs(yx) > H) return false;
    if (Math.abs(yy) > H) return false;
    if (Math.abs((yx + yy) * SQ) > H) return false;
    if (Math.abs((yy - yx) * SQ) > H) return false;
    return true;
  };
  for (let n1 = -N; n1 <= N; n1++) for (let n3 = -N; n3 <= N; n3++) {
    const c0 = SQ * (n1 - n3) - gx, c2 = SQ * (n1 + n3) + gy;
    for (let n0 = Math.floor(c0 - H); n0 <= Math.ceil(c0 + H); n0++)
      for (let n2 = Math.floor(c2 - H); n2 <= Math.ceil(c2 + H); n2++) {
        if (!accept(n0, n1, n2, n3)) continue;
        const px = (n0 + n1 * SQ - n3 * SQ) * edgePx;
        const py = (n1 * SQ + n2 + n3 * SQ) * edgePx;
        if (px * px + py * py > genR * genR) continue;
        const kk = n0 + ',' + n1 + ',' + n2 + ',' + n3;
        if (map.has(kk)) continue;
        const rec = { n: [n0, n1, n2, n3], x: cc + px, y: cc + py, r: Math.hypot(px, py) / genR };
        map.set(kk, rec); verts.push(rec);
      }
  }
  const pairs = [[0, 1], [0, 2], [0, 3], [1, 2], [1, 3], [2, 3]];
  const mk = (nn, inc) => (nn[0] + inc[0]) + ',' + (nn[1] + inc[1]) + ',' + (nn[2] + inc[2]) + ',' + (nn[3] + inc[3]);
  const tiles = [];
  for (const rec of verts) {
    const nn = rec.n;
    for (const pr of pairs) {
      const j = pr[0], k = pr[1];
      const ij = [0, 0, 0, 0]; ij[j] = 1;
      const ik = [0, 0, 0, 0]; ik[k] = 1;
      const ijk = [0, 0, 0, 0]; ijk[j] = 1; ijk[k] = 1;
      const rj = map.get(mk(nn, ij)), rk = map.get(mk(nn, ik)), rjk = map.get(mk(nn, ijk));
      if (!rj || !rk || !rjk) continue;
      tiles.push({ x0: rec.x, y0: rec.y, x1: rj.x, y1: rj.y, x2: rjk.x, y2: rjk.y, x3: rk.x, y3: rk.y,
        type: (Math.abs(j - k) === 2) ? 1 : 0, r: rec.r, jit: ((nn[0] * 7 + nn[1] * 13 + nn[2] * 17 + nn[3] * 23) * 0.61803) % 1 });
    }
  }

  // ---- bake tiling into buffer ----
  if (S.buf) S.buf.remove();
  const g = createGraphics(BS, BS); S.buf = g; S.BS = BS;
  g.colorMode(g.HSB, 360, 100, 100, 100);
  g.push();
  if (st === 'quasi-octagon') g.background((P.hue + 18) % 360, 42, 9);
  else if (st === 'stained-glass') g.background(0, 0, 4);
  else if (st === 'neon-lattice') g.background(232, 60, 5);
  else if (st === 'blueprint') g.background(220, 72, 13);
  else g.background(40, 12, 86);
  const jf = Math.max(0.6, edgePx);
  for (const t of tiles) {
    const jit = t.jit < 0 ? t.jit + 1 : t.jit;
    if (st === 'quasi-octagon') {
      if (t.type === 1) g.fill(P.hue, 66, 50 + jit * 16 + (1 - t.r) * 10);
      else g.fill((P.hue + 150) % 360, 58, 46 + jit * 16 + (1 - t.r) * 10);
      g.stroke((P.hue + 18) % 360, 55, 14); g.strokeWeight(Math.max(1, jf * 0.03));
    } else if (st === 'stained-glass') {
      const hh = (P.hue + t.r * 130 + t.type * 46 + jit * 22) % 360;
      g.fill(hh, 80, 40 + jit * 24 + (t.type ? 6 : 0));
      g.stroke(0, 0, 3); g.strokeWeight(Math.max(1.4, jf * 0.075));
    } else if (st === 'neon-lattice') {
      g.fill(232, 52, 7 + (1 - t.r) * 4);
      const hh = (P.hue + t.type * 150 + t.r * 70) % 360;
      g.stroke(hh, 82, 96); g.strokeWeight(Math.max(1, jf * 0.028));
    } else if (st === 'blueprint') {
      g.noFill();
      g.stroke(196, 68, 92); g.strokeWeight(Math.max(1, jf * 0.024));
    } else { // ink
      if (t.type === 1 && jit > 0.62) { g.fill(38, 16, 44, 42); } else g.noFill();
      g.stroke(34, 32, 22, 90); g.strokeWeight(Math.max(1, jf * 0.045 * (0.7 + jit * 0.7)));
    }
    g.beginShape();
    g.vertex(t.x0, t.y0); g.vertex(t.x1, t.y1); g.vertex(t.x2, t.y2); g.vertex(t.x3, t.y3);
    g.endShape(g.CLOSE);
  }

  // ---- Ammann bars (quasiperiodic straight-line grid, 4 directions) ----
  const bars = [];
  const shortS = edgePx * 0.9, longS = shortS * Math.SQRT2, al = Math.SQRT2 - 1;
  for (let m = 0; m < 4; m++) {
    const ang = m * Math.PI / 4, nx = Math.cos(ang), ny = Math.sin(ang), ph = fr(10 + m) * 3.3;
    let pos = (fr(20 + m) - 0.5) * edgePx, i = 0;
    while (pos < genR * 1.05) {
      bars.push({ nx, ny, t: pos, m });
      const sf = Math.floor((i + 1) * al + ph) - Math.floor(i * al + ph);
      pos += sf ? longS : shortS; i++;
    }
    pos = (fr(20 + m) - 0.5) * edgePx; i = 0;
    while (pos > -genR * 1.05) {
      const sf = Math.floor((i + 1) * al + ph) - Math.floor(i * al + ph);
      pos -= sf ? longS : shortS; i++;
      bars.push({ nx, ny, t: pos, m });
    }
  }
  // faint baked baseline of the bars so they read even outside the highlight
  if (st !== 'ink') {
    const L0 = genR * 1.2;
    const bc = st === 'blueprint' ? [196, 60, 60] : (st === 'neon-lattice' ? [(P.hue + 30) % 360, 40, 55] : [(P.hue + 40) % 360, 30, 55]);
    g.strokeWeight(1);
    for (const b of bars) {
      const mx = cc + b.nx * b.t, my = cc + b.ny * b.t, dx = -b.ny, dy = b.nx;
      g.stroke(bc[0], bc[1], bc[2], st === 'blueprint' ? 26 : 15);
      g.line(mx - dx * L0, my - dy * L0, mx + dx * L0, my + dy * L0);
    }
  }
  g.pop();
  S.bars = bars; S.genR = genR;
}

// ================= live frame =================
const rot = K.t * (0.006 + 0.02 * P.speed);
push();
translate(width * 0.5, height * 0.5);
rotate(rot);
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.buf, -S.BS * 0.5, -S.BS * 0.5);

// traveling luminous highlight along the Ammann bars
const range = S.genR;
const sweepPos = Math.sin(K.t * (0.03 + 0.10 * P.speed)) * range;
const sweepAng = K.t * (0.01 + 0.04 * P.speed);
const sdx = Math.cos(sweepAng), sdy = Math.sin(sweepAng);
const sigma = range * (0.10 + P.glow * 0.16 + intn * 0.05);
const peak = 0.4 + P.energy * 0.9 + intn * 0.3 + A.rms * 0.6;
const secDrift = (K.section || 0) * 15; // slow palette rotation across the 8 sections
const baseGlow = (st === 'blueprint' || st === 'ink') ? 0.14 : 0.20;
const L = range * 1.2;
blendMode(ADD);
for (const b of S.bars) {
  const mx = b.nx * b.t, my = b.ny * b.t;
  const proj = mx * sdx + my * sdy;
  const dd = proj - sweepPos;
  const band = Math.exp(-(dd * dd) / (2 * sigma * sigma));
  const bri = baseGlow + band * peak * 0.9;
  if (bri < 0.03) continue;
  const dx = -b.ny, dy = b.nx;
  const hh = (P.hue + b.m * 12 + 34 + secDrift) % 360;
  strokeWeight(1 + band * 2.6);
  stroke(hh, 26 + band * 24, 100, Math.min(58, bri * 55));
  line(mx - dx * L, my - dy * L, mx + dx * L, my + dy * L);
}
blendMode(BLEND);
pop();

// partial-frame beat bloom on the central octagonal sun (never full-frame flash)
const beatBloom = K.pulse * 0.5 + A.bass * 0.8;
if (beatBloom > 0.04) {
  push(); blendMode(ADD); noStroke();
  fill((P.hue + 40) % 360, 28, 100, beatBloom * 9);
  circle(width * 0.5, height * 0.5, u * 0.5 * (1 + beatBloom * 0.15));
  blendMode(BLEND); pop();
}

const D = { energy: .62, scale: 1, speed: 1, density: .5, kappa: .3, grain: .5, hue: 206, x: .5, y: .5, style: 'micrograph', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse field buffer (Perona-Malik anisotropic diffusion), image()-upscaled ----
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
