}
cw = S.cw; ch = S.ch; const NG = cw*ch;

// ---- seeded Clifford basin (verified-robust chaotic sets; rebuild on seed change) ----
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
  const SETS = [[-1.402,1.836,1.977,1.978],[1.956,1.864,1.699,-1.952],[1.898,1.599,-1.915,1.895],[1.418,1.749,-1.559,-1.869],[1.504,1.633,1.887,-1.982],[-1.346,-1.924,1.611,1.972],[1.663,-1.792,1.993,-1.573],[-1.945,-1.596,-1.709,-1.739],[1.357,1.837,-1.416,-1.728],[1.836,1.659,-1.817,-1.249],[1.873,-1.529,1.845,-1.655],[1.464,-1.935,-1.914,1.181],[-1.877,-1.953,1.953,0.86],[-1.835,-1.881,-1.797,1.504],[-1.948,-1.001,1.988,1.778],[-1.882,-1.421,-1.736,1.887]];
  const bs = SETS[Math.floor(fr(9)*SETS.length) % SETS.length];
  S.ba = bs[0] + (fr(1)*2-1)*0.02;
  S.bb = bs[1] + (fr(2)*2-1)*0.02;
  S.bc = bs[2] + (fr(3)*2-1)*0.02;
  S.bd = bs[3] + (fr(4)*2-1)*0.02;
