  const ang = ((P.hue-255)/360)*6.28318;
  const U = Math.cos(ang), Wv = Math.sin(ang);
  const m00=.299+.701*U+.168*Wv, m01=.587-.587*U+.330*Wv, m02=.114-.114*U-.497*Wv;
  const m10=.299-.299*U-.328*Wv, m11=.587+.413*U+.035*Wv, m12=.114-.114*U+.292*Wv;
  const m20=.299-.300*U+1.250*Wv, m21=.587-.588*U-1.050*Wv, m22=.114+.886*U-.203*Wv;
