const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const h2=(a,b)=>{const s=Math.sin(a*12.9898+b*78.233+P.seed*37.719)*43758.5453;return s-Math.floor(s);};
const sm=(e0,e1,x)=>{const t=cl((x-e0)/((e1-e0)||1e-6),0,1);return t*t*(3-2*t);};
const hsb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255|0,(g+m)*255|0,(l+m)*255|0]; };
const rs=(c,a)=>'rgba('+c[0]+','+c[1]+','+c[2]+','+a.toFixed(4)+')';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh), dc=drawingContext;
const sty=P.style, act=P.act;
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.6), dens=cl(P.density,0,1);
const fld=cl(P.field,0,1), dif=cl(P.diffuse,0,1), H0=md(P.hue,360);
const spd=cl(P.speed,.1,4), ax=cl(P.x,0,1), ay=cl(P.y,0,1), al=cl(P.alpha,0,1);
const T=K.t*spd;
const MODE = sty==='bubble'?1 : sty==='schematic'?2 : sty==='emulsion'?3 : 0;
const DARKINK = (MODE===1||MODE===3);

S.bass=(S.bass||0)*.9+(A.bass||0)*.1;
S.tre=(S.tre||0)*.9+(A.treble||0)*.1;

// ---- flux dramaturgy ----
let flux;
if(act==='source') flux=.72+.34*(.5+.5*Math.sin(K.t*.037))+.18*K.intensity;
else if(act==='shower'){ const q=md(T*.021,1); flux=.30+1.35*Math.pow(sm(.55,.80,q)*(1-sm(.86,1,q)),1.2)+.22*K.intensity; }
else flux=.52+.30*(.5+.5*Math.sin(K.t*.023+1.1))+.24*K.intensity;
flux=cl(flux,.12,1.9);

// ---- cached chamber: light sheet raking through the vapour, plate texture ----
let BW,BH;
if(W>=Hh){ BW=170; BH=Math.max(64,Math.round(170*Hh/Math.max(1,W))); }
else { BH=170; BW=Math.max(64,Math.round(170*W/Math.max(1,Hh))); }
const bk=BW+'x'+BH+'|'+sty+'|'+Math.round(H0)+'|'+P.seed+'|'+Math.round(ay*200);
if(!S.bg||S.bk!==bk){
  if(S.bg&&S.bg.remove)S.bg.remove();
  const g=createGraphics(BW,BH); g.pixelDensity(1); g.colorMode(HSB,360,100,100,100); g.noStroke();
  g.loadPixels(); const q=g.pixels;
  for(let j=0;j<BH;j++){
    const yn=j/BH, dy=(yn-ay)/.34;
    const sheet=Math.exp(-dy*dy*1.25);
    for(let i2=0;i2<BW;i2++){
      const xn=i2/BW;
      const vap=.5+.5*Math.sin(xn*7.3+yn*4.1)*Math.sin(yn*9.7-xn*3.3)+.3*Math.sin(xn*17.1+yn*13.9);
      const nz=Math.sin(i2*12.9898+j*78.233+P.seed*3.71)*43758.5453;
      const gn=(nz-Math.floor(nz)-.5);
      let hh,ss,bb;
      if(MODE===1){ hh=md(H0+152,360); ss=10+6*sheet; bb=cl(78+10*sheet+5*vap+gn*7,0,100); }
      else if(MODE===2){ hh=md(H0+16,360); ss=54; bb=cl(6+5*sheet+2*vap,0,100); }
      else if(MODE===3){ hh=md(H0+150,360); ss=8; bb=cl(58+8*sheet+4*vap+gn*11,0,100); }
      else { hh=md(H0-6+10*sheet,360); ss=cl(46-24*sheet,0,100); bb=cl(6+34*sheet+9*vap*sheet+gn*5,0,100); }
      const c=hsb(hh,ss,bb), o=(j*BW+i2)*4;
      q[o]=c[0]; q[o+1]=c[1]; q[o+2]=c[2]; q[o+3]=255;
    }
  }
  g.updatePixels();
  if(MODE===1){ g.stroke(md(H0+152,360),22,26,70); g.strokeWeight(.7);
    for(let j=0;j<5;j++) for(let i2=0;i2<7;i2++){ const cx=(i2+.5)/7*BW, cy=(j+.5)/5*BH;
      g.line(cx-2.5,cy,cx+2.5,cy); g.line(cx,cy-2.5,cx,cy+2.5); } g.noStroke(); }
  if(MODE===2){ g.stroke(md(H0+10,360),58,26,52); g.strokeWeight(.5);
    for(let i2=0;i2<=16;i2++) g.line(i2/16*BW,0,i2/16*BW,BH);
    for(let j=0;j<=10;j++) g.line(0,j/10*BH,BW,j/10*BH);
    g.stroke(md(H0+10,360),58,44,80); g.strokeWeight(.9);
    for(let i2=0;i2<=16;i2+=4) g.line(i2/16*BW,0,i2/16*BW,BH); g.noStroke(); }
  S.bg=g; S.bk=bk;
}
dc.imageSmoothingEnabled=true;
image(S.bg,0,0,W,Hh);

// ---- churning vapour: slow, large, low-alpha (the motion floor if flux ever lulls) ----
{ const nv=3;
  dc.globalCompositeOperation=DARKINK?'multiply':'lighter';
  for(let i=0;i<nv;i++){
    const w1=.021+fr(i*3.7)*.030, w2=.047+fr(i*3.7+1)*.055, ph=fr(i*3.7+2)*TAU;
    const vx=(.5+.34*Math.sin(K.t*w1*7.1+ph)+.14*Math.sin(K.t*w2*4.3+ph*1.7))*W;
    const vy=(ay+.26*Math.cos(K.t*w1*5.3+ph*.7)+.11*Math.sin(K.t*w2*6.1+ph))*Hh;
    const rr=u*(.34+.22*fr(i*9.1))*sc*(.8+.2*Math.sin(K.t*.031+i));
    const c=DARKINK?hsb(md(H0+150,360),14,72):hsb(md(H0+6,360),24,96);
    const gg=dc.createRadialGradient(vx,vy,0,vx,vy,rr);
    gg.addColorStop(0,rs(c,(DARKINK?.10:.075)*al)); gg.addColorStop(.55,rs(c,(DARKINK?.05:.030)*al)); gg.addColorStop(1,rs(c,0));
    dc.fillStyle=gg; dc.fillRect(0,0,W,Hh);
  }
  dc.globalCompositeOperation='source-over'; }

// ---- the tracks ----
const MAXP=34;
if(!S.px){ S.px=new Float64Array(MAXP); S.py=new Float64Array(MAXP); }
const px=S.px, py=S.py;
const N=Math.min(64,Math.round((12+dens*44)*cl(flux,.2,1.5)));
let cTrk;
if(MODE===1) cTrk=hsb(md(H0+160,360),34,10);
else if(MODE===2) cTrk=hsb(md(H0-6,360),72,98);
else if(MODE===3) cTrk=hsb(md(H0+164,360),22,14);
else cTrk=hsb(md(H0,360),10,100);
dc.lineCap='round'; dc.lineJoin='round';
dc.globalCompositeOperation=DARKINK?'multiply':'lighter';
for(let i=0;i<N;i++){
  const life=(2.0+4.4*fr(i*1.7))*(1.25-.45*dif);
  const uu=T/Math.max(.2,life)+fr(i*1.7+1)*11.3;
  const nn=Math.floor(uu), a=uu-nn;
  let kr=h2(i*3.1+.5,nn);
  if(act==='source') kr*=.42;
  const kind = kr<.20?0 : kr<.34?1 : 2;
  let x0,y0,th0;
  if(kind===0){ const aa=h2(i*5.3,nn)*TAU; x0=ax*W+Math.cos(aa)*u*.012; y0=ay*Hh+Math.sin(aa)*u*.012; th0=aa; }
  else if(kind===1){ th0=Math.PI*.5+(h2(i*5.3+1,nn)-.5)*.95; x0=h2(i*5.3+2,nn)*W*1.3-W*.15; y0=-u*.06; }
  else { x0=h2(i*5.3+3,nn)*W; y0=h2(i*5.3+4,nn)*Hh; th0=h2(i*5.3+5,nn)*TAU; }
  const ds=u*(.012+.020*fr(i*2.3))*sc*(.5+1.05*en)*(kind===0?.42:kind===1?1.6:.85);
  const M=kind===0?8:(kind===1?Math.min(MAXP,30):Math.min(MAXP,14+Math.round(fr(i*9.1)*16)));
  const sgn=h2(i*13.7,nn)<.5?-1:1;
  let kap=(kind===0?.020:kind===1?.004:(.055+.30*h2(i*11.3,nn)))*(.25+1.7*fld)*sgn;
  const kgrow=kind===2?1.058:1.004;
  const scat=(kind===0?.012:kind===1?.004:.048)*(1.25-.6*en);
  let x=x0,y=y0,th=th0;
  for(let m=0;m<M;m++){
    px[m]=x; py[m]=y;
    th+=kap+(h2(i*7.7+m*1.13,nn)-.5)*scat;
    kap*=kgrow;
    x+=Math.cos(th)*ds; y+=Math.sin(th)*ds;
  }
  const w0=(kind===0?.0115:kind===1?.0034:.0044)*u*sc*(.7+.6*en);
  const wid=w0*(1+(2.0+4.2*dif)*a);
  const br=Math.pow(1-a,1.3)*sm(0,.06,a)*cl(.55+.6*flux,0,1.5);
  if(br<=.012) continue;
  if(MODE===3){
    dc.fillStyle=rs(cTrk,1);
    for(let m=0;m<M;m+=2){
      if(h2(i*17.3+m,nn)>.62) continue;
      const gr=wid*(.5+1.1*h2(i*19.1+m,nn));
      dc.globalAlpha=cl(br*.72*al,0,.92);
      dc.beginPath(); dc.arc(px[m],py[m],gr,0,TAU); dc.fill();
    }
    continue;
  }
  dc.strokeStyle=rs(cTrk,1);
  if(MODE!==2){
    dc.globalAlpha=cl(br*(DARKINK?.16:.13+.15*en)*al,0,.5);
    dc.lineWidth=Math.max(.6,wid*2.9);
    dc.beginPath(); dc.moveTo(px[0],py[0]); for(let m=1;m<M;m++) dc.lineTo(px[m],py[m]); dc.stroke();
  }
  dc.globalAlpha=cl(br*(MODE===2?.78:(DARKINK?.62:.45+.42*en))*al,0,.95);
  dc.lineWidth=Math.max(.5,wid*(MODE===2?.6:.95));
  dc.beginPath(); dc.moveTo(px[0],py[0]); for(let m=1;m<M;m++) dc.lineTo(px[m],py[m]); dc.stroke();
}
dc.globalAlpha=1; dc.globalCompositeOperation='source-over';

// ---- the source pin: a needle of radioisotope the alphas fan out of ----
{ const sx=ax*W, sy=ay*Hh, pl=u*.05*sc;
  const c=DARKINK?hsb(md(H0+160,360),40,14):hsb(md(H0+30,360),42,88);
  dc.globalAlpha=cl(.85*al,0,1);
  dc.fillStyle=rs(c,1);
  dc.beginPath(); dc.moveTo(sx-pl*.09,sy); dc.lineTo(sx-pl*.22,sy+pl*2.6); dc.lineTo(sx+pl*.22,sy+pl*2.6); dc.lineTo(sx+pl*.09,sy); dc.closePath(); dc.fill();
  if(!DARKINK){ const gl=dc.createRadialGradient(sx,sy,0,sx,sy,pl*(.9+.25*Math.sin(K.t*.19)));
    const gc=hsb(md(H0+16,360),24,100);
    gl.addColorStop(0,rs(gc,cl((.30+.34*en)*(.7+.4*S.bass)*al,0,.8))); gl.addColorStop(1,rs(gc,0));
    dc.fillStyle=gl; dc.fillRect(sx-pl*2,sy-pl*2,pl*4,pl*4); }
  dc.globalAlpha=1; }
blendMode(BLEND); dc.globalAlpha=1; dc.globalCompositeOperation='source-over'; dc.shadowBlur=0; noStroke(); noTint();

const D = { density:.6, energy:.62, speed:1, scale:1, curl:.5, sway:.55, hue:275, x:.5, y:.92, style:'delta', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const wh = h => ((h%360)+360)%360;
const st = P.style;
const sec = K.section|0;
const intn = (K.intensity!=null?K.intensity:.6);
const aA = clp(P.alpha,0,100)/100;

// ---- style config: distinct rendering philosophies ----
// topB/botB = ground gradient (HSB) top->bottom(root) ; rootGlow = bloom at delta mouth
// stops = 3-stop orbit-length hue ramp (young->mid->old) ; add = additive glow vs flat ink
let cfg;
if (st==='coral')       cfg={topB:[196,72,9],  botB:[318,58,17], rootGlow:[330,72,40], stops:[338,302,176], sat:84, add:true,  coreBri:92, glowA:15, coreA:30, glintH:326, blur:true};
else if (st==='autumn') cfg={topB:[14,72,9],   botB:[34,82,18],  rootGlow:[42,92,44],  stops:[6,30,50],     sat:90, add:true,  coreBri:96, glowA:16, coreA:32, glintH:44,  blur:true};
else if (st==='bio')    cfg={topB:[222,82,7],  botB:[196,82,15], rootGlow:[168,92,40],  stops:[172,150,286], sat:92, add:true,  coreBri:99, glowA:18, coreA:30, glintH:172, blur:true};
else if (st==='ink')    cfg={topB:[38,9,90],   botB:[36,12,80],  rootGlow:[34,14,72],  stops:[32,30,28],    sat:14, add:false, coreBri:15, glowA:9,  coreA:44, glintH:30,  blur:false};
else /* delta */        cfg={topB:[238,70,15], botB:[276,48,30], rootGlow:[44,66,60],  stops:[283,188,46],  sat:88, add:true,  coreBri:96, glowA:16, coreA:32, glintH:48,  blur:true};

const rootX = clp(P.x,0.05,0.95)*width, rootY = clp(P.y,0.05,0.99)*height;

// ---- HSB->RGB for the ground buffer ----
function h2r(h,s,b){ h=wh(h); s=clp(s,0,100)/100; b=clp(b,0,100)/100; const c=b*s, x=c*(1-Math.abs((h/60)%2-1)), m=b-c; let r,g,bl;
  if(h<60){r=c;g=x;bl=0;} else if(h<120){r=x;g=c;bl=0;} else if(h<180){r=0;g=c;bl=x;}
  else if(h<240){r=0;g=x;bl=c;} else if(h<300){r=x;g=0;bl=c;} else {r=c;g=0;bl=x;}
  return [(r+m)*255,(g+m)*255,(bl+m)*255]; }

// ---- cached ground gradient (rebuild on size / style / hue / section) ----
const gKey = width+'x'+height+':'+st+':'+(P.seed|0)+':'+Math.round(P.hue)+':'+sec;
if (!S.gb || S.gKey !== gKey){
  const BW=Math.max(360, Math.min(640, Math.round(width/2.4))), BH=Math.max(48, Math.round(BW*height/width));
  if (!S.gb || S.gbw!==BW || S.gbh!==BH){ if(S.gb) S.gb.remove(); S.gb=createGraphics(BW,BH); S.gb.pixelDensity(1); S.gbw=BW; S.gbh=BH; }
  const gb=S.gb; gb.loadPixels(); const px=gb.pixels; const asp=(BW/BH);
  const rfx=clp(P.x,0.05,0.95), rfy=clp(P.y,0.05,0.99);
  const hd=(P.hue-275)*0.5, sd=sec*7;
  for (let j=0;j<BH;j++){
    const vy=j/(BH-1);
    for (let i=0;i<BW;i++){
      const fx=i/(BW-1);
      const dx=(fx-rfx)*asp, dy=(vy-rfy);
      const dist=Math.sqrt(dx*dx+dy*dy);
      let bloom=clp(1-dist*1.15,0,1); bloom=bloom*bloom;
      const hh = wh(cfg.topB[0]+(cfg.botB[0]-cfg.topB[0])*vy + hd + sd);
      const ss = cfg.topB[1]+(cfg.botB[1]-cfg.topB[1])*vy;
      let bb = cfg.topB[2]+(cfg.botB[2]-cfg.topB[2])*vy;
      const gh = wh(cfg.rootGlow[0]+hd+sd);
      const c1=h2r(hh,ss,bb), c2=h2r(gh,cfg.rootGlow[1],cfg.rootGlow[2]);
      const o=4*(j*BW+i);
      px[o]   = clp(c1[0]*(1-bloom)+c2[0]*bloom,0,255);
      px[o+1] = clp(c1[1]*(1-bloom)+c2[1]*bloom,0,255);
      px[o+2] = clp(c1[2]*(1-bloom)+c2[2]*bloom,0,255);
      px[o+3] = 255;
    }
  }
  gb.updatePixels(); S.gKey=gKey;
}

// ---- seed-deterministic Collatz strand geometry (rebuild on seed change) ----
const NMAX=220, CAP=64;
if (S.seedUsed!==P.seed || !S.str){
  S.seedUsed=P.seed;
  const fr=i=>{ const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s); };
  const str=[]; const seedInt=(P.seed|0);
  for (let gi=0;gi<NMAX;gi++){
    const n = 3 + (Math.floor(fr(gi+1)*9000) + gi*7 + seedInt*13);
    let v=n%100000, guard=0; if(v<3)v+=3;
    const par=[];
    while (v>1 && guard++<400){ par.push(v%2===0?0:1); v=(v%2===0)?v/2:3*v+1; }
    const L=par.length;
    const cap=Math.min(L,CAP);
    const p8=new Uint8Array(cap);
    for(let k=0;k<cap;k++) p8[k]=par[k];
    str.push({ par:p8, cap, norm:clp((L-6)/90,0,1), mir:(gi&1)?-1:1,
               fan:(fr(gi*2+3)-0.5)*0.95, ph:fr(gi*3+5)*6.283, jit:(fr(gi*5+7)-0.5)*0.14 });
  }
  S.str=str;
}
const str=S.str;

// ---- per-frame dynamics (all rhythm from K, audio ON TOP) ----
const flow  = K.t*(0.55+P.speed*0.5);
const glint = K.t*(0.11+P.speed*0.08);
const swayU = u*(0.018+P.sway*0.05);
const gsx = Math.sin(K.t*0.11)*swayU + Math.sin(K.t*0.041+1.3)*swayU*0.6 + A.lowmid*u*0.02;
const gsy = Math.cos(K.t*0.083)*swayU*0.5 + Math.sin(K.t*0.027)*swayU*0.35;
const gsr = 0.035*Math.sin(K.t*0.067) + 0.02*Math.sin(K.t*0.019+0.7);
const cosR=Math.cos(gsr), sinR=Math.sin(gsr);
const segLen = u*0.011*clp(P.scale,0.4,2.4);
const cr = clp(P.curl,0.05,1.05)*0.5;
const evenA=cr*0.55, oddA=cr;
const baseAng=Math.PI/2;
const N = Math.round(clp(28 + P.density*175,10,200));
const expo = 0.55 + P.energy*0.85 + intn*0.3 + A.rms*0.6;
const ramp = n => { n=clp(n,0,1); return n<0.5 ? cfg.stops[0]+(cfg.stops[1]-cfg.stops[0])*(n/0.5) : cfg.stops[1]+(cfg.stops[2]-cfg.stops[1])*((n-0.5)/0.5); };
const hShift=(P.hue-275)*0.6;

// ---- draw ground (fills frame; slow parallax drift on K.t) ----
const pdx=Math.sin(K.t*0.05)*u*0.012, pdy=Math.cos(K.t*0.037)*u*0.010;
push();
if (aA<1) tint(0,0,100,aA*100);
image(S.gb, pdx-u*0.02, pdy-u*0.02, width+u*0.04, height+u*0.04);
noTint();
pop();

// ---- draw the braided delta ----
push();
blendMode(cfg.add?ADD:BLEND);
noFill(); strokeCap(ROUND); strokeJoin(ROUND);
const glintDots=[];
for (let s=0;s<N;s++){
  const S1=str[s]; const cap=S1.cap; if(cap<3) continue;
  const norm=S1.norm, mir=S1.mir, jf=1+S1.jit;
  let ang=baseAng+S1.fan, lx=0, ly=0;
  const gi=Math.floor((((glint+S1.ph)%1+1)%1)*(cap-1));
  let gx=rootX, gy=rootY;
  const xs=new Array(cap+1), ys=new Array(cap+1);
  xs[0]=rootX+gsx; ys[0]=rootY+gsy;
  for (let k=0;k<cap;k++){
    ang += (S1.par[k]? -oddA:evenA)*jf;
    lx += Math.cos(ang)*segLen; ly += Math.sin(ang)*segLen;
    const off=Math.sin(k*0.42 - flow + S1.ph)*segLen*0.55*(k/cap)*(0.5+cr);
    const pxL=(lx+off)*mir, pyL=ly;
    const rx=pxL*cosR - pyL*sinR, ry=pxL*sinR + pyL*cosR;
    const wx=rootX+rx+gsx, wy=rootY-ry+gsy;
    xs[k+1]=wx; ys[k+1]=wy;
    if(k===gi){ gx=wx; gy=wy; }
  }
  const h=wh(ramp(norm)+hShift+sec*4);
  const sb=clp(cfg.coreBri*0.6 + norm*38, 12, 100);
  const eA=clp(cfg.coreA*(0.45+P.energy*0.9), 8, 60)*aA;
  const gA=clp(cfg.glowA*(0.45+P.energy*0.9), 4, 34)*aA;
  // glow underlay (fat, translucent)
  if(cfg.add){ stroke(h,cfg.sat-20,sb,gA); strokeWeight((2.4+norm*2.6)*(0.6+P.scale*0.4));
    beginShape(); for(let q=0;q<=cap;q++) vertex(xs[q],ys[q]); endShape(); }
  // core line
