}

const D = { energy: .6, scale: 1, density: .5, weight: .6, hue: 28, speed: 1, x: .5, y: .52, alpha: 1, style: 'burin', act: 'plate', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const wt=cl(P.weight,0,1.6), sc=cl(P.scale,.5,2.2), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.2,4);
const en=cl(P.energy,0,1)*(.5+.6*K.intensity);
const T=K.t*spd, H=md(P.hue,360);
const cx=cl(P.x,.1,.9)*W, cy=cl(P.y,.1,.9)*Hh;

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
const kick=Math.min(1, K.pulse*.45 + S.bass*.55);

// ---- style: how form is BUILT, not just its hue ----
// NOTE (rescue): every ground here is TONED — mid-key. The first cut of this
// asset printed pale bistre onto near-ivory (paper b=92) and the whole plate
// washed out to an empty cream page at lum .78. Tone is the point of an
// engraving: it is built ENTIRELY from hatch density, so the paper must sit
// low enough for the ink to have somewhere to go.
const mezz=(sty==='mezzotint'), cont=(sty==='contour'), sang=(sty==='sanguine');
let pH,pS,pB, iH,iS,iB, xhatch=true, tonal=true;
if(mezz){ pH=252; pS=26; pB=7;  iH=md(H+18,360);  iS=6;  iB=95; tonal=true; }
else if(cont){ pH=208; pS=48; pB=14; iH=md(H+160,360); iS=30; iB=97; xhatch=false; tonal=false; }
else if(sang){ pH=34; pS=18; pB=66; iH=md(H-14,360); iS=66; iB=44; }
else { pH=42; pS=14; pB=58; iH=md(H+6,360); iS=36; iB=10; }

// ---- the plate: laid paper / mezzotint ground / burnished copper (cached) ----
const pkey=W+'x'+Hh+'|'+sty+'|'+P.seed;
if(!S.pl||S.plKey!==pkey){
  const g=(S.pl&&S.pl.width===W&&S.pl.height===Hh)?S.pl:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.noStroke(); g.background(pH,pS,pB);
  const up=(mezz||cont);
  g.strokeWeight(1);
  for(let i=0;i<Math.round(W/26);i++){ g.stroke(pH,pS+6,up?pB+7:pB-9,12); g.line(i*26+7,0,i*26+7,Hh); }
  for(let i=0;i<620;i++){ const x=fr(i*19)*W, y=fr(i*19+1)*Hh, a=fr(i*19+2)*TAU, L=2+fr(i*19+3)*13;
    g.stroke(pH,pS+9,up?pB+16:pB+13,8+fr(i*19+4)*14); g.line(x,y,x+Math.cos(a)*L,y+Math.sin(a)*L); }
  g.noStroke();
  for(let i=0;i<760;i++){ const x=fr(i*37)*W, y=fr(i*37+1)*Hh;
    g.fill(pH,pS+10,up?pB+21:pB-16,6+fr(i*37+2)*11); g.circle(x,y,.7+fr(i*37+3)*2.3); }
  const m=u*0.045; g.noFill(); g.strokeWeight(Math.max(2,u*0.004));
  g.stroke(pH,pS+4,up?pB+18:pB-20,34); g.rect(m,m,W-2*m,Hh-2*m,u*0.006);
  g.strokeWeight(1); g.stroke(pH,pS+2,pB+22,26); g.rect(m+2,m+2,W-2*m-4,Hh-2*m-4,u*0.006);
  g.noStroke(); S.pl=g; S.plKey=pkey; }
image(S.pl,0,0);

// ---- THE SUBJECT: a modelled volume. A draped ovoid under a raking lamp. ----
// An ellipsoid height field + drapery folds that taper to nothing at the
// silhouette. Everything downstream reads tone off this — the engraving has a
// body to describe instead of an empty page.
const RX=.46*sc, RY=.52*sc, RZ=.40*sc;
const FOLD=.055*sc*(.45+en*.95);
const FW=7.4/sc;
const fd=T*.043+.8*Math.sin(T*.017)+.4*Math.sin(T*.0071);   // folds breathe, never repeat
const bf=2.1/sc, bg=1.7/sc, bt1=T*.037, bt2=T*.029;
const BAMP=.16;
let _gx=0,_gy=0,_in=0;
const field=(x,y)=>{
  const sa=Math.sin(x*bf+bt1), ca=Math.cos(x*bf+bt1), sb=Math.sin(y*bg-bt2), cb=Math.cos(y*bg-bt2);
  let h=BAMP*sa*cb, gx=BAMP*bf*ca*cb, gy=-BAMP*bg*sa*sb;
  let ins=0;
  const X=x/RX, Y=y/RY, rr=X*X+Y*Y;
  if(rr<1){
    ins=1;
    const q=Math.max(.09,Math.sqrt(1-rr));
    h+=RZ*q; gx+=RZ*(-X/RX)/q; gy+=RZ*(-Y/RY)/q;
    const tap=1-rr, sf=Math.sin(x*FW+fd), cf=Math.cos(x*FW+fd);
    h+=FOLD*tap*sf;
    gx+=FOLD*(tap*FW*cf - 2*X/RX*sf);
    gy+=FOLD*(-2*Y/RY*sf);
  }
  _gx=gx; _gy=gy; _in=ins; return h;
};

// ---- raking light on two incommensurate orbits (the primary motion floor) ----
let phi=T*.13+.75*Math.sin(T*.061)+1.1*Math.sin(T*.0237);
if(act==='proof') phi=T*.27+.9*Math.sin(T*.083);
const psi=.30+.20*Math.sin(T*.089)+.08*Math.sin(T*.0413);
const Lz=Math.sin(psi), Lc=Math.cos(psi), Lx=Math.cos(phi)*Lc, Ly=Math.sin(phi)*Lc;
const rel=(1.0+1.8*en)*(1+.28*kick*en);
const amb=mezz?.13:.19;
let inkTone=1; if(act==='burnish') inkTone=.6+.9*K.intensity;
// backdrop: a graded studio sweep, NOT lambert — a flat wall under a raking
// lamp would be uniformly black and swallow the whole frame.
const BD0=.60, BD1=.30;
const val=(px,py)=>{
  const x=(px-cx)/u, y=(py-cy)/u;
  field(x,y);
  if(_in){
    const gx=_gx*rel, gy=_gy*rel, nl=Math.sqrt(gx*gx+gy*gy+1);
    const v=(-gx*Lx-gy*Ly+Lz)/nl;
    return cl(amb+(1-amb)*cl(v,0,1),0,1);
  }
  const X=x/RX, Y=y/RY, rr=X*X+Y*Y;
  const roll=.10*Math.sin(x*bf+bt1)*Math.cos(y*bg-bt2);
  let vb=BD0+BD1*(.5-y)+roll;
  vb*=1-.40*Math.exp(-(rr-1)*2.6);          // occlusion halo hugging the form
  return cl(vb,0,1);
};

// ---- hatch: swelling burin ribbons that follow the surface contour ----
const a0=(sang?-.35:-.22)+.16*Math.sin(T*.023);
const fam=(ang,N,pitch,gamma,bend,wmul,shade)=>{
  const ca=Math.cos(ang), sa2=Math.sin(ang);
  const L=Math.abs(W*ca)+Math.abs(Hh*sa2)+u*.12;
  const NS=38, step=L/NS;
  const px=S._px||(S._px=new Float32Array(64)), py=S._py||(S._py=new Float32Array(64));
  const nxA=S._nx||(S._nx=new Float32Array(64)), nyA=S._ny||(S._ny=new Float32Array(64)), wA=S._w||(S._w=new Float32Array(64));
  for(let k=0;k<N;k++){
    const o=(k-(N-1)/2)*pitch + (fr(k*3+ang*17)-.5)*pitch*.34;
    let x=cx-ca*L/2-sa2*o, y=cy-sa2*L/2+ca*o;
    let dx=ca, dy=sa2, any=false;
    for(let s=0;s<=NS;s++){
      const v=val(x,y);
      let mark = shade? cl(v-.10,0,1) : cl(1-v,0,1);
      if(!tonal) mark=cl(.30+Math.min(Math.sqrt(_gx*_gx+_gy*_gy)*.30,.6),0,1);
      const w=pitch*wmul*Math.pow(mark,gamma)*wt*inkTone;
      px[s]=x; py[s]=y; nxA[s]=-dy; nyA[s]=dx; wA[s]=w; if(w>.30) any=true;
      const gl=Math.sqrt(_gx*_gx+_gy*_gy)+1e-5;
      let tx=-_gy/gl, ty=_gx/gl;
      if(tx*dx+ty*dy<0){ tx=-tx; ty=-ty; }
      const bnd=_in?bend:bend*.25;              // the backdrop hatch runs straight
      dx=dx*(1-bnd)+tx*bnd; dy=dy*(1-bnd)+ty*bnd;
      const dl=Math.sqrt(dx*dx+dy*dy)+1e-6; dx/=dl; dy/=dl;
      x+=dx*step; y+=dy*step;
    }
    if(!any) continue;
    beginShape();
    for(let s=0;s<=NS;s++) vertex(px[s]+nxA[s]*wA[s], py[s]+nyA[s]*wA[s]);
    for(let s=NS;s>=0;s--) vertex(px[s]-nxA[s]*wA[s], py[s]-nyA[s]*wA[s]);
    endShape(CLOSE);
  }
};

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
noStroke();
dc.globalCompositeOperation = mezz||cont ? 'lighter' : 'multiply';
const N1=Math.round(56+dens*48);
const ext1=Math.abs(W*Math.sin(a0))+Math.abs(Hh*Math.cos(a0))+u*.1;
fill(iH,iS,iB, (mezz?70:cont?64:92)*al);
fam(a0, N1, ext1/N1, sang?1.10:1.25, cont?.34:.52, .86, mezz);
if(xhatch){
  const a1=a0+(sang?1.02:1.18);
  const N2=Math.round(N1*(sang?.40:.60));
  const ext2=Math.abs(W*Math.sin(a1))+Math.abs(Hh*Math.cos(a1))+u*.1;
  fill(iH,iS,mezz?iB:iB+(sang?8:5), (mezz?52:sang?62:82)*al);
  fam(a1, N2, ext2/N2, mezz?2.4:2.15, .40, .62, mezz);
}

// ---- burin flicks in the deepest darks (the engraver's lozenge dots) ----
const NFL=Math.round(90+dens*140);
fill(iH,iS,mezz?100:iB+8,(mezz?60:74)*al);
for(let i=0;i<NFL;i++){
  const x=fr(i*41)*W, y=fr(i*41+1)*Hh, v=val(x,y);
  const m=mezz? cl(v-.35,0,1) : cl(.40-v,0,1);
  if(m<.03) continue;
  const a=fr(i*41+2)*TAU, len=u*.004*(1+m*4)*wt;
  push(); translate(x,y); rotate(a+_gx*.4); ellipse(0,0,len*2.4,len*.7+.7); pop();
}

// ---- ink tone: a slow wash that deepens the plate over the section arc ----
dc.globalCompositeOperation = mezz||cont ? 'source-over' : 'multiply';
if(!(mezz||cont)){ noStroke(); fill(iH,iS*.6,iB+30, (4+8*K.intensity)*al); rect(0,0,W,Hh); }
dc.globalCompositeOperation=oldOp;

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.shadowBlur=0; noStroke(); noTint();

const D = { energy:.6, scale:1, density:.5, speed:1, hue:26, wig:.55, rings:.6, x:.5, y:.5, style:'inlay', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);

// ---- an interlocking tile that PROVABLY tiles the plane -------------------
// Start from the regular hexagon (a parallelogon). Its neighbour across edge i
// is the translate by T_i = v_i + v_{i+1}. For the tile to keep tiling after we
// deform edge i into any curve C, edge i+3 must become exactly reverse(C - T_i).
// Every wiggle we add is mirrored onto the opposite edge, so the shape can morph
// live -- as wildly as it likes -- and the coronas still lock together with zero
// gap. Endpoints are pinned because every harmonic is sin(pi*h*f), zero at f=0,1.
const VX=[], VY=[];
for (let i=0;i<6;i++){ const a = Math.PI/6 + i*Math.PI/3; VX[i]=Math.cos(a); VY[i]=Math.sin(a); }
const TXv=[], TYv=[];
for (let i=0;i<3;i++){ TXv[i]=VX[i]+VX[(i+1)%6]; TYv[i]=VY[i]+VY[(i+1)%6]; }

const MS = 6;
const wig = cl(P.wig,0,1) * (.35 + .85*en) * .34;
const EDG = [];
for (let i=0;i<3;i++){
  const x0=VX[i], y0=VY[i], x1=VX[(i+1)%6], y1=VY[(i+1)%6];
  let tx=x1-x0, ty=y1-y0; const tl=Math.hypot(tx,ty)||1; tx/=tl; ty/=tl;
  const nx=-ty, ny=tx;
  const pts=[];
  for (let s=0;s<=MS;s++){
    const f=s/MS;
    let amp=0;
    for (let hh=1;hh<=3;hh++){
      const a0 = (fr(i*17.3+hh*5.1)*2-1)/hh;
      const ph = K.t*(.061*hh + .047*fr(i*3.1+hh)) * sp + fr(i*7.7+hh*2.3)*6.283;
      amp += a0*Math.sin(Math.PI*hh*f + 0)*Math.sin(ph)*0.9 + a0*Math.sin(Math.PI*hh*f)*.45;
    }
    amp *= wig*tl;
    let tg = 0;
    for (let hh=1;hh<=2;hh++){
      const b0 = (fr(i*23.9+hh*11.7)*2-1)/hh;
      tg += b0*Math.sin(Math.PI*hh*f)*Math.sin(K.t*(.083+.037*hh)*sp + fr(i*13.1+hh)*6.283);
    }
    tg *= wig*tl*.5;
    pts.push(x0+tx*(f*tl+tg)+nx*amp, y0+ty*(f*tl+tg)+ny*amp);
  }
  EDG[i]=pts;
}
for (let i=0;i<3;i++){                       // the forced opposite edges
  const src=EDG[i], out=[];
  for (let s=MS;s>=0;s--){ out.push(src[s*2]-TXv[i], src[s*2+1]-TYv[i]); }
  EDG[i+3]=out;
}
const BX=[], BY=[];
for (let i=0;i<6;i++){ const e=EDG[i]; for (let s=0;s<MS;s++){ BX.push(e[s*2]); BY.push(e[s*2+1]); } }
const NB = BX.length;

// ---- lattice + coronas ----------------------------------------------------
const ax = cl(P.x,.2,.8)*width, ay = cl(P.y,.2,.8)*height;
const corner = Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay));
const NMAX = 9;
const hexR = Math.max(u*.105*cl(P.scale,.55,2.0), corner/(1.732*NMAX + 1));
const NC = cl(Math.ceil(corner/(1.732*hexR) - .5) + 1, 1, NMAX);
const rot = K.t*.0132*sp + .10*Math.sin(K.t*.0713+1.4);

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function grd(){
  if (sty==='riso')   return [44, 9, 93];
  if (sty==='verdi')  return [172, 34, 15];
  if (glow)           return [(H+192)%360, 56, 5];
  if (sty==='slate')  return [216, 13, 17];
  return [(H+10)%360, 30, 13];                 // inlay: dark shellac between cells
}
function cellCol(n, w, sh){
  const q = n/Math.max(1,NC);
  if (sty==='riso')  return [ (n%2) ? 352 : 205, 58 + 14*w, cl(96 - 26*(1-w) + 10*sh, 20, 100) ];
  if (sty==='verdi') return [ (168 + q*26 + w*22)%360, cl(44 - 18*w,6,90), cl(30 + 46*sh + 30*w, 6, 96) ];
  if (glow)          return [ (H + 130 + q*100 + w*60)%360, 42, cl(30 + 70*w + 40*sh, 4, 100) ];
  if (sty==='slate') return [ 214, cl(8 + 8*w,0,40), cl(24 + 48*sh + 26*w, 5, 92) ];
  return [ (H + 4 + q*20 + w*16)%360, cl(52 - 22*w, 8, 80), cl(28 + 50*sh + 30*w, 5, 96) ];
}

const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);

// light direction orbits -> every cell's shading changes continuously
const lang = K.t*.077*sp + .6*Math.sin(K.t*.029+1.1);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const wavT = K.t*(.55 + .95*sp) + .8*Math.sin(K.t*.043);
const rw = cl(P.rings,0,1);

push(); translate(ax, ay); rotate(rot);
strokeJoin(ROUND); strokeWeight((u/900)*(.7 + 2.0*en));
const inner = cl(P.density,0,1) > .22;

for (let a=-NC;a<=NC;a++){
  for (let b=-NC;b<=NC;b++){
    const n = (Math.abs(a) + Math.abs(b) + Math.abs(a+b))*.5;    // axial hex distance
    if (n > NC) continue;
    const cx = (a*TXv[0] + b*TXv[1])*hexR, cy = (a*TYv[0] + b*TYv[1])*hexR;
    if (Math.abs(cx) > corner + hexR*1.8 || Math.abs(cy) > corner + hexR*1.8) continue;
    // the corona wave: rings of state change rippling out through the layers
    const w = rw * Math.pow(Math.max(0, Math.sin(n*.92 - wavT)), 2) * (.65 + .5*bass) * lift;
    const jit = fr(a*31.7 + b*17.3);
    // flat shade off the orbiting light
    const dl = Math.hypot(cx,cy) || 1;
    const sh = (.34 + .5*((cx/dl)*lgx + (cy/dl)*lgy)*.5 + .5*.5) * (.6 + .55*en) + .12*jit;
    const c = cellCol(n, w, sh);
    fill(c[0], c[1], c[2], glow ? cl(38 + 54*w, 14, 96) : 100);
    stroke(gc[0], cl(gc[1]*1.15,0,100), cl(gc[2]*(.45+.5*(1-en)),0,100), 88);
    beginShape();
    for (let s=0;s<NB;s++) vertex(cx + BX[s]*hexR, cy + BY[s]*hexR);
    endShape(CLOSE);
    if (inner) {                              // inlaid contour -> engraved relief
      noFill();
      stroke(c[0], cl(c[1]+16,0,100), cl(c[2]*.52,0,100), 30 + 46*cl(P.density,0,1));
      strokeWeight((u/900)*(.5 + .9*en));
      const k2 = .80 - .10*cl(P.density,0,1);
      beginShape();
      for (let s=0;s<NB;s++) vertex(cx + BX[s]*hexR*k2, cy + BY[s]*hexR*k2);
      endShape(CLOSE);
      stroke(c[0], c[1], cl(c[2]*1.35,0,100), 22 + 30*w);
      strokeWeight((u/900)*(.4 + .7*en));
      const k3 = k2*.56;
      beginShape();
      for (let s=0;s<NB;s++) vertex(cx + BX[s]*hexR*k3, cy + BY[s]*hexR*k3);
      endShape(CLOSE);
      strokeWeight((u/900)*(.7 + 2.0*en));
    }
  }
}
pop();

// ---- moving chiaroscuro ---------------------------------------------------
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (18 + 30*en));
L.blendMode(ADD);
const plx = (.5 + .28*Math.sin(K.t*.067+.7))*lw2, ply = (.5 + .24*Math.cos(K.t*.053+2.4))*lh2;
for (let i=0;i<9;i++){
  const q=i/8, rr=Math.max(lw2,lh2)*(1.26-q*.98);
  L.fill(0,0,100, (6.5 + 7*en + 5*bass)*(.28+.72*q*q));
  L.ellipse(plx, ply, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached grain ---------------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=420, th=280, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2200;i++){
    const rr=.4+fr(i*4.31)*1.8;
    t.fill(30, 8, 100-fr(i*6.77)*42, 50);
    t.ellipse(fr(i*2.53)*tw, fr(i*3.79+5.1)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;

const D = { energy: .6, scale: 1, speed: 1, density: .5, shear: .35, hue: 40, x: .5, y: .80, style: 'euv_gold', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Coronal rain over an arcade -----------------------------------------------------------
// An arcade of magnetic loops standing off the limb, each rooted at both feet in the
// photosphere and filled with million-degree plasma that glows in the extreme ultraviolet.
// A loop that is heated near its feet piles up too much mass at its top to stay hot; the
// balance fails, the apex CATASTROPHICALLY COOLS in minutes, and the plasma there condenses
// into blobs a hundred times denser and cooler than the corona around them. They cannot fall
// straight down — they are charged, and charged matter is threaded on the field — so they
// drain along the loop instead, and that is the whole beauty of it: the gravity a blob feels
// is only the component along its own field line, which is ZERO at the apex and full at the
// footpoint. So it hangs at the top, creeps, and then plunges into the leg. That is integrated
// here, not faked: each drop carries a true speed along the arc, ds/du and dy/du come from the
// loop's own geometry, and the drop drains to whichever side of the apex it happened to
// condense on. Drops respawn forever, so the arcade never empties and never settles.
// The loops themselves ring in the transverse kink mode, each at its own incommensurate rate.
// --------------------------------------------------------------------------------------------

const TAU = 6.283185307;
const PI = Math.PI;
const style = P.style;
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const fr2 = (i, j) => { const s = Math.sin(i * 127.1 + j * 311.7 + sd * 74.77) * 43758.5453; return s - Math.floor(s); };

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtr = K.t - S.lastT; S.lastT = K.t;
dtr = dtr < 0 ? 0 : (dtr > 0.06 ? 0.06 : dtr);
if (S.T == null) S.T = 0;
const spd = 0.25 + P.speed * 0.9;
S.T += dtr * spd;
const ts = S.T, dt = dtr * spd;

const en = Math.min(1, Math.max(0, P.energy));
const scl = Math.max(0.4, P.scale);
const dens = Math.min(1, Math.max(0, P.density));
const limbY = Math.min(0.98, Math.max(0.45, P.y)) * height;
const arcX = Math.min(1, Math.max(0, P.x)) * width;
const shearA = (P.shear - 0.5) * 1.5;

// incommensurate real-time floor
const dr1 = Math.sin(K.t * 0.061) * 0.9 + Math.sin(K.t * 0.143 + 1.7) * 0.5 + Math.sin(K.t * 0.229) * 0.32;
const dr2 = Math.sin(K.t * 0.077 + 2.1) * 0.8 + Math.sin(K.t * 0.181 + 0.4) * 0.44;

const h2rgb = (h, s, v) => {
  h = (((h % 360) + 360) % 360) / 60;
  const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  if (h < 1) return [c + m, x + m, m];
  if (h < 2) return [x + m, c + m, m];
  if (h < 3) return [m, c + m, x + m];
  if (h < 4) return [m, x + m, c + m];
  if (h < 5) return [x + m, m, c + m];
  return [c + m, m, x + m];
};

// ---- the arcade ---------------------------------------------------------------------------
const NL = Math.round(5 + dens * 13);
if (!S.LX || S.LX.length < 24) { S.LX = new Float64Array(24); S.LRX = new Float64Array(24); S.LRY = new Float64Array(24); S.LRO = new Float64Array(24); S.LKK = new Float64Array(24); S.LDZ = new Float64Array(24); }
const LX = S.LX, LRX = S.LRX, LRY = S.LRY, LRO = S.LRO, LKK = S.LKK, LDZ = S.LDZ;
const spread = (0.30 + dens * 0.42) * scl;
for (let li = 0; li < NL; li++) {
  const f1 = fr(li * 3.1 + 1.7), f2 = fr(li * 7.7 + 5.3), f3 = fr(li * 11.3 + 9.1), f4 = fr(li * 5.1 + 13.7);
  const dz = 0.40 + f1 * 0.60;                                   // depth rank: far loops small + hazed
  LDZ[li] = dz;
  LX[li] = arcX + ((NL < 2 ? 0.5 : li / (NL - 1)) - 0.5) * spread * width + (f2 - 0.5) * 0.05 * width
         + 0.024 * width * Math.sin(ts * 0.051 + f1 * TAU) + 0.014 * width * Math.sin(ts * 0.113 + f3 * TAU);
  LRX[li] = (0.045 + f3 * 0.115) * scl * width * dz;
  LRY[li] = (0.11 + f4 * 0.44 + en * 0.16) * scl * height * dz * (1 + 0.13 * Math.sin(ts * (0.083 + f4 * 0.071) + f2 * TAU));
  LRO[li] = shearA * ((NL < 2 ? 0.5 : li / (NL - 1)) - 0.5) + (f2 - 0.5) * 0.20;
  // transverse kink mode: each loop rings at its own rate, so the arcade never re-phases
  LKK[li] = 0.034 * width * dz * (0.4 + en) * Math.sin(ts * (0.29 + f3 * 0.31) + f1 * TAU);
}
// point on loop li at u in [0,1]; also its d(arc)/du and d(height)/du
const lpt = (li, u) => {
  const a = PI * u, ro = LRO[li], cr = Math.cos(ro), sr = Math.sin(ro);
  const lx = LRX[li] * Math.cos(a) + LKK[li] * Math.sin(a);
  const ly = LRY[li] * Math.sin(a);                                // local height, up
  return [LX[li] + lx * cr - ly * sr, limbY - (ly * cr + lx * sr)];
};
const lder = (li, u) => {
  const a = PI * u, ro = LRO[li], cr = Math.cos(ro), sr = Math.sin(ro);
  const dlx = -PI * LRX[li] * Math.sin(a) + PI * LKK[li] * Math.cos(a);
  const dly = PI * LRY[li] * Math.cos(a);
  const dwx = dlx * cr - dly * sr, dwy = dly * cr + dlx * sr;      // dwy = d(height)/du, up
  return [Math.sqrt(dwx * dwx + dwy * dwy), dwy];
};

// ---- coarse glow field: splat the loops in, then upscale (the cheap volumetric trick) ------
const BW = 168, BH = Math.max(56, Math.round(BW * height / width));
if (!S.g || S.key !== width + 'x' + height) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.key = width + 'x' + height;
  S.FL = new Float32Array(BW * BH); S.HZ = new Float32Array(BW * BH); S.hzKey = null;
}
const g = S.g, FL = S.FL, HZ = S.HZ;
const bsx = BW / width, bsy = BH / height;

if (S.hzKey !== S.key + ':' + sd) {                                // static plate grain
  S.hzKey = S.key + ':' + sd;
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) HZ[j * BW + i] = fr2(i * 2.7 + 1.3, j * 5.1 + 7.9);
}
FL.fill(0);
const splat = (bx, by, rad, amp) => {
  const x0 = Math.max(0, Math.floor(bx - rad)), x1 = Math.min(BW - 1, Math.ceil(bx + rad));
  const y0 = Math.max(0, Math.floor(by - rad)), y1 = Math.min(BH - 1, Math.ceil(by + rad));
  const ir2 = 1 / (rad * rad * 0.42);
  for (let y = y0; y <= y1; y++) { const dy = y - by; for (let x = x0; x <= x1; x++) { const dx = x - bx, q = (dx * dx + dy * dy) * ir2; if (q < 7) FL[y * BW + x] += amp * Math.exp(-q); } }
};
const NU = 48;
for (let li = 0; li < NL; li++) {
  const dz = LDZ[li];
  const rad = (1.5 + 2.6 * dz) * scl;
  const amp = (0.030 + en * 0.045) * (0.35 + dz * 0.85);
  for (let k = 0; k <= NU; k++) {
    const u = k / NU, pq = lpt(li, u);
    // loops are brightest at their feet, where the heating is
    const foot = 1 + 1.5 * Math.exp(-u * u * 26) + 1.5 * Math.exp(-(1 - u) * (1 - u) * 26);
    splat(pq[0] * bsx, pq[1] * bsy, rad, amp * foot);
  }
}
// the limb itself, and the diffuse corona that sits over the whole active region
for (let i = 0; i < BW; i++) splat(i, limbY * bsy, 4.5 * scl, 0.052 + en * 0.030);
splat(arcX * bsx, (limbY - 0.10 * height) * bsy, BH * 0.55, (0.030 + en * 0.028) * (1 + 0.16 * Math.sin(K.t * 0.071)));

// ---- palettes ----
let sky, cLo, cMi, cHi, rainC;
if (style === 'euv_teal') { sky = [0.012, 0.030, 0.034]; cLo = h2rgb(178, 0.95, 0.30); cMi = h2rgb(166, 0.80, 0.72); cHi = h2rgb(150, 0.16, 1.0); rainC = h2rgb(52, 0.72, 1.0); }
else if (style === 'halpha') { sky = [0.030, 0.014, 0.020]; cLo = h2rgb(P.hue - 32, 0.94, 0.26); cMi = h2rgb(P.hue - 26, 0.86, 0.66); cHi = h2rgb(P.hue - 10, 0.30, 1.0); rainC = h2rgb(P.hue - 34, 0.95, 0.90); }
else if (style === 'schematic') { sky = [0.030, 0.042, 0.066]; cLo = h2rgb(196, 0.72, 0.34); cMi = h2rgb(192, 0.60, 0.62); cHi = h2rgb(188, 0.22, 0.92); rainC = [1.0, 0.96, 0.86]; }
else if (style === 'xray') { sky = [0.028, 0.028, 0.030]; cLo = [0.20, 0.20, 0.21]; cMi = [0.56, 0.56, 0.56]; cHi = [0.98, 0.98, 0.97]; rainC = [0.06, 0.06, 0.07]; }
else { sky = [0.030, 0.020, 0.012]; cLo = h2rgb(P.hue - 16, 0.96, 0.28); cMi = h2rgb(P.hue, 0.82, 0.70); cHi = h2rgb(P.hue + 16, 0.16, 1.0); rainC = h2rgb(P.hue - 32, 0.90, 0.95); }

// value noise -> fbm, for the diffuse corona and the moss on the disk
const vn = (x, y) => {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const ux = xf * xf * (3 - 2 * xf), uy = yf * yf * (3 - 2 * yf);
  const a = fr2(xi, yi), b = fr2(xi + 1, yi), c = fr2(xi, yi + 1), d = fr2(xi + 1, yi + 1);
  return (a * (1 - ux) + b * ux) * (1 - uy) + (c * (1 - ux) + d * ux) * uy;
};
const fbm = (x, y) => vn(x, y) * 0.55 + vn(x * 2.03 + 11.3, y * 2.03 + 5.7) * 0.29 + vn(x * 4.11 + 3.9, y * 4.11 + 17.1) * 0.16;

g.loadPixels();
const gp = g.pixels;
const gam = style === 'schematic' ? 1.5 : 1.0;
const lF = limbY / height, aF = arcX / width;
const diskK = style === 'schematic' ? 0.10 : (style === 'xray' ? 0.42 : 1.0);
const hazeK = style === 'schematic' ? 0.42 : (style === 'xray' ? 0.72 : 1.0);
for (let p = 0; p < BW * BH; p++) {
  const bi = p % BW, bj = (p - bi) / BW;
  const fx = (bi + 0.5) / BW, fy = (bj + 0.5) / BH;
  let v = FL[p];
  v = 1 - Math.exp(-v * (1.5 + en * 1.1));                         // saturating, so the feet don't blow out
  if (gam !== 1) v = Math.pow(v, gam);

  // the diffuse corona — an active region is never sitting on black, it sits in its own halo,
  // and that halo is turbulent, so it drifts and is the frame's broadest moving element
  const hz = fbm(fx * 3.4 + ts * 0.032 + dr1 * 0.05, fy * 3.4 - ts * 0.021);
  const hz2 = fbm(fx * 8.5 - ts * 0.045, fy * 8.5 + ts * 0.028 + dr2 * 0.04);
  const above = Math.max(0, lF - fy);
  const halo = Math.exp(-Math.pow((fx - aF) / 0.60, 2));
  const diffuse = (0.060 + 0.40 * hz + 0.15 * hz2) * Math.exp(-above / 0.62)
                * (0.46 + 0.54 * halo) * (0.60 + en * 0.62) * hazeK;
  v = v + diffuse * (1 - v);

  // below the limb: the disk itself, carpeted in EUV moss at the feet of everything above
  if (fy > lF) {
    const dd = (fy - lF) / Math.max(0.02, 1 - lF);
    const moss = 0.40 + 0.44 * fbm(fx * 13.0 + ts * 0.042, fy * 30.0 - ts * 0.030) + 0.16 * (hz2 - 0.5);
    const dv = moss * Math.min(1, dd * 7 + 0.30) * (0.6 + en * 0.5) * diskK;
    v = v + dv * (1 - v);
  }

  v += (HZ[p] - 0.5) * 0.035;
  v = v < 0 ? 0 : (v > 1 ? 1 : v);
  let R, G2, B;
  if (v < 0.30) { const u = v / 0.30; R = sky[0] + (cLo[0] - sky[0]) * u; G2 = sky[1] + (cLo[1] - sky[1]) * u; B = sky[2] + (cLo[2] - sky[2]) * u; }
  else if (v < 0.68) { const u = (v - 0.30) / 0.38; R = cLo[0] + (cMi[0] - cLo[0]) * u; G2 = cLo[1] + (cMi[1] - cLo[1]) * u; B = cLo[2] + (cMi[2] - cLo[2]) * u; }
  else { const u = (v - 0.68) / 0.32; R = cMi[0] + (cHi[0] - cMi[0]) * u; G2 = cMi[1] + (cHi[1] - cMi[1]) * u; B = cMi[2] + (cHi[2] - cMi[2]) * u; }
  const o = 4 * p;
  gp[o] = R < 0 ? 0 : (R > 1 ? 255 : R * 255);
  gp[o + 1] = G2 < 0 ? 0 : (G2 > 1 ? 255 : G2 * 255);
  gp[o + 2] = B < 0 ? 0 : (B > 1 ? 255 : B * 255);
  gp[o + 3] = 255;
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

const aMul = P.alpha / 100;
const css = (c, a) => 'rgba(' + Math.round(Math.min(255, c[0] * 255)) + ',' + Math.round(Math.min(255, c[1] * 255)) + ',' + Math.round(Math.min(255, c[2] * 255)) + ',' + Math.min(1, Math.max(0, a)).toFixed(3) + ')';

// ---- sharp loop cores at full res ----------------------------------------------------------
push();
if (style !== 'xray') blendMode(ADD);
noFill();
for (let li = 0; li < NL; li++) {
  const dz = LDZ[li];
  strokeWeight(Math.max(0.6, (0.8 + dz * 1.9) * scl));
  const cc = style === 'xray' ? [0.02, 0.02, 0.03] : cHi;
  drawingContext.strokeStyle = css(cc, (0.10 + dz * 0.24) * (0.4 + en * 0.8) * aMul);
  stroke(0, 0, 100, 1);
  beginShape();
  for (let k = 0; k <= NU; k++) { const q = lpt(li, k / NU); vertex(q[0], q[1]); }
  endShape();
}
pop();

// ---- the rain -------------------------------------------------------------------------------
const NDMAX = 220;
const ND = Math.min(NDMAX, Math.round(40 + dens * 140 + en * 40));
if (!S.RU || S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.RU = new Float64Array(NDMAX); S.RV = new Float64Array(NDMAX); S.RL = new Int32Array(NDMAX);
  S.RA = new Float64Array(NDMAX); S.RM = new Float64Array(NDMAX); S.rc = 0;
  for (let d = 0; d < NDMAX; d++) S.RA[d] = -1;
}
const RU = S.RU, RV = S.RV, RL = S.RL, RA = S.RA, RM = S.RM;
const gAcc = (0.55 + en * 1.35) * 0.30;                            // gravity along the field line
const spawn = d => {
  const c = (S.rc = (S.rc + 1) % 100000);
  RL[d] = Math.floor(fr(c * 1.7 + 3.3) * NL) % Math.max(1, NL);
  RU[d] = 0.5 + (fr(c * 5.9 + 11.1) - 0.5) * 0.40;                 // condenses near the apex, either side
  RV[d] = (fr(c * 3.1 + 7.7) - 0.5) * 0.006;
  RA[d] = 0;
  RM[d] = 0.5 + fr(c * 9.3 + 2.1) * 0.9;                           // blob mass -> size + brightness
};
push();
if (style !== 'xray') blendMode(ADD);
noStroke();
for (let d = 0; d < ND; d++) {
  if (RA[d] < 0) { spawn(d); RA[d] = fr(d * 13.1 + 5) * 6; }       // stagger the first fill
  RA[d] += dt;
  const li = RL[d];
  if (li >= NL) { spawn(d); continue; }
  // integrate ALONG THE ARC: a_s = -g * (dy/du)/(ds/du) — zero at the apex, full at the foot
  const dv = lder(li, RU[d]);
  const dsdu = Math.max(1e-6, dv[0]);
  const aS = -gAcc * (dv[1] / dsdu) * width;
  RV[d] += aS * dt / width;
  RV[d] *= 1 - Math.min(0.4, 0.55 * dt);                            // a little drag
  RU[d] += (RV[d] / dsdu) * width * dt;
  if (RU[d] <= 0.004 || RU[d] >= 0.996 || RA[d] > 90) { spawn(d); continue; }

  const q = lpt(li, RU[d]);
  const dz = LDZ[li];
  const cond = Math.min(1, RA[d] * 0.85);                           // it takes a moment to condense
  const foot = Math.min(1, Math.min(RU[d], 1 - RU[d]) / 0.06);      // swallowed at the footpoint
  const br = cond * foot * (0.45 + en * 0.75) * (0.35 + dz * 0.8) * RM[d];
  const rr = (0.0050 + RM[d] * 0.0060) * scl * Math.min(width, height) * dz;
  if (br < 0.02) continue;

  // a tail, dragged back up the field line the way it came
  const sp = Math.abs(RV[d]);
  const tl = Math.min(0.10, sp * 1.9);
  if (tl > 0.004) {
    const back = RU[d] - Math.sign(RV[d]) * tl;
    const qb = lpt(li, Math.min(0.999, Math.max(0.001, back)));
    drawingContext.fillStyle = css(rainC, 0.20 * br * aMul);
    const dxq = q[0] - qb[0], dyq = q[1] - qb[1], Lq = Math.hypot(dxq, dyq) || 1;
    const nx = -dyq / Lq * rr * 0.85, ny = dxq / Lq * rr * 0.85;
    beginShape();
    vertex(q[0] + nx, q[1] + ny); vertex(q[0] - nx, q[1] - ny); vertex(qb[0], qb[1]);
    endShape(CLOSE);
  }
  drawingContext.fillStyle = css(rainC, Math.min(1, 0.62 * br) * aMul);
  fill(0, 0, 100, 1);
  ellipse(q[0], q[1], rr * 2, rr * 2);
  // where it lands, the leg lights up
  if (RU[d] < 0.10 || RU[d] > 0.90) {
    drawingContext.fillStyle = css(cHi, 0.10 * br * (1 - foot) * aMul);
    ellipse(q[0], q[1], rr * 9, rr * 9);
  }
}
pop();

// audio adds on top of a baseline that already carries itself
if (A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  drawingContext.fillStyle = css(cHi, Math.min(0.16, A.bass * 0.13 + K.pulse * 0.03) * aMul);
  ellipse(arcX, limbY, width * 1.1, height * 0.55);
  pop();
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;

const D = { energy:.6, scale:1, density:.5, speed:1, hue:34, x:.5, y:.5, doors:.55, style:'concrete', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

// ---- real-time dolly. bay content is keyed on ABSOLUTE index -> never re-phases
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.30 + .34*K.intensity + .30*P.energy) * .62;
const trav = S.z - Math.floor(S.z), base = Math.floor(S.z);

// ---- incommensurate camera drift (motion floor, no audio required)
const dx = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dy = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9);
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.42 + .58*P.energy) * (.55 + .5*K.intensity) + bass*.35;

const vx = cl(P.x,.1,.9)*width  + u*.030*P.energy*dx;
const vy = cl(P.y,.2,.8)*height + u*.020*P.energy*dy;
const f = u*1.0;
const RW = u*.50*P.scale, CH = u*.50*P.scale, FH = u*.42*P.scale;
const NB = Math.round(7 + P.density*8);
const SP = u*.66, ZMIN = SP*.20;
const sty = P.style, H = ((P.hue%360)+360)%360;

// raking light wanders down the corridor on incommensurate rates
const lz = S.z + 3.2 + 2.4*Math.sin(K.t*.113) + 1.2*Math.sin(K.t*.271+1.3) + .7*Math.sin(K.t*.617+2.2);

const PX = (X,Z) => vx + f*X/Z;
const PY = (Y,Z) => vy + f*Y/Z;

// ---- style tone tables ------------------------------------------------------
const paper = (sty==='engraving');
const line  = (sty==='blueprint');
function ground(){
  if (line)     return [212, 62, 20];
  if (paper)    return [40, 10, 86];
  if (sty==='sodium')   return [26, 40, 7];
  if (sty==='clinical') return [162, 8, 78];
  return [H, 7, 10];
}
// surface: face 0=leftwall 1=rightwall 2=ceiling 3=floor
function surf(face, bi, near, lit){
  const tv = fr(bi*3.7 + face*0.31);
  const rake = (face===0 ? .78 : face===1 ? .42 : face===2 ? .30 : .62);
  let v = (.20 + .62*lit*rake + .10*tv) * (.55 + .45*near);
  if (sty==='sodium')   return [26 + tv*8, cl(58 - 26*lit,10,80), cl(4 + 62*v*1.35, 3, 78)];
  if (sty==='clinical') return [162, cl(5 + 7*tv,0,16), cl(56 + 34*v + 8*tv, 30, 93)];
  if (paper)            return [40, 8, cl(93 - 34*(1-v)*1.1, 44, 96)];
  if (line)             return [212, 60, cl(10 + 18*v, 8, 34)];
  return [H, cl(6 + 10*tv,2,20), cl(6 + 74*v, 4, 84)];  // concrete
}
function ink(a){
  if (line)  { stroke(190, 30, 100, a); }
  else if (paper) { stroke(30, 22, 16, a); }
  else if (sty==='sodium') { stroke(30, 55, 40, a*.7); }
  else if (sty==='clinical') { stroke(168, 14, 40, a*.55); }
  else { stroke(H, 8, 88, a*.35); }
}

// ---- ground -----------------------------------------------------------------
