// incommensurate K.t rates.
// ---------------------------------------------------------------------------
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(100, Math.round(BW * height / width));
const N = BW * BH;
const FY = Math.round(BH * 0.32);
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.h = new Float32Array(BW); S.hn = new Float32Array(BW);
  S.M = new Float32Array(N); S.Mb = new Float32Array(N);
  S.init = false; S.seedUsed = null;
}

const sd = P.seed | 0;
function hs3(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
let RR = 0, GG = 0, BB = 0;
function hsv(h, s, v) {
  h = h - Math.floor(h);
  const i = Math.floor(h * 6), f = h * 6 - i, p2 = v * (1 - s), q = v * (1 - f * s), w = v * (1 - (1 - f) * s);
  if (i === 0) { RR = v; GG = w; BB = p2; } else if (i === 1) { RR = q; GG = v; BB = p2; }
  else if (i === 2) { RR = p2; GG = v; BB = w; } else if (i === 3) { RR = p2; GG = q; BB = v; }
  else if (i === 4) { RR = w; GG = p2; BB = v; } else { RR = v; GG = p2; BB = q; }
}

const h = S.h, hn = S.hn, M = S.M, Mb = S.Mb;

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  for (let i = 0; i < BW; i++) h[i] = (hs3(i, 5, 2) - 0.5) * 0.9;
  M.fill(0); Mb.fill(0.5);
  S.Y = 0;
}

const tt = K.t;

// ---- KS front: A sets the selected cell spacing and drifts, so cells must split/merge ----
const Abase = 0.42 + P.density * 1.85;
const Adr = Abase * (1 + 0.22 * Math.sin(tt * 0.043) + 0.12 * Math.sin(tt * 0.107 + 1.9) + 0.07 * Math.sin(tt * 0.191 + 0.6));
const Bc = 1.0, Cc = 1.0;
const dt = 0.035;
const sub = Math.max(1, Math.min(6, Math.round(2 + P.speed * 2)));
for (let st = 0; st < sub; st++) {
  let mean = 0;
  for (let i = 0; i < BW; i++) {
    const i1 = i > 0 ? i - 1 : BW - 1, i2 = i > 1 ? i - 2 : BW - 2 + i;
    const j1 = i < BW - 1 ? i + 1 : 0, j2 = i < BW - 2 ? i + 2 : i + 2 - BW;
    const hxx = h[i1] - 2 * h[i] + h[j1];
    const hxxxx = h[i2] - 4 * h[i1] + 6 * h[i] - 4 * h[j1] + h[j2];
    const hx = (h[j1] - h[i1]) * 0.5;
    let v = h[i] + dt * (-Adr * hxx - Bc * hxxxx - Cc * hx * hx);
    if (!(v > -40)) v = -40; else if (v > 40) v = 40;
    hn[i] = v; mean += v;
  }
  mean /= BW;
  for (let i = 0; i < BW; i++) h[i] = hn[i] - mean;   // KS drifts; keep the front centred
}

// normalise the front profile for display + recording
let hmin = 1e9, hmax = -1e9;
for (let i = 0; i < BW; i++) { const v = h[i]; if (v < hmin) hmin = v; if (v > hmax) hmax = v; }
const hrng = Math.max(0.6, hmax - hmin);

// ---- pulling rate drifts -> banded microstructure ----
const Vb = (3.0 + P.speed * 6.0) * (1 + P.band * (0.42 * Math.sin(tt * 0.071) + 0.24 * Math.sin(tt * 0.151 + 1.1) + 0.13 * Math.sin(tt * 0.263 + 2.3)));
const V = Math.max(1.2, Vb) * (0.85 + K.swell * 0.2 + A.lowmid * 0.35);
const bandv = Math.max(0, Math.min(1, (V / (3.0 + P.speed * 6.0) - 0.4) * 0.9));

S.Y += V / 60;
let rows = 0;
while (S.Y >= 1 && rows < 8) {
  S.Y -= 1; rows++;
  M.copyWithin((FY + 1) * BW, FY * BW, (BH - 1) * BW);
  Mb.copyWithin((FY + 1) * BW, FY * BW, (BH - 1) * BW);
  const o = FY * BW;
  for (let i = 0; i < BW; i++) {
    const dpt = (hmax - h[i]) / hrng;              // 0 at a cell tip, 1 in the deepest groove
    M[o + i] = dpt;
    Mb[o + i] = bandv;
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const style = P.style;
const hb = P.hue / 360 + (K.section | 0) * 0.023 + Math.sin(tt * 0.017) * 0.018;
const gain = 0.45 + P.energy * 1.1 + A.rms * 0.3;
const gr = P.grain;
const amp = Math.min(BH * 0.11, 3.2 + P.energy * 3.0);
for (let i = 0; i < BW; i++) {
  const fy = FY - ((h[i] - (hmin + hmax) * 0.5) / hrng) * 2 * amp;   // live front profile
  const im = i > 0 ? i - 1 : BW - 1, ip = i < BW - 1 ? i + 1 : 0;
  for (let j = 0; j < BH; j++) {
    const p = j * BW + i;
    const th = (hs3(i, j, 71) - 0.5) * 0.09 * gr;
    let r, gg, b;
    const dfr = j - fy;
    if (dfr < 0) {
      // ---- liquid: thermal gradient + solute boundary layer piled ahead of the front
      const dep = Math.min(1, -dfr / (BH * 0.34));
      const sol = Math.max(0, 1 - (-dfr) * 0.09);          // solute pile-up hugging the front
      const shim = (hs3(i, (j + (tt * 9 | 0)) % BH, 13) - 0.5) * 0.05;
      if (style === 'micrograph') { const v = 0.10 + dep * 0.05 + sol * 0.06 + shim; r = v; gg = v * 0.99; b = v * 0.97; }
      else if (style === 'dic') { const v = 0.46 + sol * 0.05 + shim * 0.5; r = v; gg = v * 0.995; b = v * 1.01; }
      else if (style === 'schematic') { const v = 0.055 + sol * 0.05; r = v * 0.5; gg = v * 0.9; b = v * 1.9; }
      else {
        hsv(hb + 0.52, 0.62 - dep * 0.12, 1);
        const v = (0.09 + dep * 0.05 + sol * 0.10) * (0.7 + gain * 0.4);
        r = RR * v; gg = GG * v; b = BB * v;
      }
    } else {
      // ---- mushy zone then solid: read the space-time record
      const rec = j >= FY ? M[p] : M[FY * BW + i];
      const bnd = j >= FY ? Mb[p] : bandv;
      const mush = Math.max(0, 1 - dfr * 0.20);            // latent-heat glow behind the front
      const groove = Math.pow(rec, 1.35);
      if (style === 'micrograph') {
        // etched longitudinal section: bright cell cores, dark intercellular grooves
        const v = (0.62 - groove * 0.50 + bnd * 0.07) * (0.55 + gain * 0.45);
        r = v * 1.0 + mush * 0.30; gg = v * 0.985 + mush * 0.28; b = v * 0.94 + mush * 0.24;
      } else if (style === 'dic') {
        // Nomarski relief: form from light only, pseudo-3D off the groove gradient
        const gx = (j >= FY ? M[p - (i > 0 ? 1 : 1 - BW)] : rec) - (j >= FY ? M[p + (i < BW - 1 ? 1 : 1 - BW)] : rec);
        const gy = j > FY && j < BH - 1 ? M[p - BW] - M[p + BW] : 0;
        const rel = 0.5 + (gx * 2.6 + gy * 1.1) * (0.6 + gain * 0.7);
        const v = Math.max(0, Math.min(1, rel)) * 0.72 + 0.12 + bnd * 0.04;
        r = v * 1.0 + mush * 0.16; gg = v * 0.99 + mush * 0.16; b = v * 0.96 + mush * 0.14;
      } else if (style === 'schematic') {
        // blueprint: the groove trajectories and the live front, nothing else
        const line = Math.max(0, groove - 0.52) * 2.1;
        const fl = Math.max(0, 1 - Math.abs(dfr) * 0.5);
        r = 0.06 + line * 0.42 * gain + fl * 0.30;
        gg = 0.09 + line * 0.80 * gain + fl * 0.56;
        b = 0.15 + line * 1.0 * gain + fl * 0.74;
      } else {
        // phase_field (default): solid warm, grooves solute-dark, hot mushy zone,
        // pulling-rate bands laid horizontally through the microstructure
        hsv(hb + 0.02 + bnd * 0.05, 0.30 + groove * 0.30, 1);
        const v = (0.30 + (1 - groove) * 0.52 + bnd * 0.09) * (0.55 + gain * 0.5);
        r = RR * v; gg = GG * v; b = BB * v;
        hsv(hb + 0.09, 0.55, 1);
        r += RR * mush * 0.42 * gain; gg += GG * mush * 0.42 * gain; b += BB * mush * 0.42 * gain;
      }
    }
    const o = 4 * p;
    px[o] = Math.max(0, Math.min(255, (r + th) * 255));
    px[o + 1] = Math.max(0, Math.min(255, (gg + th) * 255));
    px[o + 2] = Math.max(0, Math.min(255, (b + th) * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh2 = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh2) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh2);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;

const D = { scale:1, density:.55, energy:.6, speed:1, hue:35, x:.5, y:.5, seed:0, style:'1bit', act:'boil' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const TAU = 6.28318530718, cl = (v,a,b)=>v<a?a:v>b?b:v;
const fr = i=>{ const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };

// ---- working buffer keyed on aspect bucket ----
const asp = width/height;
const LS = 180;
let bw, bh;
if (asp>=1){ bw=LS; bh=Math.max(8,Math.round(LS/asp)); } else { bh=LS; bw=Math.max(8,Math.round(LS*asp)); }
const bkey = bw+'x'+bh;
if (!S.buf || S.bkey!==bkey){ if (S.buf && S.buf.remove) S.buf.remove(); S.buf = createGraphics(bw,bh); S.buf.pixelDensity(1); S.bkey = bkey; }
const g = S.buf;

// ---- 8x8 Bayer ----
if (!S.bay){
  const b=[0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21];
  const bb=new Float32Array(64); for (let i=0;i<64;i++) bb[i]=(b[i]+.5)/64; S.bay=bb;
}

// ---- seeded wave field ----
const nW=4;
if (S.seedUsed!==P.seed){
  S.seedUsed=P.seed; const W=[]; let sw=0;
  for (let i=0;i<nW;i++){
    const ang=fr(i*9)*TAU, f=1.2+fr(i*9+1)*3.5, w=.6+fr(i*9+5)*.6;
    W.push({ fx:Math.cos(ang)*f, fy:Math.sin(ang)*f, ph:fr(i*9+2)*TAU, sp:(fr(i*9+3)*.8+.3)*(fr(i*9+4)<.5?-1:1), w:w });
    sw+=w;
  }
  S.W=W; S.sumW=sw;
}

// ---- ink/paper palette keyed style+hue ----
const style=P.style, hue=cl(P.hue,0,360);
const ckey=style+'|'+Math.round(hue);
if (S.ckey!==ckey){
  S.ckey=ckey;
  const rgb=(h,s,b)=>{ const c=color(h,s,b); return [c.levels[0],c.levels[1],c.levels[2]]; };
  if (style==='amber'){ S.ink=rgb(hue||35,92,96); S.pap=rgb(30,80,5); }
  else if (style==='blueprint'){ S.pap=rgb(212,78,26); S.ink=rgb(200,16,96); }
  else if (style==='newsprint'){ S.pap=rgb(44,14,92); S.ink=rgb(0,0,9); }
  else if (style==='xray'){ S.pap=rgb(216,60,5); S.ink=rgb(205,12,97); }
  else if (style==='thermal'){ const hp=[[240,90,20],[210,90,55],[300,70,60],[10,90,75],[45,95,96]]; S.heat=hp.map(a=>rgb(a[0],a[1],a[2])); }
  else { S.pap=rgb(0,0,95); S.ink=rgb(0,0,7); }
}

// ---- per-frame field params ----
const spd=cl(P.speed,.2,4), en=cl(P.energy,0,1), sc=cl(P.scale,.3,3);
const freqScale = .5 + sc*1.1;
const cover = cl(P.density,0,1);
const bias = (cover-.5)*.9;
const contrast = .7 + en*1.6;
const pump = K.pulse*.05*en + (A.rms||0)*.22 + (A.bass||0)*.1;
const drift = P.act==='drift' ? K.t*spd*.06 : 0;
const ripple = P.act==='ripple';
const rf = 8 + sc*6;
const rph = K.t*spd*2;
const W=S.W, bay=S.bay;
const norm = .5 / (S.sumW + (ripple?.9:0));
const px0 = cl(P.x,0,1), py0 = cl(P.y,0,1);

// ---- render dither ----
g.loadPixels();
const px=g.pixels, invW=1/(bw-1), invH=1/(bh-1);
const ink=S.ink, pap=S.pap, heat=S.heat;
let idx=0;
for (let yy=0; yy<bh; yy++){
  const ny=yy*invH, row=(yy&7)*8;
  for (let xx=0; xx<bw; xx++){
    const nx=xx*invW, ax=nx+drift;
    let raw=0;
    for (let i=0;i<nW;i++){ const w=W[i]; raw += Math.sin(ax*w.fx*freqScale + ny*w.fy*freqScale + w.ph + K.t*spd*w.sp)*w.w; }
    if (ripple){ const dx=(nx-px0)*asp, dy=ny-py0; const d=Math.sqrt(dx*dx+dy*dy); raw += Math.sin(d*rf - rph)*.9; }
    let f = .5 + raw*norm;
    f = .5 + (f-.5)*contrast + bias + pump;
    if (f<0) f=0; else if (f>1) f=1;
    const th = bay[row + (xx&7)];
    let r,gg,bb2;
    if (style==='thermal'){
      let q = f + (th-.5)/5; if (q<0) q=0; else if (q>.999) q=.999;
      const lvl=(q*5)|0; const c=heat[lvl]; r=c[0]; gg=c[1]; bb2=c[2];
    } else {
      const c = f>th ? ink : pap; r=c[0]; gg=c[1]; bb2=c[2];
    }
    px[idx]=r; px[idx+1]=gg; px[idx+2]=bb2; px[idx+3]=255; idx+=4;
  }
}
g.updatePixels();

drawingContext.imageSmoothingEnabled = false;
image(g,0,0,width,height);
drawingContext.imageSmoothingEnabled = true;
blendMode(BLEND);

const D = { density:.5, scale:1, speed:1, energy:.6, hue:205, branch:.5, style:'frost', act:'grow', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:0.6);
const restartEvery = (P.act==='melt')?1:2;
const epoch = Math.floor((K.section||0)/restartEvery);
const cs = Math.max(2.5, u*0.0058*(0.55+P.scale));
const cols = Math.max(8, Math.floor(width/cs));
const rows = Math.max(8, Math.floor(height/cs));
const centerSeed = !(st==='coral' || P.act==='melt');

function paintBg(buf, st, hue){
  buf.noStroke();
  if (st==='ink') buf.background(40, 9, 88);
  else if (st==='coral') buf.background(192, 62, 9);
  else if (st==='circuit') buf.background(160, 45, 5);
  else buf.background(222, 58, 11);
  // faint vignette so it never reads flat
  buf.drawingContext.save();
  const g = buf.drawingContext.createRadialGradient(buf.width/2,buf.height/2,buf.width*0.1, buf.width/2,buf.height/2,buf.width*0.75);
  g.addColorStop(0,'rgba(255,255,255,0.04)'); g.addColorStop(1,'rgba(0,0,0,0.28)');
  buf.drawingContext.fillStyle=g; buf.drawingContext.fillRect(0,0,buf.width,buf.height);
  buf.drawingContext.restore();
}

function stamp(buf,cx,cy,cs,st,P,rad01,u){
  const x=(cx+0.5)*cs, y=(cy+0.5)*cs;
  const r = cs*(0.55 + P.branch*1.0);
  buf.push(); buf.noStroke();
  if (st==='circuit'){
    buf.drawingContext.shadowBlur=6; buf.drawingContext.shadowColor='rgba(80,255,150,0.6)';
    buf.fill((110+rad01*50)%360, 82, 96, 92);
    buf.rectMode(CENTER); buf.rect(x,y,r*0.9,r*0.9);
  } else if (st==='ink'){
    buf.fill(228, 14, 12, 78);
    buf.circle(x + (Math.sin(cx*12.9)*r*0.2), y + (Math.cos(cy*7.3)*r*0.2), r*(0.8+ (Math.sin(cx*3.1+cy)*0.3)));
  } else if (st==='coral'){
    buf.drawingContext.shadowBlur=5; buf.drawingContext.shadowColor='rgba(255,120,90,0.5)';
    buf.fill((14 + rad01*40)%360, 74, 96, 88); buf.circle(x,y,r);
  } else {
    buf.drawingContext.shadowBlur=8; buf.drawingContext.shadowColor='rgba(190,230,255,0.7)';
    buf.fill((P.hue + rad01*28)%360, Math.max(6,22-rad01*14), 92+rad01*8, 88); buf.circle(x,y,r);
  }
  buf.drawingContext.shadowBlur=0; buf.pop();
}

function spawn(S){
  const occ=S.occ, cols=S.cols, rows=S.rows;
  const o = occ.length? occ[(occ.length*S.rnd())|0] : [cols>>1, rows>>1];
  const ang = S.rnd()*Math.PI*2;
  const d = 4 + S.rnd()*11;
  let cx = Math.round(o[0]+Math.cos(ang)*d);
  let cy = Math.round(o[1]+Math.sin(ang)*d);
  cx = Math.max(1, Math.min(cols-2, cx));
  cy = Math.max(1, Math.min(rows-2, cy));
  return {cx:cx, cy:cy, life: 40 + (S.rnd()*70|0)};
}

const key = width+'x'+height+'|'+cs.toFixed(2)+'|'+P.seed+'|'+epoch+'|'+st;
if (S.key !== key){
  S.key = key;
  let z = ((P.seed*2654435761) ^ (epoch*40503)) >>> 0; z = (z+12345)>>>0;
  S.rnd = ()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.cols=cols; S.rows=rows; S.cs=cs;
  S.grid = new Uint8Array(cols*rows);
  S.occ = [];
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(width,height);
  S.buf.colorMode(HSB,360,100,100,100);
  paintBg(S.buf, st, P.hue);
  const seeds = [];
  if (centerSeed) seeds.push([cols>>1, rows>>1]);
  else for (let i=0;i<Math.floor(5+P.density*7);i++) seeds.push([1+Math.floor(S.rnd()*(cols-2)), rows-2]);
  for (let s=0;s<seeds.length;s++){ const sx=seeds[s][0], sy=seeds[s][1]; S.grid[sy*cols+sx]=1; S.occ.push([sx,sy]); stamp(S.buf, sx, sy, cs, st, P, 0.02, u); }
  const NW = Math.floor(24 + P.density*130);
  S.walk = [];
  for (let i=0;i<NW;i++) S.walk.push(spawn(S));
  S.rmax = 3;
}

image(S.buf,0,0);

const grid=S.grid, cc=S.cols, rr=S.rows, occ=S.occ, cs2=S.cs, rnd=S.rnd;
const steps = Math.max(1, Math.round((2 + P.speed*4) * (0.6+intn) + A.bass*4));
noStroke();
if (st!=='ink') blendMode(ADD);
const wl = st==='ink' ? [228,22,20,42] : (st==='circuit'?[135,80,95,50]:(st==='coral'?[16,60,98,46]:[(P.hue)%360,26,98,46]));
for (let i=0;i<S.walk.length;i++){
  let w=S.walk[i];
  for (let s=0;s<steps;s++){
    const r=rnd(); w.cx += (r<0.34?-1:(r<0.67?0:1));
    const r2=rnd(); w.cy += (r2<0.34?-1:(r2<0.67?0:1));
    if (w.cx<1||w.cx>=cc-1||w.cy<1||w.cy>=rr-1||(--w.life)<=0){ S.walk[i]=spawn(S); w=S.walk[i]; continue; }
    const gi=w.cy*cc+w.cx;
    if (grid[gi]){ S.walk[i]=spawn(S); w=S.walk[i]; continue; }
    if (grid[gi-1]||grid[gi+1]||grid[gi-cc]||grid[gi+cc]){
      grid[gi]=1; occ.push([w.cx,w.cy]);
      const dc=w.cx-(cc>>1), dgr=w.cy-(rr>>1); const rad=Math.sqrt(dc*dc+dgr*dgr);
      if (rad>S.rmax) S.rmax=rad;
      stamp(S.buf, w.cx, w.cy, cs2, st, P, rad/Math.max(cc,rr), u);
      S.walk[i]=spawn(S); w=S.walk[i];
      break;
    }
  }
  const tw = wl[3]*(0.45 + 0.4*Math.sin(K.t*3+i*0.7) + A.treble*0.9);
  fill(wl[0],wl[1],wl[2], Math.max(0,tw));
  circle((w.cx+0.5)*cs2,(w.cy+0.5)*cs2, cs2*0.85);
}

if (centerSeed){
  const gx=(cc>>1)*cs2, gy=(rr>>1)*cs2;
