function ddot(x0,y0,x1,y1,per,a){
  const L=Math.hypot(x1-x0,y1-y0); if(L<.5) return;
  const ux=(x1-x0)/L, uy=(y1-y0)/L;
  sc(C.ctr, a); strokeWeight(Math.max(.4,u*.0008));
  for (let s=0;s<L;s+=per){
    line(x0+ux*s,y0+uy*s,x0+ux*Math.min(L,s+per*.58),y0+uy*Math.min(L,s+per*.58));
    const c=Math.min(L,s+per*.74); line(x0+ux*c,y0+uy*c,x0+ux*Math.min(L,c+per*.09),y0+uy*Math.min(L,c+per*.09));
  }
}
function wheelSpokes(cx,cy,r,ang,n,a){
  sc(C.line, a); strokeWeight(Math.max(.5,u*.0012));
  for (let i=0;i<n;i++){ const b=ang+i*T2/n;
    line(cx+Math.cos(b)*r*.20, cy+Math.sin(b)*r*.20, cx+Math.cos(b)*r*.86, cy+Math.sin(b)*r*.86); }
  noFill(); ellipse(cx,cy,r*.40,r*.40); ellipse(cx,cy,r*1.72,r*1.72);
}
// a plain toothed wheel for the going train
function trainWheel(cx,cy,r,ang,Z,dim){
  if (schem){ sc(C.line, 30*dim); strokeWeight(Math.max(.4,u*.0008)); noFill(); ellipse(cx,cy,r*2,r*2);
    sc(C.ctr, 40*dim); line(cx-r*.2,cy,cx+r*.2,cy); line(cx,cy-r*.2,cx,cy+r*.2); return; }
  noStroke(); fc(C.body, (C.add?16:74)*dim);
  beginShape();
  for (let k=0;k<Z;k++){ const a0=k*T2/Z+ang, ht=Math.PI/(2*Z);
    const put=(rr,aa)=>vertex(cx+Math.cos(aa)*rr*r, cy+Math.sin(aa)*rr*r);
    put(1-2.4/Z,a0-ht*1.3); put(1+1.9/Z,a0-ht*.5); put(1+1.9/Z,a0+ht*.5); put(1-2.4/Z,a0+ht*1.3);
  }
  endShape(CLOSE);
  noFill(); sc(C.line, (C.add?40:66)*dim); strokeWeight(Math.max(.4,u*.0010));
  beginShape();
  for (let k=0;k<Z;k++){ const a0=k*T2/Z+ang, ht=Math.PI/(2*Z);
    const put=(rr,aa)=>vertex(cx+Math.cos(aa)*rr*r, cy+Math.sin(aa)*rr*r);
    put(1-2.4/Z,a0-ht*1.3); put(1+1.9/Z,a0-ht*.5); put(1+1.9/Z,a0+ht*.5); put(1-2.4/Z,a0+ht*1.3);
  }
  endShape(CLOSE);
  const ns = r > u*.05 ? 5 : 4;
  sc(C.line, 52*dim); strokeWeight(Math.max(.4,u*.0009));
  for (let i=0;i<ns;i++){ const b=ang*1.0+i*T2/ns;
    line(cx+Math.cos(b)*r*.18, cy+Math.sin(b)*r*.18, cx+Math.cos(b)*r*.80, cy+Math.sin(b)*r*.80); }
  noFill(); ellipse(cx,cy,r*.36,r*.36);
  noStroke(); fc(C.jewel, 84*dim); ellipse(cx,cy,r*.13,r*.13);
}

