    sc(C.hatch, 40); strokeWeight(Math.max(.4,u*.0007));
    for (let i=-4;i<=4;i++){ const yy=by+i*bobR*.22, hx=Math.sqrt(Math.max(0,bobR*bobR-(yy-by)*(yy-by)));
      line(bx-hx, yy, bx+hx, yy); }
    sc(C.line, 76); strokeWeight(Math.max(.6,u*.0013));
