// ---- LAYER 4: the anchor — deadbeat pallets with concentric locking faces ---
{
  const pt = rp*.085;
  push(); translate(ax2, ay2); rotate(th);
  if (!schem){
    noStroke(); fc(C.body, C.add?30:95);
    beginShape();
    for (let i=0;i<=18;i++){ const a3 = aL + (aR-aL)*(i/18); vertex(Math.cos(a3)*(rp+pt), Math.sin(a3)*(rp+pt)); }
    for (let i=18;i>=0;i--){ const a3 = aL + (aR-aL)*(i/18); vertex(Math.cos(a3)*(rp-pt), Math.sin(a3)*(rp-pt)); }
    endShape(CLOSE);
    noFill(); sc(C.line, 94); strokeWeight(Math.max(.8, u*.0022*(.6+.7*NRG)));
    beginShape();
    for (let i=0;i<=18;i++){ const a3 = aL + (aR-aL)*(i/18); vertex(Math.cos(a3)*(rp+pt), Math.sin(a3)*(rp+pt)); }
    for (let i=18;i>=0;i--){ const a3 = aL + (aR-aL)*(i/18); vertex(Math.cos(a3)*(rp-pt), Math.sin(a3)*(rp-pt)); }
    endShape(CLOSE);
