      line(Math.cos(a3)*(rp-pt), Math.sin(a3)*(rp-pt), Math.cos(a3+.16)*(rp+pt), Math.sin(a3+.16)*(rp+pt)); }
  } else {
    noFill(); sc(C.line, 84); strokeWeight(Math.max(.7,u*.0016));
    beginShape(); for (let i=0;i<=18;i++){ const a3=aL+(aR-aL)*(i/18); vertex(Math.cos(a3)*rp, Math.sin(a3)*rp); } endShape();
  }
  // the two pallets. The LOCKING face is an arc concentric with this arbor -> deadbeat.
  for (const sgn of [0,1]){
    const a3 = sgn ? aR : aL;
    const px2 = Math.cos(a3)*rp, py2 = Math.sin(a3)*rp;
    const lock = locked && ((sgn===0) === (sIdx%2===0));
    if (!schem){
      push(); translate(px2,py2); rotate(a3 + (sgn?  .62 : -.62));
