const D = { energy:.6, scale:1, density:.5, speed:1, hue:206, x:.5, y:.5, spin:.6, style:'technical', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const TAU = Math.PI*2;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

const sty = P.style;
const bp = (sty==='blueprint'), paper = (sty==='engraving'), xr = (sty==='xray'), ano = (sty==='anodized');
const tech = (sty==='technical');
const H = ((P.hue%360)+360)%360;
const NP = Math.max(3, Math.round(4 + cl(P.density,0,1)*6));
const R = u*.30*cl(P.scale,.3,2.2);

// ---- seeded assembly --------------------------------------------------------
if (S.sdU !== sd || S.npU !== NP){
  S.sdU = sd; S.npU = NP;
  const kinds = ['flange','gear','ring','hub','cone','spring','nut','disc'];
  const ps = []; let z = 0;
  for (let i=0;i<NP;i++){
    const q = fr(i*9.7+1);
    let kd = kinds[Math.floor(fr(i*4.3+2)*kinds.length)];
    if (i===0) kd = 'flange';
    if (i===NP-1) kd = (q>.5) ? 'nut' : 'flange';
    const len = (kd==='hub') ? .28 + q*.55 : (kd==='spring') ? .30 + q*.34 : .07 + q*.16;
    const r0 = (kd==='hub') ? .18 + fr(i*7.1+3)*.14 : (kd==='nut') ? .26 + fr(i*7.1+3)*.12 : .42 + fr(i*7.1+3)*.55;
