  if (therm) return [cl(258 - 240*v, 10, 262), cl(66 - 16*v, 20, 80), cl(8 + 82*v, 4, 96)];
  if (rust)  return [cl(16 + 18*tv - 5*v, 4, 42), cl(34 + 30*tv - 12*v, 6, 64), cl(6 + 76*v, 4, 92)];
  if (sty === 'sodium') return [cl(28 + 10*tv, 18, 44), cl(54 - 22*v, 8, 68), cl(4 + 76*v, 3, 92)];
  return [(HU - 8 + 10*tv + 360)%360, cl(20 - 11*v + 6*tv, 2, 30), cl(7 + 78*v, 4, 95)];
}
function ink(a){ if (wire) stroke(190, 30, 100, a); else stroke((HU+2)%360, 12, 84, a*.30); }
const RY = [1, .58, .10], RG = [.055, .05, .075];
const LTH = sty === 'sodium' ? 32 : rust ? 34 : therm ? 24 : (HU-160+360)%360;

// ---- the volume: light from above dying into the deep (banded) --------------------
noStroke();
const NBD = 32;
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1);
  const c = tone(cl(.34*Math.pow(1-s, 1.6) + .06, 0, 1), fr(i*3.1));
  fill(c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.7, 0, 100));
  rect(0, s*height - 1.5, width, height/NBD + 3);
}

// ---- far wall: corrugated steel ribs — texture, never a flat fill -----------------
{
  const NRB = 22;
  for (let i=0; i<NRB; i++){
    const x0 = -XW + (2*XW)*(i/NRB), x1 = -XW + (2*XW)*((i+1)/NRB);
    const rv = (.16 + .13*Math.abs(Math.cos(i*1.9))) * (.5+.5*gl);
    const c = mixc(tone(cl(rv,0,1), fr(i*7.3)), HAZE, .62*fogA);
    if (wire){ noFill(); ink(34); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
    poly([x0, camY-LEV*8, ZW, x1, camY-LEV*8, ZW, x1, camY+LEV*8, ZW, x0, camY+LEV*8, ZW]);
  }
}

// ---- full-height stanchions tying the levels together ----------------------------
for (let i=0;i<5;i++){
  const cx2 = -XW*.55 + fr(i*7.7+3)*XW*1.1, cz2 = u*1.9 + fr(i*13.3+9)*(ZW - u*2.4);
  const p = pt2(cx2, camY, cz2);
  if (!p) continue;
  if (p[0] < -u*.1 || p[0] > width + u*.1) continue;
  const hz = cl(p[2]/(ZW*.9), 0, 1);
  const rw = Math.max(1.2, f*(u*.026)/p[2]);
  const NSf = cl(Math.round(rw/(u*.008)), 1, 5);
  for (let s2=0; s2<NSf; s2++){
    const p0 = -1 + 2*s2/NSf, p1 = -1 + 2*(s2+1)/NSf, pm = (p0+p1)*.5;
    const lamb = cl(.20 + .84*Math.cos((pm - .45)*1.45), 0, 1);
    let c = mixc(tone(cl(lamb*(.34+.42*gl), 0, 1), fr(i*3.1)), HAZE, hz*fogA);
    if (rust) c = mixc(c, [14, 62, 30], fr(i*11.1)*.5);
    if (wire){ noFill(); ink(44); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
    rect(p[0] + p0*rw, 0, (p1-p0)*rw + 1.1, height);
  }
}

// ---- gather the catwalks, depth-sort, paint far -> near ----------------------------
const decks = [];
for (let j = lc-NL; j <= lc+NL; j++){
  const nHere = fr(j*3.7) < .30 ? 2 : 1;
  for (let c2=0; c2<nHere; c2++){
    const r0 = fr(j*13.1 + c2*29.3);
    const alongX = fr(j*5.9 + c2*17.7) < .6;
    const zc = u*.85 + r0*(ZW - u*1.5);
    const xc = -XW*.45 + fr(j*11.3 + c2*7.1)*XW*.9;
    const Y = j*LEV;
    const p = pt2(alongX ? 0 : xc, Y, alongX ? zc : u*1.9);
    if (!p) continue;
    decks.push([p[2], j, c2, alongX, zc, xc, Y]);
  }
}
decks.sort((a,b) => b[0]-a[0]);
const ND = Math.min(decks.length, 11);

strokeWeight(Math.max(1, u*.0014));
for (let q = decks.length-ND; q < decks.length; q++){
  const dd = decks[q], rz = dd[0], j = dd[1], alongX = dd[3], zc = dd[4], xc = dd[5], Y = dd[6];
  const hz = cl(rz/(ZW*.9), 0, 1);
  const tv = fr(j*31.7 + dd[2]*3.3);
  const lit = cl(.34 + .58*Math.exp(-Math.pow(j - ly0, 2)*.30), 0, 1);
  const below = (Y > camY);                       // below the eye => we read the grating
  const rr = fr(j*19.1);

  // run endpoints
  const aA = alongX ? -XW*.8 : u*.9, aB = alongX ? XW*.8 : ZW - u*.35;
  const gA = (t2) => alongX ? [aA + (aB-aA)*t2, zc] : [xc, aA + (aB-aA)*t2];
  const wA = CW*.5;
  const e0 = gA(0), e1 = gA(1);
  const nx = alongX ? 0 : 1, nz = alongX ? 1 : 0;   // deck half-width direction

  // ---- deck: drawn translucent so it reads as open grating, then slatted
  const dv = (below ? (.24 + .30*lit) : (.09 + .10*lit)) * (.5+.55*gl) + .06*tv;
  let c = mixc(tone(cl(dv,0,1), tv), HAZE, hz*fogA);
  if (rust) c = mixc(c, [14, 62, 30], rr*.5);
  if (wire){ noFill(); ink(48); } else { noStroke(); fill(c[0], c[1], c[2], below ? 84 : 100); }
  poly([e0[0]-nx*wA, Y, e0[1]-nz*wA, e1[0]-nx*wA, Y, e1[1]-nz*wA,
        e1[0]+nx*wA, Y, e1[1]+nz*wA, e0[0]+nx*wA, Y, e0[1]+nz*wA]);
  if (below && !wire && hz < .55){
    ink(30); noFill();
    for (let s2=1; s2<8; s2++){
      const t2 = s2/8, g2 = gA(t2);
      poly([g2[0]-nx*wA, Y, g2[1]-nz*wA, g2[0]+nx*wA, Y, g2[1]+nz*wA]);
    }
  }
  // ---- edge fascia / stringer beam
  if (!wire){
    const c2 = mixc(tone(cl(dv*.55 + .05, 0, 1), tv), HAZE, hz*fogA);
    noStroke(); fill(c2[0], c2[1], c2[2], 100);
    for (let sg=-1; sg<=1; sg+=2){
      poly([e0[0]+nx*wA*sg, Y, e0[1]+nz*wA*sg, e1[0]+nx*wA*sg, Y, e1[1]+nz*wA*sg,
            e1[0]+nx*wA*sg, Y+DT, e1[1]+nz*wA*sg, e0[0]+nx*wA*sg, Y+DT, e0[1]+nz*wA*sg]);
    }
  }
  // ---- handrails: two bands + a toe board, both sides
  for (let sg=-1; sg<=1; sg+=2){
    for (let ri=0; ri<3; ri++){
      const yy = Y - RH*RY[ri], hgt = RH*RG[ri];
      const rv = (ri===2 ? .16 : .34 + .30*lit) * (.5+.55*gl);
      let rc = mixc(tone(cl(rv,0,1), tv), HAZE, hz*fogA);
      if (rust) rc = mixc(rc, [12, 66, 30], rr*.6);
      if (wire){ noFill(); ink(52); } else { noStroke(); fill(rc[0], rc[1], rc[2], 100); }
      poly([e0[0]+nx*wA*sg, yy, e0[1]+nz*wA*sg, e1[0]+nx*wA*sg, yy, e1[1]+nz*wA*sg,
            e1[0]+nx*wA*sg, yy+hgt, e1[1]+nz*wA*sg, e0[0]+nx*wA*sg, yy+hgt, e0[1]+nz*wA*sg]);
    }
    // stanchions
    for (let s2=0; s2<4; s2++){
      const g2 = gA((s2+.5)/4);
      const p = pt2(g2[0]+nx*wA*sg, Y, g2[1]+nz*wA*sg);
      if (!p) continue;
      const rw = Math.max(.9, f*(u*.008)/p[2]);
      const yb = vcy + f*(Y - camY)/p[2], yt = vcy + f*(Y - RH - camY)/p[2];
      let sc = mixc(tone(cl((.26 + .26*lit)*(.5+.55*gl), 0, 1), tv), HAZE, hz*fogA);
      if (wire){ noFill(); ink(46); } else { noStroke(); fill(sc[0], sc[1], sc[2], 100); }
      rect(p[0] - rw*.5, Math.min(yb,yt), rw, Math.abs(yb-yt));
    }
  }
  // ---- a clamped work lamp, seeded, with a bloom and a pool on the deck
  if (!wire && fr(j*23.1 + dd[2]*5.3) < cl(P.lamps,0,1)*.8){
    const g2 = gA(.28 + .44*fr(j*9.7));
    const p = pt2(g2[0], Y - RH*1.02, g2[1]);
    if (p){
      const fl = .62 + .38*Math.sin(K.t*(.5 + fr(j*2.7)*.6) + j*2.1);
      push(); blendMode(ADD); noStroke();
      for (let i=4;i>=1;i--){
        fill(LTH, therm?70:24, 100, cl(2.2 + 4.6*gl*fl, 0, 15));
        ellipse(p[0], p[1], f*(u*.30)/p[2]*i*.45, f*(u*.30)/p[2]*i*.45);
      }
      pop(); blendMode(BLEND);
      noStroke(); fill(LTH, therm?60:14, cl(66 + 30*gl*fl, 10, 98), 100);
      const rw = Math.max(1.4, f*(u*.014)/p[2]);
      ellipse(p[0], p[1], rw*2, rw*2);
    }
  }
}

// ---- the shaft of light from above (partial frame, ADD, no flash) ------------------
if (!wire){
  push(); blendMode(ADD); noStroke();
  const sx2 = vcx + u*.30*Math.sin(K.t*.043) + u*.12*Math.sin(K.t*.107+1.7);
  for (let i=5;i>=1;i--){
    fill(LTH, therm?60:20, 100, 1.5 + 2.8*gl);
    quad(sx2 - u*.05*i, 0, sx2 + u*.05*i, 0, sx2 + u*.17*i, height, sx2 - u*.17*i, height);
  }
  pop(); blendMode(BLEND);
}

// ---- cached grain + vignette --------------------------------------------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9000, Math.floor(width*height/230));
  for (let i=0;i<N;i++){
    const px = Math.abs((Math.sin(i*12.9898)*43758.5453)%1)*width;
    const py = Math.abs((Math.sin(i*78.233+2.1)*43758.5453)%1)*height;
    g.fill(0,0, (i%2) ? 100 : 0, 6);
    g.rect(px, py, 1.7, 1.7);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.10;
    g.fill(0,0,0, 1.2 + 4.2*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);

const D = { energy: .6, density: .55, scale: 1, speed: 1, wear: .5, lamps: .6, hue: 40, x: .5, y: .5, style: 'brass', act: 'steady', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const md = (a, n) => ((a % n) + n) % n;
// integer hash — finalize with >>> (>> sign-extends and caps the hash at 0.5)
function h2(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + (P.seed | 0) * 1442695041) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function h1(i) { return h2(i | 0, 0x3ac9); }
function vn1(x, r) { const ix = Math.floor(x), fx = x - ix, ux = fx*fx*(3-2*fx); const a = h2(ix, r), b = h2(ix+1, r); return a + (b-a)*ux; }

const en = clp(P.energy, 0, 1), dens = clp(P.density, 0, 1), wear = clp(P.wear, 0, 1);
const W = width, H = height, u = Math.min(W, H);
const hs = P.hue - 40;

const ST = {
  brass:    { pan:[38,16,30], dial:[42,20,78], face:[40,10,88], ink:[35,30,14], nd:[8,80,58],  bez:[42,34,58], lamp:[40,90,96], txt:[38,22,70], glow:.55 },
  cold_war: { pan:[95,14,26], dial:[80,14,62], face:[74,12,70], ink:[100,26,16], nd:[6,84,52],  bez:[90,10,44], lamp:[110,80,92], txt:[86,18,64], glow:.5 },
  bakelite: { pan:[18,34,17], dial:[30,12,66], face:[34,8,76],  ink:[20,34,12], nd:[2,86,50],  bez:[24,30,36], lamp:[26,88,94], txt:[28,22,58], glow:.45 },
  xray:     { pan:[210,52,17], dial:[206,40,26], face:[204,36,30], ink:[190,4,96], nd:[190,4,99], bez:[200,30,44], lamp:[186,70,96], txt:[196,14,86], glow:.9 }
};
const st = ST[P.style] || ST.brass;
const PNH = md(st.pan[0] + hs, 360), DIH = md(st.dial[0] + hs, 360), FAH = md(st.face[0] + hs, 360), INH = md(st.ink[0] + hs, 360), NDH = md(st.nd[0] + hs, 360), BEH = md(st.bez[0] + hs, 360), LAH = md(st.lamp[0] + hs, 360), TXH = md(st.txt[0] + hs, 360);
const wire = P.style === 'xray';

// ---- act dramaturgy: what the plant is doing over minutes ----
let load = 0.5, jit = 1, alarmP = 0.06;
if (P.act === 'startup') { load = clp(md(K.t * 0.006, 1) * 1.25, 0, 1); jit = 1.5; alarmP = 0.10; }
else if (P.act === 'excursion') { load = 0.55 + 0.42 * Math.sin(K.t * 0.037); jit = 2.6; alarmP = 0.34; }
else { load = 0.46 + 0.16 * Math.sin(K.t * 0.029) + 0.10 * Math.sin(K.t * 0.071); }
load = clp(load + K.intensity * 0.18 - 0.09, 0, 1);

const LBLS = ['MAIN BUS','FEEDWATER','TURBINE','EXCITER','COOLANT A','COOLANT B','STATOR','MANIFOLD','PLENUM','REACTOR','CONDENSER','SCRUBBER','GOVERNOR','PENSTOCK','BUS TIE','INTERTIE','PREHEAT','SURGE','TAILRACE','DRUM'];
const UNITS = ['kV','m³/h','RPM','A','°C','bar','Hz','%','MW','kPa'];

// ---- panel layout: a seeded grid of instrument tiles (cached) ----
const COLS = clp(4 + Math.round(dens * 3), 4, 7), ROWS = clp(3 + Math.round(dens * 1), 3, 4);
const lkey = COLS + 'x' + ROWS + '|' + (P.seed | 0);
if (!S.tiles || S.lkey !== lkey) {
  const T = [];
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const i = r * COLS + c, k = h1(i * 5 + 1);
    // kind: 0 round gauge, 1 edgewise meter, 2 counter drum, 3 annunciator block, 4 strip recorder
    let kind = k < .46 ? 0 : k < .64 ? 1 : k < .76 ? 2 : k < .9 ? 3 : 4;
    T.push({ c, r, i, kind,
      lbl: LBLS[Math.floor(h1(i * 5 + 2) * LBLS.length)], unit: UNITS[Math.floor(h1(i * 5 + 3) * UNITS.length)],
      w0: 0.30 + h1(i * 5 + 4) * 0.5, ph: h1(i * 5 + 5) * TAU, red: 0.68 + h1(i * 7 + 6) * 0.22,
      w2: 0.17 + h1(i * 7 + 7) * 0.33, base: h1(i * 7 + 8) });
  }
  S.tiles = T; S.lkey = lkey; S.nkey = '';
}
const tiles = S.tiles;

// ---- cached brushed-panel plate (local coords -> scales live with P.scale) ----
const pkey = P.style + '|' + Math.round(P.hue) + '|' + (P.seed | 0) + '|' + wear.toFixed(2);
if (!S.plate || S.pkey !== pkey) {
  if (S.plate && S.plate.remove) S.plate.remove();
  const BX = 512, BY = 384;
  const g = createGraphics(BX, BY); g.pixelDensity(1); g.colorMode(g.HSB, 360, 100, 100, 100);
  g.noStroke(); g.background(PNH, st.pan[1], st.pan[2]);
  for (let i = 0; i < 2600; i++) {                     // brushed grain
    g.fill(PNH, st.pan[1] * .7, st.pan[2] * (.55 + h1(i * 2 + 11) * 1.1), 12);
    g.rect(h1(i * 2 + 12) * BX, h1(i * 2 + 13) * BY, 14 + h1(i * 2 + 14) * 60, 1);
  }
  for (let i = 0; i < 260; i++) {                      // scuffs, oxide bloom, thumb wear
    const a = 5 + h1(i * 3 + 21) * 14 * wear;
    g.fill(PNH, st.pan[1] * (1.4 + h1(i * 3 + 22)), st.pan[2] * (h1(i * 3 + 23) > .5 ? 1.5 : .55), a);
    g.ellipse(h1(i * 3 + 24) * BX, h1(i * 3 + 25) * BY, 8 + h1(i * 3 + 26) * 54 * wear, 6 + h1(i * 3 + 27) * 40 * wear);
  }
  S.plate = g; S.pkey = pkey;
  // The dial FACE is static — bezel, dial, graduations, numerals. Bake it once and
  // share it across every round gauge; only the needle and the red band are live.
  if (S.face && S.face.remove) S.face.remove();
  const FS = 256, fc = FS * .5, FR = FS * .435;
  const f = createGraphics(FS, FS); f.pixelDensity(1); f.colorMode(f.HSB, 360, 100, 100, 100);
  f.clear(); f.noStroke();
  f.fill(BEH, st.bez[1], st.bez[2] * 1.5); f.ellipse(fc, fc, FR * 2.3);
  f.fill(BEH, st.bez[1], st.bez[2] * .55); f.ellipse(fc, fc, FR * 2.12);
  if (!wire) { f.fill(DIH, st.dial[1], st.dial[2]); f.ellipse(fc, fc, FR * 2); }
  else { f.noFill(); f.stroke(INH, st.ink[1], st.ink[2], 60); f.strokeWeight(1.5); f.ellipse(fc, fc, FR * 2); }
  const fa0 = Math.PI * .78, fa1 = Math.PI * 2.22;
  for (let k = 0; k <= 20; k++) {
    const a = fa0 + (fa1 - fa0) * k / 20, maj = k % 5 === 0;
    f.stroke(INH, st.ink[1], st.ink[2], maj ? 92 : 46); f.strokeWeight(maj ? FR * .05 : 1.4);
    f.line(fc + Math.cos(a) * FR * (maj ? .62 : .72), fc + Math.sin(a) * FR * (maj ? .62 : .72), fc + Math.cos(a) * FR * .84, fc + Math.sin(a) * FR * .84);
    if (maj) { f.noStroke(); f.fill(INH, st.ink[1], st.ink[2], 82); f.textAlign(f.CENTER, f.CENTER); f.textSize(FR * .17); f.text(k * 5, fc + Math.cos(a) * FR * .45, fc + Math.sin(a) * FR * .45); }
  }
  S.face = f;
}

// ---- damped needle physics: honest instrument motion, integrated in S ----
let dt = K.t - (S.lastT == null ? K.t - 1 / 60 : S.lastT);
if (dt < 0 || dt > 0.2) dt = 1 / 60;                    // tolerate t0 reset
S.lastT = K.t;
if (!S.n || S.n.length !== tiles.length) { S.n = new Float32Array(tiles.length); S.v = new Float32Array(tiles.length); S.nkey = ''; }
function target(t0) {
  // each channel drifts on its OWN incommensurate rates — nothing re-phases at 8 s
  const s = t0.i;
  let v = t0.base * .18 + load * .62;
  v += 0.16 * Math.sin(K.t * t0.w0 * .9 + t0.ph) + 0.09 * Math.sin(K.t * t0.w2 * 2.3 + t0.ph * 1.7);
  v += 0.06 * jit * (vn1(K.t * (1.1 + t0.w0) + s * 13.7, 7) - .5) * 2;
  v += (K.pulse * .05 + A.rms * .5 + A.bass * .22) * en;   // audio rides ON TOP of the baseline
  return clp(v, 0.02, 1.02);
}
for (let i = 0; i < tiles.length; i++) {
  const tg = target(tiles[i]);
  const k = 62, c = 9.4;                               // spring + damping -> real needle overshoot
  const acc = (tg - S.n[i]) * k - S.v[i] * c;
  S.v[i] += acc * dt; S.n[i] += S.v[i] * dt;
  if (!Number.isFinite(S.n[i])) { S.n[i] = tg; S.v[i] = 0; }
}

// =================== composite ===================
const sc = clp(P.scale, .4, 2.2);
const PW = 0.94 * W * sc, PH2 = 0.88 * H * sc;
const px0 = P.x * W - PW * .5, py0 = P.y * H - PH2 * .5;
const tw = PW / COLS, th = PH2 / ROWS;
const dc = drawingContext;

noStroke();
background(PNH, st.pan[1], st.pan[2] * .45);
image(S.plate, px0, py0, PW, PH2);

// bay dividers + rivets: the panel reads as bolted-together sections
stroke(PNH, st.pan[1] * .6, st.pan[2] * 1.9, 46); strokeWeight(Math.max(1, u * .0016));
for (let c = 1; c < COLS; c++) line(px0 + c * tw, py0, px0 + c * tw, py0 + PH2);
for (let r = 1; r < ROWS; r++) line(px0, py0 + r * th, px0 + PW, py0 + r * th);
noFill();

textFont('Courier New');
for (let i = 0; i < tiles.length; i++) {
  const t0 = tiles[i], x = px0 + t0.c * tw + tw * .5, y = py0 + t0.r * th + th * .5;
  const R = Math.min(tw, th) * .34;
  const v = clp(S.n[i], 0, 1.05);
  const alarm = v > t0.red;

  // engraved tile label
  noStroke(); fill(TXH, st.txt[1], st.txt[2], 78);
  textAlign(CENTER, TOP); textSize(clp(Math.min(u * .0105, th * .11), 5, 17));
  text(t0.lbl, x, py0 + t0.r * th + th * .055);

  if (t0.kind === 0) {                                  // ---- round moving-coil gauge ----
    const a0 = Math.PI * .78, a1 = Math.PI * 2.22;
    noStroke();
    image(S.face, x - R * 1.149, y - R * 1.149, R * 2.299, R * 2.299);   // baked bezel+dial+scale
    // red band at the top of the scale (per-tile, so it stays live)
    noFill(); stroke(NDH, st.nd[1], st.nd[2], 74); strokeWeight(R * .10);
    arc(x, y, R * 1.62, R * 1.62, a0 + (a1 - a0) * t0.red, a1);
    noStroke(); fill(INH, st.ink[1], st.ink[2], 70);
    textAlign(CENTER, CENTER); textSize(clp(R * .19, 4, 16)); text(t0.unit, x, y + R * .48);
    // needle + counterweight + hub
    const an = a0 + (a1 - a0) * clp(v, 0, 1);
    stroke(alarm ? NDH : INH, alarm ? st.nd[1] : st.ink[1], alarm ? st.nd[2] * 1.6 : st.ink[2], 96);
    strokeWeight(Math.max(1.4, R * .055));
    line(x - Math.cos(an) * R * .17, y - Math.sin(an) * R * .17, x + Math.cos(an) * R * .80, y + Math.sin(an) * R * .80);
    noStroke(); fill(BEH, st.bez[1], st.bez[2] * 1.1); ellipse(x, y, R * .20);
    if (!wire) {                                        // convex glass: a raking sheen, drifting slowly
      const gl = Math.sin(K.t * 0.067 + t0.c * .7);
      blendMode(ADD); noStroke(); fill(0, 0, 100, 5.5 + 3 * en);
      push(); translate(x, y); rotate(-0.75 + 0.22 * gl);
      ellipse(gl * R * .35, -R * .40, R * 1.5, R * .34); pop();
      blendMode(BLEND);
    }
  } else if (t0.kind === 1) {                           // ---- edgewise bar meter ----
    const bw = tw * .62, bh = th * .17;
    noStroke(); fill(BEH, st.bez[1], st.bez[2] * .5); rect(x - bw * .5 - 3, y - bh * .5 - 3, bw + 6, bh + 6, 2);
    fill(DIH, st.dial[1], st.dial[2] * .5); rect(x - bw * .5, y - bh * .5, bw, bh);
    for (let k = 0; k <= 10; k++) { stroke(INH, st.ink[1], st.ink[2], k % 5 === 0 ? 80 : 34); strokeWeight(1); const xx = x - bw * .5 + bw * k / 10; line(xx, y - bh * .5, xx, y - bh * .2); }
    noStroke(); fill(alarm ? NDH : LAH, alarm ? st.nd[1] : st.lamp[1] * .8, alarm ? st.nd[2] * 1.5 : st.lamp[2] * .8, 86);
    rect(x - bw * .5, y - bh * .5 + bh * .3, bw * clp(v, 0, 1), bh * .7);
    stroke(INH, st.ink[1], st.ink[2], 96); strokeWeight(Math.max(1.5, bh * .12));
    const nx = x - bw * .5 + bw * clp(v, 0, 1);
    line(nx, y - bh * .62, nx, y + bh * .62);
    noStroke(); fill(TXH, st.txt[1], st.txt[2], 72); textAlign(CENTER, TOP); textSize(clp(u * .0095, 4, 15));
    text((v * 100).toFixed(1) + ' ' + t0.unit, x, y + bh * .8);
  } else if (t0.kind === 2) {                           // ---- rolling counter drum ----
    const dw = Math.min(tw * .12, th * .30), dh = dw * 1.5, nd = 5;
    const tot = v * 90000 + K.t * (9 + t0.base * 40);
    noStroke(); fill(BEH, st.bez[1], st.bez[2] * .4); rect(x - dw * nd * .5 - 4, y - dh * .5 - 4, dw * nd + 8, dh + 8, 2);
    for (let d = 0; d < nd; d++) {
      const place = Math.pow(10, nd - 1 - d);
      const val = tot / place;                          // each wheel rolls continuously into the next
      const fracd = md(val, 1), digit = Math.floor(md(val, 10));
      const dx = x - dw * nd * .5 + d * dw;
      dc.save(); dc.beginPath(); dc.rect(dx, y - dh * .5, dw, dh); dc.clip();
      noStroke(); fill(DIH, st.dial[1], st.dial[2] * .22); rect(dx, y - dh * .5, dw, dh);
      const roll = (place === 1) ? fracd : (fracd > .9 ? (fracd - .9) * 10 : 0);
      fill(FAH, st.face[1] * .3, st.face[2], 92);
      textAlign(CENTER, CENTER); textSize(dh * .62);
      const o0 = roll > 0.004 ? -1 : 0, o1 = roll > 0.004 ? 1 : 0;
      for (let o = o0; o <= o1; o++) text(String(md(digit + o, 10) | 0), dx + dw * .5, y + (o + roll) * dh);
      dc.restore();
      stroke(0, 0, 0, 40); strokeWeight(1); noFill(); rect(dx, y - dh * .5, dw, dh);
    }
    noStroke(); fill(TXH, st.txt[1], st.txt[2], 66); textAlign(CENTER, TOP); textSize(clp(u * .0092, 4, 15));
    text(t0.unit, x, y + dh * .75);
  } else if (t0.kind === 3) {                           // ---- annunciator lamp block ----
    const gw = 2, gh2 = 2, cwv = tw * .30, chv = th * .16;
    for (let a = 0; a < 4; a++) {
      const ax = x + ((a % gw) - .5) * cwv, ay = y + (Math.floor(a / gh2) - .5) * chv;
      const lit = h1(t0.i * 13 + a) < alarmP * 3.2 + (v > t0.red ? .5 : 0) * (a === 3 ? 1 : 0);
      const flick = lit ? (0.78 + 0.22 * vn1(K.t * 2.1 + a * 7 + t0.i, 31)) : 0;
      noStroke();
      fill(BEH, st.bez[1], st.bez[2] * .45); rect(ax - cwv * .46, ay - chv * .42, cwv * .92, chv * .84, 2);
      const lh = a === 3 ? NDH : (a === 0 ? md(LAH + 80, 360) : LAH);
      fill(lh, st.lamp[1] * (lit ? 1 : .5), st.lamp[2] * (lit ? flick : .16) * clp(P.lamps, 0, 1) + st.lamp[2] * .1, 92);
      rect(ax - cwv * .40, ay - chv * .35, cwv * .80, chv * .70, 1);
      fill(0, 0, lit ? 8 : 30, lit ? 78 : 48); textAlign(CENTER, CENTER); textSize(clp(chv * .28, 3, 11));
      text(['TRIP','LOCK','AUTO','ALARM'][a], ax, ay);
      if (lit && st.glow > 0) {
        blendMode(ADD); noStroke(); fill(lh, st.lamp[1] * .6, 100, 13 * st.glow * flick * clp(P.lamps, 0, 1));
        ellipse(ax, ay, cwv * 1.7, chv * 1.6); blendMode(BLEND);
      }
    }
  } else {                                              // ---- miniature strip-chart recorder ----
    const rw = tw * .70, rh = th * .34;
    noStroke(); fill(BEH, st.bez[1], st.bez[2] * .45); rect(x - rw * .5 - 3, y - rh * .5 - 3, rw + 6, rh + 6, 2);
    fill(DIH, st.dial[1] * .6, st.dial[2] * 1.05); rect(x - rw * .5, y - rh * .5, rw, rh);
    stroke(NDH, st.nd[1] * .6, st.nd[2], 30); strokeWeight(1);
    for (let k = 1; k < 5; k++) line(x - rw * .5, y - rh * .5 + rh * k / 5, x + rw * .5, y - rh * .5 + rh * k / 5);
    // the trace is a pure function of time -> it scrolls honestly, no history buffer needed
    noFill(); stroke(INH, st.ink[1], st.ink[2], 92); strokeWeight(Math.max(1, u * .0013));
    beginShape();
    const NPTS = 22;
    for (let k = 0; k <= NPTS; k++) {
      const tt = K.t - (1 - k / NPTS) * 9;
      let vv = t0.base * .18 + (0.46 + 0.16 * Math.sin(tt * 0.029) + 0.10 * Math.sin(tt * 0.071)) * .62;
      vv += 0.16 * Math.sin(tt * t0.w0 * .9 + t0.ph) + 0.09 * Math.sin(tt * t0.w2 * 2.3 + t0.ph * 1.7);
      vertex(x - rw * .5 + rw * k / NPTS, y + rh * .5 - clp(vv, 0, 1) * rh);
    }
    endShape();
    noStroke(); fill(NDH, st.nd[1], st.nd[2] * 1.4, 92); ellipse(x + rw * .5, y + rh * .5 - clp(v, 0, 1) * rh, Math.max(2.5, u * .004));
  }

  if (alarm && st.glow > 0) {   // alarm halo — soft and slow, never a flash (NO STROBE)
    blendMode(ADD); noStroke();
    fill(NDH, st.nd[1] * .7, 100, 6.5 * st.glow * (0.55 + 0.45 * Math.sin(K.t * 1.9 + i)));
    ellipse(x, y, tw * .9, th * .9); blendMode(BLEND);
  }
}

// toggle switches + knobs along the bottom rail
const nsw = clp(Math.round(COLS * 2.5), 6, 20);
for (let i = 0; i < nsw; i++) {
  const x = px0 + PW * (i + .5) / nsw, y = py0 + PH2 - u * .018;
  const on = h1(i * 3 + 61) + 0.22 * Math.sin(K.t * 0.05 + i) > .5;
  noStroke(); fill(BEH, st.bez[1], st.bez[2] * .5); ellipse(x, y, u * .016, u * .016);
  fill(BEH, st.bez[1] * .5, st.bez[2] * 1.7);
  push(); translate(x, y); rotate(on ? -0.55 : 0.55);
  rect(-u * .0022, -u * .016, u * .0044, u * .017, 2); pop();
  fill(on ? LAH : PNH, on ? st.lamp[1] : st.pan[1], on ? st.lamp[2] * .9 : st.pan[2] * .8, 88);
  ellipse(x, y + u * .014, u * .005);
}

// panel placard
noStroke(); fill(TXH, st.txt[1], st.txt[2], 88);
textAlign(LEFT, BOTTOM); textSize(clp(u * .014, 7, 26));
text('CENTRAL CONTROL  ·  BOARD ' + String((P.seed | 0) % 90 + 10), px0 + u * .012, py0 - u * .010);
textAlign(RIGHT, BOTTOM); textSize(clp(u * .011, 6, 20)); fill(TXH, st.txt[1], st.txt[2] * .8, 70);
text('LOAD ' + (load * 100).toFixed(0) + '%   ' + P.act.toUpperCase(), px0 + PW - u * .012, py0 - u * .010);

// room light raking across the whole board — the broad, slow motion floor
blendMode(ADD);
const sweep = md(K.t * 0.041, 1);
noStroke();
for (let i = 0; i < 8; i++) {
  fill(LAH, 12, 100, 2.6);
  const sx = (sweep * 1.6 - .3) * W;
  push(); translate(sx, H * .5); rotate(-0.36);
  rect(-u * .10 + i * u * .026, -H, u * .022, H * 2); pop();
}
blendMode(BLEND);
noFill(); stroke(0, 0, 0, 26); strokeWeight(u * .11); rect(-u * .055, -u * .055, W + u * .11, H + u * .11);
dc.shadowBlur = 0;
blendMode(BLEND);
if (P.alpha < 100) { noStroke(); fill(PNH, st.pan[1], st.pan[2] * .45, 100 - clp(P.alpha, 0, 100)); rect(0, 0, W, H); }

const D = { energy:.6, scale:1, density:.5, speed:1, hue:96, x:.42, y:.5, teeth:.5, anno:.7, style:'film', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const T2 = Math.PI*2;
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const lp = (a,b,s) => a+(b-a)*s;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);

// ---- palette per style -------------------------------------------------------
function pal(){
  if (sty==='cyanotype') return { g:[212,72,19], body:[210,60,29], line:[200,6,99], ctr:[196,34,84], pitch:[190,42,76], anno:[200,10,92], hatch:[205,48,60], grain:36, add:false, wash:[196,20,80] };
  if (sty==='engraving') return { g:[38,17,73],  body:[36,13,60], line:[28,36,12], ctr:[8,64,40],  pitch:[30,32,28], anno:[28,40,15], hatch:[30,30,24], grain:32, add:false, wash:[44,26,96] };
  if (sty==='xray')      return { g:[228,58,10], body:[H,62,24],  line:[H,26,97], ctr:[12,74,60],  pitch:[168,58,72], anno:[H,14,86], hatch:[H,42,52], grain:18, add:true,  wash:[H,42,66] };
  if (sty==='schematic') return { g:[196,36,9],  body:[196,44,15], line:[178,64,92], ctr:[10,72,70], pitch:[178,72,86], anno:[52,56,88], hatch:[186,42,42], grain:14, add:false, wash:[184,40,60] };
  return { g:[H,15,21], body:[H,11,33], line:[H,4,93], ctr:[10,68,64], pitch:[H,24,70], anno:[H,6,88], hatch:[H,9,56], grain:28, add:false, wash:[H,10,80] };
}
const C = pal();
const sc = (c,a) => { stroke(c[0], c[1], c[2], a*AL); };
const fc = (c,a) => { fill(c[0], c[1], c[2], a*AL); };

// ---- real-time drive: monotonic accumulator + section gear-shift --------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const secN = K.section|0;
let tgt = fr(secN*3.77 + 11)*1.75 - .62;
if (Math.abs(tgt) < .38) tgt = tgt < 0 ? -.38 : .38;
tgt *= (.5 + .8*K.intensity);
if (S.rate == null) S.rate = tgt;
S.rate += (tgt - S.rate) * cl(dt*1.1, 0, 1);
const wob = 1 + .26*Math.sin(K.t*.131) + .17*Math.sin(K.t*.313+1.1) + .09*Math.sin(K.t*.767+2.3);
S.th = (S.th||0) + dt * S.rate * wob * P.speed * (1.0 + 1.9*NRG);
const ths = S.th;

// ---- incommensurate plate drift + breathe (motion floor, no audio needed) -----
const drx = .9*Math.sin(K.t*.137) + .5*Math.sin(K.t*.293+1.7) + .32*Math.sin(K.t*.451);
const dry = .8*Math.sin(K.t*.109+2.1) + .45*Math.sin(K.t*.257+.6) + .28*Math.sin(K.t*.617+1.9);
const zm = 1 + .045*NRG*(Math.sin(K.t*.089) + .6*Math.sin(K.t*.211+1.3));
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.45 + .55*NRG)*(.55 + .5*K.intensity) + S.bs*.3;

// ---- involute-ish tooth profile, cached per tooth count -----------------------
S.prof = S.prof || {};
function profile(Z, internal){
  const kk = Z + (internal ? 'i' : 'e');
  if (S.prof[kk]) return S.prof[kk];
  const ht = Math.PI/(2*Z);
  const ra = internal ? 1 - 2/Z   : 1 + 2/Z;
  const rf = internal ? 1 + 2.5/Z : 1 - 2.5/Z;
  const pts = [];
  for (let k=0;k<Z;k++){
    const a0 = k*T2/Z;
    pts.push([rf,a0-ht*1.30],[1,a0-ht*1.00],[ra,a0-ht*.55],[ra,a0+ht*.55],[1,a0+ht*1.00],[rf,a0+ht*1.30]);
  }
  S.prof[kk] = pts; return pts;
}
function toothPath(cx,cy,rp,Z,ang,internal,rev){
  const pts = profile(Z, internal);
  if (rev) { for (let i=pts.length-1;i>=0;i--){ const a=pts[i][1]+ang, r=pts[i][0]*rp; vertex(cx+Math.cos(a)*r, cy+Math.sin(a)*r); } }
  else     { for (let i=0;i<pts.length;i++){ const a=pts[i][1]+ang, r=pts[i][0]*rp; vertex(cx+Math.cos(a)*r, cy+Math.sin(a)*r); } }
}

// ---- epicyclic sets that actually close: Zr = Zs+2Zp, (Zs+Zr)/np integer ------
const COMBOS = [[18,15,48,3],[24,18,60,4],[20,16,52,4],[30,15,60,3],[16,20,56,4],[24,12,48,6],[36,12,60,4]];
const cb = COMBOS[Math.floor(fr(7.3)*COMBOS.length) % COMBOS.length];
const Zs=cb[0], Zp=cb[1], Zr=cb[2], np=cb[3];
const mod = (.54*u*P.scale)/Zr * zm;
const rs = mod*Zs/2, rpl = mod*Zp/2, rr = mod*Zr/2;
const Rout = rr*(1+2.5/Zr) + mod*1.6;
const ex = cl(P.x,.12,.88)*width  + u*.024*NRG*drx;
const ey = cl(P.y,.12,.88)*height + u*.020*NRG*dry;

// kinematics: ring fixed, sun input, carrier output
const kr = Zs/(Zs+Zr);
const thc = ths*kr;
const b0 = thc;
const thp0 = b0 + Math.PI + Math.PI/Zp - (Zs/Zp)*(ths - b0);
const thr = b0 + Math.PI/Zr + (Zp/Zr)*(thp0 - b0);
const ratio = 1 + Zr/Zs;

// ---- spur chain: each mesh solved from the previous -> geometrically exact ----
const ckey = sd+'|'+cl(P.teeth,0,1).toFixed(3)+'|'+Math.round(P.density*24)+'|'+Math.round(P.scale*80)+'|'+width+'x'+height;
if (S.ck !== ckey){
  S.ck = ckey;
  const Zlo = Math.round(lp(11,17,cl(P.teeth,0,1))), Zhi = Math.round(lp(19,36,cl(P.teeth,0,1)));
  const nch = Math.round(3 + cl(P.density,0,1)*8);
  const ch = [];
  const Z0 = Math.round(lp(Zlo,Zhi,fr(11.7)));
  let bp = -1e9, sx=0, sy=0, sphi=0;
  for (let c=0;c<20;c++){
    const ph = fr(3.1)*T2 + c*T2/20;
    const dd = Rout + mod*Z0/2 + u*.055;
    const nx = ex + Math.cos(ph)*dd, ny = ey + Math.sin(ph)*dd;
    const mg = mod*(Z0/2+1) + u*.03;
    const s = Math.min(nx-mg, width-mg-nx, ny-mg, height-mg-ny);
    if (s > bp){ bp = s; sx = nx; sy = ny; sphi = ph; }
  }
  ch.push({ x:sx, y:sy, Z:Z0, rp:mod*Z0/2, rt:mod*(Z0/2+1), ph:fr(19.1)*T2, drv:0 });
  let prevB = sphi;
  for (let i=1;i<nch;i++){
    const g0 = ch[i-1];
    const Zn = Math.round(lp(Zlo,Zhi,fr(i*5.77+2.3)));
    const rn = mod*Zn/2, rtn = mod*(Zn/2+1);
    const cd = g0.rp + rn;
    let bb = null, bs = -1e18;
    for (let c=0;c<18;c++){
      const b = prevB + (c/17-.5)*2.6 + (fr(i*9.1+c*.37)-.5)*.5;
      const nx = g0.x + Math.cos(b)*cd, ny = g0.y + Math.sin(b)*cd;
      let s = 0;
      const mg = rtn + u*.028;
      if (nx<mg || nx>width-mg || ny<mg || ny>height-mg) s -= 1400;
      s -= 26*Math.abs(((b-prevB+Math.PI)%T2+T2)%T2 - Math.PI);
      const dr = Math.hypot(nx-ex, ny-ey), needr = rtn + Rout + u*.018;
      if (dr < needr) s -= (needr-dr)*14;
      for (let j=0;j<i-1;j++){ const gg=ch[j], dd2=Math.hypot(nx-gg.x, ny-gg.y), need=rtn+gg.rt+u*.014; if (dd2<need) s -= (need-dd2)*11; }
      if (s > bs){ bs = s; bb = b; }
    }
    if (bs < -600) break;
    ch.push({ x:g0.x+Math.cos(bb)*cd, y:g0.y+Math.sin(bb)*cd, Z:Zn, rp:rn, rt:rtn, b:bb, drv:1 });
    prevB = bb;
  }
  S.chain = ch;
}
const chain = S.chain || [];
// resolve chain angles by the external-mesh phase law
chain[0] && (chain[0].ang = thc + chain[0].ph);
for (let i=1;i<chain.length;i++){
  const a=chain[i-1], b=chain[i];
  b.ang = b.b + Math.PI + Math.PI/b.Z - (a.Z/b.Z)*(a.ang - b.b);
}

// ---- cached plate texture ----------------------------------------------------
const gkey = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gkey !== gkey){
  if (S.gr && S.gr.remove) S.gr.remove();
  const gw=170, gh=Math.max(60, Math.round(170*height/Math.max(1,width)));
  const g = createGraphics(gw,gh);
  g.loadPixels();
  for (let y=0;y<gh;y++) for (let x=0;x<gw;x++){
    const c1 = fr(Math.floor(x/9)*13.71 + Math.floor(y/9)*7.33 + 3.1);
    const c2 = fr(Math.floor(x/3)*3.17 + Math.floor(y/3)*11.9 + 8.7);
    const c3 = fr(x*1.13 + y*3.31 + 1.7);
    const v = cl(255*(.42 + .34*c1 + .17*c2 + .07*c3), 0, 255);
    const j = (y*gw+x)*4; g.pixels[j]=v; g.pixels[j+1]=v; g.pixels[j+2]=v; g.pixels[j+3]=255;
  }
  g.updatePixels();
  S.gr = g; S.gkey = gkey;
}

// ---- ground + texture + drafting grid ---------------------------------------
noStroke(); fill(C.g[0], C.g[1], C.g[2], 100); rect(0,0,width,height);
push(); blendMode(MULTIPLY); tint(0,0,100,C.grain); image(S.gr, 0,0, width,height); pop();
blendMode(BLEND); noTint();
const gs = u*.055;
sc(C.hatch, 9*AL + 7*anno); strokeWeight(Math.max(.5,u*.0009));
for (let x=(-drx*u*.01)%gs; x<width; x+=gs) line(x,0,x,height);
for (let y=(-dry*u*.01)%gs; y<height; y+=gs) line(0,y,width,y);

// ---- wandering inspection wash (big soft light, SCREEN) -----------------------
const wx = width*(.5 + .30*Math.sin(K.t*.071) + .13*Math.sin(K.t*.181+2.2));
const wy = height*(.5 + .26*Math.sin(K.t*.097+1.1) + .11*Math.sin(K.t*.233+.4));
push(); blendMode(SCREEN); noStroke();
