const st=P.style;
const Tdrift=K.t*0.08*P.speed;
const wPh=K.t*0.5*P.speed;                                // slow aurora wave through the ground (motion floor insurance)
const buf=S.buf; buf.loadPixels(); const q=buf.pixels;
for (let i=0;i<N4;i++){
