const D = { energy: .6, scale: 1, speed: 1, density: .55, discharge: .5, hue: 205, x: .5, y: .5, style: 'fisk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Meander migration, Ikeda-Parker-Sawai bend theory (simplified) ----------
// Lateral migration at a node = exponentially weighted UPSTREAM curvature, so
// bends both GROW (the bend instability) and TRANSLATE downstream (phase lag).
// When a neck closes on itself the loop is severed -> an oxbow lake is abandoned
// and sinuosity resets. THAT CUTOFF CYCLE is why this never reaches equilibrium.
// Every channel position is printed into a floodplain plate, so the swept belt
// accretes as arcuate scroll bars (Harold Fisk's Mississippi plates) while slow
// overbank burial fades the oldest scars to ghosts -> bounded memory, endless change.
const BW = 768, BH = 432;

const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> : an arithmetic fold would cap at .5
}
function vn(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
  const a = hsh(ix, iy), b = hsh(ix + 1, iy), c = hsh(ix, iy + 1), d2 = hsh(ix + 1, iy + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d2) * u * v;
}
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- style: palette + rendering philosophy ---------------------------------
const st = P.style;
const rot = h => (((h + (P.hue - 205)) % 360) + 360) % 360;
let base, waterC, inkC, barC, belts, grainAmt, lineOnly;
if (st === 'satellite') {           // false-colour NIR: vegetation dark red, water near-black, bars white
  base = [352, 54, 24]; belts = [[10, 52, 32], [24, 46, 40], [350, 48, 27], [35, 38, 46], [2, 46, 35], [16, 40, 43]];
  waterC = [rot(200), 55, 13]; barC = [45, 10, 88]; inkC = [0, 0, 6]; grainAmt = 10; lineOnly = false;
} else if (st === 'survey') {       // aged sepia plate: line over mass, ink hachure, blue water
  base = [40, 30, 62]; belts = [[32, 36, 50], [28, 30, 57], [36, 32, 44], [24, 34, 53], [42, 28, 47], [30, 38, 42]];
  waterC = [rot(205), 62, 42]; barC = [42, 20, 78]; inkC = [28, 44, 16]; grainAmt = 17; lineOnly = true;
} else if (st === 'blueprint') {    // cyanotype schematic: pale drafting lines on prussian ground
  base = [rot(212), 70, 19]; belts = [[rot(196), 34, 58], [rot(186), 26, 70], [rot(206), 40, 50], [rot(176), 22, 78], [rot(216), 36, 56], [rot(190), 30, 64]];
  waterC = [0, 0, 96]; barC = [rot(190), 18, 86]; inkC = [rot(190), 28, 90]; grainAmt = 8; lineOnly = true;
} else {                            // fisk (default): alluvial plate, historic belts in plate inks
  base = [34, 44, 38]; belts = [[178, 54, 58], [38, 62, 64], [350, 46, 58], [86, 46, 50], [210, 40, 56], [292, 38, 52]];
  waterC = [rot(206), 66, 29]; barC = [44, 36, 74]; inkC = [0, 0, 12]; grainAmt = 14; lineOnly = false;
}

// ---- buffers ---------------------------------------------------------------
if (!S.fp) {
  S.fp = createGraphics(BW, BH); S.fp.pixelDensity(1);
  S.fp.colorMode(HSB, 360, 100, 100, 100); S.fp.noStroke();
  S.styleUsed = null; S.seedUsed = null;
}
if (!S.grain || S.grainSeed !== sd) {
  S.grainSeed = sd;
  const g = S.grain || (S.grain = createGraphics(256, 144));
  g.pixelDensity(1); g.loadPixels();
  for (let i = 0; i < 256 * 144; i++) {
    const v = 206 + hsh(i % 256, (i / 256) | 0) * 49;
    const o = i * 4; g.pixels[o] = v; g.pixels[o + 1] = v; g.pixels[o + 2] = v; g.pixels[o + 3] = 255;
  }
  g.updatePixels();
}
if (!S.vig || S.vigKey !== width + 'x' + height) {
  const gd = drawingContext.createRadialGradient(width / 2, height / 2, Math.min(width, height) * 0.26,
                                                 width / 2, height / 2, Math.max(width, height) * 0.74);
  gd.addColorStop(0, 'rgba(0,0,0,0)'); gd.addColorStop(1, 'rgba(0,0,0,0.40)');
  S.vig = gd; S.vigKey = width + 'x' + height;
}

// ---- (re)seed the reach ----------------------------------------------------
function clearPlate() { S.fp.push(); S.fp.noStroke(); S.fp.fill(base[0], base[1], base[2], 100); S.fp.rect(0, 0, BW, BH); S.fp.pop(); }
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed; S.styleUsed = st;
  S.ds = 0.0105;
  S.rx = []; S.ry = [];
  const n0 = Math.round(1 / S.ds);
  for (let i = 0; i <= n0; i++) {
    const u = i / n0;
    S.rx.push(u);
    S.ry.push(0.5 + 0.05 * Math.sin(u * Math.PI * 5.3 + fr(1) * 6.283)
                  + 0.026 * Math.sin(u * Math.PI * 12.7 + fr(2) * 6.283)
                  + (fr(i + 7) - 0.5) * 0.005);
  }
  S.ox = []; S.age = 0; S.fadeAcc = 0; S.warm = 52;
  S.epochLen = 15 + fr(11) * 11;
  clearPlate();
}
if (S.styleUsed !== st) { S.styleUsed = st; clearPlate(); }   // replate in the new inks

// ---- flood stage: incommensurate real-time sines (never re-phases at 8s) ----
const flood = 0.5 + 0.5 * (0.55 * Math.sin(K.t * 0.041) + 0.31 * Math.sin(K.t * 0.0934 + 1.9) + 0.14 * Math.sin(K.t * 0.1571 + 0.4));
const stage = Math.max(0, Math.min(1, flood * (0.55 + K.intensity * 0.55) + A.bass * 0.22 + K.swell * 0.05));
const spd = 0.35 + P.speed * 0.95;
const dts = Math.min(0.05, (typeof deltaTime === 'number' ? deltaTime : 16.7) / 1000);

// ---- one migration step ----------------------------------------------------
function step(rate) {
  const n = S.rx.length; if (n < 12) return;
  const cur = S.cur || (S.cur = []); cur.length = n;
  for (let i = 1; i < n - 1; i++) {
    const ax = S.rx[i] - S.rx[i - 1], ay = S.ry[i] - S.ry[i - 1];
    const bx = S.rx[i + 1] - S.rx[i], by = S.ry[i + 1] - S.ry[i];
    const la = Math.hypot(ax, ay) || 1e-6, lb = Math.hypot(bx, by) || 1e-6;
    const cr = Math.max(-1, Math.min(1, (ax * by - ay * bx) / (la * lb)));
    cur[i] = Math.asin(cr) / ((la + lb) * 0.5);
  }
  cur[0] = 0; cur[n - 1] = 0;
  const nrx = S.nrx || (S.nrx = []), nry = S.nry || (S.nry = []);
  nrx.length = n; nry.length = n;
  for (let i = 0; i < n; i++) { nrx[i] = S.rx[i]; nry[i] = S.ry[i]; }
  for (let i = 1; i < n - 1; i++) {
    // exponentially weighted upstream curvature -> growth + downstream translation
    let s = 0, w = 0;
    for (let k = 0; k < 22; k++) { const j = i - k; if (j < 1) break; const wk = Math.exp(-k * 0.16); s += cur[j] * wk; w += wk; }
    const mig = w > 0 ? s / w : 0;
    const tx = S.rx[i + 1] - S.rx[i - 1], ty = S.ry[i + 1] - S.ry[i - 1];
    const tl = Math.hypot(tx, ty) || 1e-6;
    const nx = ty / tl, ny = -tx / tl;            // outward normal for a positive bend
    const edge = Math.min(1, Math.min(i, n - 1 - i) / 14);           // pinned inlet/outlet
    const er = 0.5 + 1.0 * vn(S.rx[i] * 9 + 3.1, S.ry[i] * 9 - 1.7); // heterogeneous floodplain (clay plugs resist)
    const conf = 1 - 0.92 * Math.max(0, (Math.abs(S.ry[i] - 0.5) - 0.36) / 0.11); // valley confinement (wide enough for loops to close)
    let m = mig * rate * edge * er * Math.max(0.05, conf);
    // CFL clamp: a tight loop reaches curvature ~60, and speed/energy are both
    // poke-able to max — without this the step can exceed node spacing and the
    // polyline turns itself inside out.
    const lim = S.ds * 0.25; if (m > lim) m = lim; else if (m < -lim) m = -lim;
    // Mild centreline smoothing. The flow cannot follow wiggles shorter than the
    // channel width, and without this the bend instability amplifies node-scale
    // noise into runaway length instead of coherent bends.
    const sm = 0.075;
    nrx[i] = S.rx[i] + nx * m + (S.rx[i - 1] + S.rx[i + 1] - 2 * S.rx[i]) * sm;
    nry[i] = S.ry[i] + ny * m + (S.ry[i - 1] + S.ry[i + 1] - 2 * S.ry[i]) * sm;
    if (nry[i] < 0.04) nry[i] = 0.04; else if (nry[i] > 0.96) nry[i] = 0.96;
  }
  for (let i = 0; i < n; i++) { S.rx[i] = nrx[i]; S.ry[i] = nry[i]; }
  // ---- resample to constant node spacing (bends lengthen the reach) --------
  const ds = S.ds, ox2 = [S.rx[0]], oy2 = [S.ry[0]];
  let px = S.rx[0], py = S.ry[0], i2 = 1, acc = 0, guard = 0, capped = false;
  while (i2 < S.rx.length && guard++ < 6000) {
    const dx = S.rx[i2] - px, dy = S.ry[i2] - py, d = Math.hypot(dx, dy);
    if (acc + d >= ds) {
      const nd = (ds - acc) / (d || 1e-9); px += dx * nd; py += dy * nd;
      ox2.push(px); oy2.push(py); acc = 0;
      if (ox2.length > 1100) { capped = true; break; }   // backstop only — cutoffs hold n near ~300
    } else { acc += d; px = S.rx[i2]; py = S.ry[i2]; i2++; }
  }
  // Only re-pin the outlet if we walked the whole reach. Appending it after an
  // early break would stitch a spurious straight bar across the map.
  if (!capped) { ox2.push(S.rx[S.rx.length - 1]); oy2.push(S.ry[S.ry.length - 1]); }
  if (ox2.length > 24) { S.rx = ox2; S.ry = oy2; }
}

// ---- neck cutoff -> oxbow lake ---------------------------------------------
// Scans the WHOLE reach for a neck via a spatial hash (a windowed scan misses
// the long loops, and O(n^2) is too slow once the reach is 500+ nodes). The
// threshold is the channel width — two banks touching IS the cutoff — and it
// grows if the reach ever gets pathologically long, which bounds sinuosity no
// matter how hard speed/energy are poked.
function cutoff(beltHue) {
  const n = S.rx.length; if (n < 30) return false;
  const strain = 1 + Math.max(0, (n - 430) / 430) * 1.6;
  const thr = Math.max(S.ds * 1.55, wsim * 1.9) * strain, t2 = thr * thr;
  const cell = thr;
  const grid = S.grid || (S.grid = new Map()); grid.clear();
  for (let i = 0; i < n; i++) {
    const k = Math.floor(S.rx[i] / cell) * 100003 + Math.floor(S.ry[i] / cell);
    const arr = grid.get(k); if (arr) arr.push(i); else grid.set(k, [i]);
  }
  let bi = -1, bj = -1, bd = 1e9;
  for (let i = 1; i < n - 13; i++) {
    const gx = Math.floor(S.rx[i] / cell), gy = Math.floor(S.ry[i] / cell);
    for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
      const arr = grid.get((gx + a) * 100003 + (gy + b)); if (!arr) continue;
      for (let m = 0; m < arr.length; m++) {
        const j = arr[m];
        if (j - i < 13 || j > n - 2) continue;      // along-channel neighbours aren't a neck
        const dx = S.rx[j] - S.rx[i], dy = S.ry[j] - S.ry[i], d = dx * dx + dy * dy;
        if (d < t2 && d < bd) { bd = d; bi = i; bj = j; }
      }
    }
  }
  if (bi < 0) return false;
  S.ox.push({ x: S.rx.slice(bi, bj + 1), y: S.ry.slice(bi, bj + 1), a: 1, h: beltHue });
  const keep = 3 + Math.round(P.density * 6);
  while (S.ox.length > keep) S.ox.shift();
  S.rx.splice(bi + 1, bj - bi - 1); S.ry.splice(bi + 1, bj - bi - 1);
  return true;
}

// ---- print the current channel into the floodplain plate -------------------
const beltIdx = Math.floor(S.age / S.epochLen);
const bc = belts[((beltIdx % belts.length) + belts.length) % belts.length];
function paintTrace(col, al, wmul) {
  const g = S.fp; g.push(); g.noFill();
  g.stroke(col[0], col[1], col[2], al); g.strokeCap(ROUND); g.strokeJoin(ROUND);
  g.strokeWeight(Math.max(0.9, wsim * BH * wmul));
  g.beginShape();
  for (let i = 0; i < S.rx.length; i++) g.vertex(S.rx[i] * BW, S.ry[i] * BH);
  g.endShape();
  g.pop();
}

const wsim = 0.0092 * (0.5 + P.discharge * 1.05) * (0.72 + stage * 0.62);
const rate = 0.000012 * spd * (0.42 + P.energy * 1.15) * (0.55 + stage * 1.15);

// Warm start: run ~1000 steps over the first second so the reach opens at an
// already-mature sinuosity with a couple of cutoff generations printed into the
// plate. A cold straight line would be both ugly and (briefly) near-static.
const sub = S.warm > 0 ? 10 : 1;
for (let s2 = 0; s2 < sub; s2++) {
  step(rate * (S.warm > 0 ? 2.0 : 1));
  if (s2 % 2 === 0) cutoff(bc);
  if (S.warm > 0) {
    S.age += 0.62 * spd;
    if (s2 % 3 === 0) {
      const wb = belts[((Math.floor(S.age / S.epochLen) % belts.length) + belts.length) % belts.length];
      paintTrace(wb, 6, 1.0);
    }
  }
}
if (S.warm > 0) S.warm--; else S.age += dts * spd;

// slow overbank burial: fade the plate toward the floodplain tone on a real-time
// cadence (a per-frame fade this gentle would round away on an 8-bit buffer)
S.fadeAcc += dts;
const fadeP = 0.55, fadeA = 3.0 - P.density * 2.0;
if (S.fadeAcc >= fadeP) {
  S.fadeAcc = 0;
  S.fp.push(); S.fp.noStroke(); S.fp.fill(base[0], base[1], base[2], fadeA); S.fp.rect(0, 0, BW, BH); S.fp.pop();
}
paintTrace(bc, 4.5 * (0.6 + P.energy * 0.8), 1.0);
if (!lineOnly) paintTrace(barC, 2.0, 0.42);   // point-bar crest inside the belt

// ---- view transform --------------------------------------------------------
const z = Math.max(1, P.scale), hw = 0.5 / z;
const cx = Math.min(1 - hw, Math.max(hw, P.x)), cy = Math.min(1 - hw, Math.max(hw, P.y));
const SX = x => (x - cx) * z * width + width / 2;
const SY = y => (y - cy) * z * height + height / 2;
const AL = P.alpha / 100;

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.fp, 0, 0, width, height, (cx - hw) * BW, (cy - hw) * BH, 2 * hw * BW, 2 * hw * BH);
pop();

const wpx = Math.max(1.3, wsim * z * height);

// ---- oxbow lakes (abandoned loops silting up) ------------------------------
noFill(); strokeCap(ROUND); strokeJoin(ROUND);
for (let o = 0; o < S.ox.length; o++) {
  const L = S.ox[o];
  L.a -= dts * 0.011 * spd;                       // infill over ~90s
  if (L.a <= 0) { S.ox.splice(o, 1); o--; continue; }
  const f = L.a;
  stroke(waterC[0], waterC[1] * (0.35 + f * 0.65), waterC[2] * (0.7 + f * 0.5) + (1 - f) * base[2] * 0.5, 78 * AL);
  strokeWeight(wpx * (0.55 + f * 0.5));
  beginShape(); for (let i = 0; i < L.x.length; i++) vertex(SX(L.x[i]), SY(L.y[i])); endShape();
}

// ---- the active channel ----------------------------------------------------
if (lineOnly) { stroke(inkC[0], inkC[1], inkC[2], 88 * AL); strokeWeight(wpx * 1.5); beginShape(); for (let i = 0; i < S.rx.length; i++) vertex(SX(S.rx[i]), SY(S.ry[i])); endShape(); }
stroke(waterC[0], waterC[1], waterC[2] * (1 - stage * 0.16), 96 * AL);
strokeWeight(wpx);
beginShape(); for (let i = 0; i < S.rx.length; i++) vertex(SX(S.rx[i]), SY(S.ry[i])); endShape();
// turbid thalweg thread — brightens and yellows at flood stage
stroke(lineOnly ? waterC[0] : rot(34), 20 + stage * 46, 62 + stage * 30 + P.energy * 12, (34 + stage * 40) * AL);
strokeWeight(Math.max(0.7, wpx * 0.3));
beginShape(); for (let i = 0; i < S.rx.length; i++) vertex(SX(S.rx[i] + 0.0012 * Math.sin(i * 0.7 + K.t * 0.9)), SY(S.ry[i])); endShape();

