const D = { energy: .6, scale: 1, speed: 1, density: .5, drift: .4, grain: .5, hue: 28, x: .5, y: .5, style: 'emulsion', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
