// ---------------------------------------------------------------------------
// Ostwald ripening (LSW): a dispersion of droplets in a supersaturated matrix.
// Curvature makes small droplets more soluble than large ones, so the big eat the
// small:   dR/dt = (k/R)(1/Rc - 1/R)     -- above the critical radius Rc you grow,
// below it you dissolve. Droplets also drift and coalesce on contact.
//
// Coarsening is the single most dangerous thing in this sub-niche: it slows down
// by construction and a settled dispersion is byte-identical 8s later. Kept alive
// by a closed mass balance plus a breathing solubility:
//   - dissolved mass returns to the matrix as supersaturation sigma;
//   - sigma sets Rc and drives CONTINUOUS NUCLEATION of fresh sub-critical drops;
//   - the equilibrium volume fraction breathes on three incommensurate K.t rates,
//     so the whole population cycles through dissolution waves and nucleation
//     bursts and never reaches a fixed point.
// Droplets are rasterised as analytic spherical caps into a coarse buffer.
// ---------------------------------------------------------------------------
const BW = 200, BH = Math.max(100, Math.round(BW * height / width));
const N = BW * BH;
const MAXD = 460;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.hf = new Float32Array(N); S.idf = new Int32Array(N); S.mtx = new Float32Array(N);
  S.dx = new Float32Array(MAXD); S.dy = new Float32Array(MAXD); S.dr = new Float32Array(MAXD);
  S.vx = new Float32Array(MAXD); S.vy = new Float32Array(MAXD); S.dk = new Float32Array(MAXD);
