const tt = K.t;
const dt = Math.min(0.05, (1 / Math.max(24, K.fps || 60))) * (0.3 + P.speed * 1.5) * 60;

// ---- solubility breathes on incommensurate rates -> perpetual dissolve/nucleate cycles ----
