const fillT = (0.15 + P.density * 0.32) * cyc * (0.85 + K.swell * 0.2 + A.lowmid * 0.25);

let n = S.n;
// mass balance -> supersaturation -> critical radius
let tot = 0, rsum = 0;
for (let k = 0; k < n; k++) { tot += drs[k] * drs[k] * 3.14159265; rsum += drs[k]; }
const targ = Math.max(1, fillT * N);
const sig = Math.max(-1, Math.min(1.4, (targ - tot) / targ));
S.sig = sig;
const rmean = n > 0 ? rsum / n : 2;
const Rc = Math.max(0.9, rmean * (1 - sig * 0.85));
const kg = (0.55 + P.speed * 1.1) * 2.2;
const rmax = BH * 0.22;

// ---- growth / dissolution ----
for (let k = 0; k < n; k++) {
  const R = drs[k];
