      n--; dxs[b2] = dxs[n]; dys[b2] = dys[n]; drs[b2] = drs[n]; vxs[b2] = vxs[n]; vys[b2] = vys[n]; dks[b2] = dks[n];
      b2--;
    }
  }
}

// ---- CONTINUOUS NUCLEATION: classical rate ~ exp(-B/sigma^2), never allowed to stall ----
if (sig > 0.02) {
  const rate = 46 * Math.exp(-0.055 / (sig * sig)) * (0.5 + P.density * 1.2);
  S.nacc = (S.nacc || 0) + rate * dt / 60 * 60;
  let guard = 0;
  while (S.nacc >= 1 && n < MAXD && guard < 30) {
    S.nacc -= 1; guard++;
    dxs[n] = rnd() * BW; dys[n] = rnd() * BH; drs[n] = 1.0 + rnd() * 0.5;
    vxs[n] = 0; vys[n] = 0; dks[n] = rnd(); n++;
