  const R = drs[k], cx = dxs[k], cy = dys[k], R2 = R * R;
  const i0 = Math.floor(cx - R), i1 = Math.ceil(cx + R), j0 = Math.floor(cy - R), j1 = Math.ceil(cy + R);
  for (let j = j0; j <= j1; j++) {
