// ---- shade ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const style = P.style;
const hb = P.hue / 360 + (K.section | 0) * 0.023 + Math.sin(tt * 0.015) * 0.015;
const gain = 0.45 + P.energy * 1.05 + A.rms * 0.3;
const gr = P.grain;
const lx = 0.50, ly = -0.62, lz = 0.60;      // key light
for (let j = 0; j < BH; j++) {
  const jc = j * BW;
