      const nz = Math.sqrt(1 - s2);
      const dif = Math.max(0, nx * lx + ny * ly + nz * lz);
      const hx = lx * 0.5, hy = ly * 0.5, hz = (lz + 1) * 0.5;
      const hl = 1 / Math.sqrt(hx * hx + hy * hy + hz * hz);
      let sp = nx * hx * hl + ny * hy * hl + nz * hz * hl; sp = sp > 0 ? sp : 0;
