// glow-front: an expanding ring re-lights tiles by radial order (continuous K.t -> never re-phases)
const front = (P.act==='drift') ? ((K.t*P.speed*0.05)%1.08) : ((K.t*P.speed*0.09) % 1.08);
const bw = 0.09 + P.glow*0.15 + (P.act==='pulse'?0.06:0);
const peak = 42 + P.energy*46;
const beatBloom = (K.pulse*0.5 + A.bass*0.9) * (P.act==='pulse'?2.0:1.0);
const shimmer = 0.5+0.5*Math.sin(K.t*0.6);
blendMode(ADD);
noStroke();
const cents=S.cents; let drawn=0;
for (let i=0;i<cents.length && drawn<150;i++){
  const tc=cents[i];
  const dd=Math.abs(tc.r-front);
  if (dd>=bw) continue;
  const amt = Math.max(0,1-dd/bw);
  const hx = (P.hue + tc.c*22 + tc.r*46 + K.section*20) % 360;
  const a = (0.06 + peak*0.006)*amt*(0.6+intn)*(0.55+0.45*shimmer) * alphaMul * 100 * 0.33;
  fill(hx, st==='neon'?70:44, 100, a);
  circle(tc.x, tc.y, u*0.045*(0.7+amt));
  drawn++;
}
// central sun beat bloom (partial-frame only -> never trips the strobe gate)
if (beatBloom>0.04){
  fill((P.hue+18)%360, 34, 100, Math.min(30, beatBloom*11)*alphaMul);
  circle(0,0, u*0.5*(1+beatBloom*0.18));
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
pop();

const D = { scale:1, density:.55, speed:1, energy:.6, hue:275, x:.5, y:.5, rough:.5, style:'time-flow', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const intn = (K.intensity!=null?K.intensity:.6);
const st = P.style;

// --- grid dims from scale (larger scale = chunkier cells), <=180 wide ---
const GW = clp(Math.round(150/Math.pow(clp(P.scale,0.4,2.6),0.85)), 44, 180);
const GH = clp(Math.round(GW*height/width), 28, 180);

// --- pixel buffer ---
if (!S.g || S.gk !== GW+'x'+GH){ if (S.g) S.g.remove(); S.g = createGraphics(GW,GH); S.g.pixelDensity(1); S.gk = GW+'x'+GH; }

function hsb2rgb(h,s,v){ h=((h%360)+360)%360; const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b;
  if(h<60){r=c;g=x;b=0;} else if(h<120){r=x;g=c;b=0;} else if(h<180){r=0;g=c;b=x;}
  else if(h<240){r=0;g=x;b=c;} else if(h<300){r=x;g=0;b=c;} else {r=c;g=0;b=x;}
  return [(r+m)*255,(g+m)*255,(b+m)*255]; }

// --- 256 time->color LUT + medium/void tones (rebuild on style/hue/section) ---
const sec = (K.section||0);
if (S.lutKey !== st+'|'+(P.hue|0)+'|'+sec){
  S.lutKey = st+'|'+(P.hue|0)+'|'+sec;
  const hs = sec*6;
  const lut = new Uint8ClampedArray(768);
  for(let k=0;k<256;k++){ const t=k/255; let c;
    if(st==='oil-water') c=hsb2rgb(30+hs*0.3 - t*8, 0.86-0.4*t, 0.12+t*0.58);
    else if(st==='thermal') c=hsb2rgb(255+hs - t*255, 0.92-0.6*Math.max(0,t-0.55), 0.32+t*0.6);
    else if(st==='moss') c=hsb2rgb(108+hs - t*46, 0.74-0.32*t, 0.22+t*0.6);
    else if(st==='ink') c=hsb2rgb(45, 0.07, 0.16+t*0.36);
