  S.lut = lut;
  if(st==='oil-water'){ S.med=hsb2rgb(196,0.52,0.25); S.vd=hsb2rgb(205,0.6,0.07); S.acc=[36,55,100]; }
  else if(st==='thermal'){ S.med=hsb2rgb(238,0.58,0.13); S.vd=hsb2rgb(240,0.5,0.05); S.acc=[14,45,100]; }
  else if(st==='moss'){ S.med=hsb2rgb(122,0.48,0.16); S.vd=hsb2rgb(30,0.5,0.08); S.acc=[64,60,100]; }
  else if(st==='ink'){ S.med=hsb2rgb(45,0.10,0.90); S.vd=hsb2rgb(45,0.05,0.55); S.acc=[45,6,100]; }
  else { S.med=hsb2rgb(P.hue-10,0.5,0.19); S.vd=hsb2rgb(P.hue-20,0.5,0.09); S.acc=[(P.hue+130)%360,45,100]; }
}

// --- medium epoch: new random medium on time-epoch OR section change ---
const period = 37;
const tEpoch = Math.floor(K.t/period);
const key = GW+'x'+GH+'|'+P.seed+'|'+tEpoch+'|'+sec+'|'+P.rough.toFixed(2)+'|'+P.density.toFixed(2);
if (S.key !== key){
  S.key = key;
  const sd = ((P.seed*2654435761) ^ (tEpoch*40503) ^ (sec*668265263)) >>> 0;
  const N = GW*GH;
  S.thr = new Float32Array(N); S.inv = new Uint8Array(N); S.tim = new Float32Array(N); S.front = new Uint8Array(N);
  S.heap = []; S.tips = []; S.counter = 0; S.fc = 0;
  const lh = (ix,iy)=>{ let h=((ix*374761393)^(iy*668265263)^(sd*2246822519))>>>0; h=(h^(h>>>13)); h=(h*1274126177)>>>0; return ((h^(h>>>16))>>>0)/4294967295; };
  const vnz = (x,y)=>{ const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy; const uu=fx*fx*(3-2*fx),vv=fy*fy*(3-2*fy);
    const a=lh(ix,iy),b=lh(ix+1,iy),c=lh(ix,iy+1),d=lh(ix+1,iy+1); return a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv; };
  const F1 = 5 + (1-P.rough)*3;
  for(let y=0;y<GH;y++) for(let x=0;x<GW;x++){ const i=y*GW+x;
    const corr = 0.62*vnz(x/GW*F1, y/GH*F1) + 0.38*vnz(x/GW*F1*2.3+7.1, y/GH*F1*2.3-3.2);
    const wht = lh(x*3+1, y*5+2);
    let tv = (1-P.rough)*corr + P.rough*wht;
    S.thr[i] = Math.min(0.999, Math.max(0.001, tv + (lh(x*7+3,y*11+5)-0.5)*0.05)); }
  S.norm = Math.max(1, Math.floor(N*(0.26+P.density*0.24)));
  const sx = Math.min(GW-2, Math.max(1, Math.floor(clp(P.x,0.08,0.92)*GW)));
  const sy = Math.min(GH-2, Math.max(1, Math.floor(clp(P.y,0.08,0.92)*GH)));
  S.seed0 = sy*GW+sx;
  S.justBuilt = true;
}

const thr = S.thr, inv = S.inv, tim = S.tim, front = S.front;
function hpush(i){ const H=S.heap; H.push(i); let c=H.length-1; while(c>0){ const p=(c-1)>>1; if(thr[H[p]]<=thr[H[c]])break; const t=H[p];H[p]=H[c];H[c]=t; c=p; } }
function hpop(){ const H=S.heap; const top=H[0], last=H.pop(); if(H.length){ H[0]=last; const n=H.length; let c=0; for(;;){ const l=2*c+1,r=l+1; let m=c; if(l<n&&thr[H[l]]<thr[H[m]])m=l; if(r<n&&thr[H[r]]<thr[H[m]])m=r; if(m===c)break; const t=H[m];H[m]=H[c];H[c]=t; c=m; } } return top; }
function tryFront(j){ if(inv[j]===0 && front[j]===0){ front[j]=1; hpush(j); } }
function invade(ci){ inv[ci]=1; tim[ci]=S.counter++; const x=ci%GW, y=(ci/GW)|0;
  S.tips.push(ci); if(S.tips.length>150) S.tips.shift();
  if(x>0) tryFront(ci-1); if(x<GW-1) tryFront(ci+1); if(y>0) tryFront(ci-GW); if(y<GH-1) tryFront(ci+GW); }
function growN(n){ const H=S.heap; let did=0, guard=0; while(did<n && H.length && guard<n*5+64){ guard++; const ci=hpop(); if(inv[ci]!==0) continue; invade(ci); did++; } return did; }
function markTrapped(){ const N=GW*GH; let reach=S.reach; if(!reach||reach.length!==N){ reach=S.reach=new Uint8Array(N); S.q=new Int32Array(N); } reach.fill(0); const q=S.q; let qt=0,qh=0;
  for(let x=0;x<GW;x++){ let i=x; if(inv[i]===0){reach[i]=1;q[qt++]=i;} i=(GH-1)*GW+x; if(inv[i]===0&&!reach[i]){reach[i]=1;q[qt++]=i;} }
  for(let y=0;y<GH;y++){ let i=y*GW; if(inv[i]===0&&!reach[i]){reach[i]=1;q[qt++]=i;} i=y*GW+GW-1; if(inv[i]===0&&!reach[i]){reach[i]=1;q[qt++]=i;} }
  while(qh<qt){ const ci=q[qh++]; const x=ci%GW,y=(ci/GW)|0;
    if(x>0){const j=ci-1; if(inv[j]===0&&!reach[j]){reach[j]=1;q[qt++]=j;}}
    if(x<GW-1){const j=ci+1; if(inv[j]===0&&!reach[j]){reach[j]=1;q[qt++]=j;}}
    if(y>0){const j=ci-GW; if(inv[j]===0&&!reach[j]){reach[j]=1;q[qt++]=j;}}
    if(y<GH-1){const j=ci+GW; if(inv[j]===0&&!reach[j]){reach[j]=1;q[qt++]=j;}} }
  for(let i=0;i<N;i++){ if(inv[i]===0 && !reach[i]) inv[i]=2; } }

if (S.justBuilt){ S.justBuilt=false; invade(S.seed0); const pg=Math.floor(GW*GH*(0.14+P.density*0.28)); growN(pg); markTrapped(); }

// --- live growth: the advancing frontier is the motion ---
const rate = Math.max(1, Math.round((3+P.speed*6)*(0.5+intn) + A.bass*30));
growN(rate);
S.fc = (S.fc||0)+1; if(S.fc%16===0) markTrapped();

// --- render grid -> pixels ---
S.g.loadPixels(); const px=S.g.pixels; const lut=S.lut, norm=S.norm, med=S.med, vd=S.vd;
const N=GW*GH;
for(let i=0;i<N;i++){ const o=i*4; const s=inv[i];
  if(s===1){ let t01=tim[i]/norm; if(t01>1)t01=1; const p3=((t01*255)|0)*3; px[o]=lut[p3]; px[o+1]=lut[p3+1]; px[o+2]=lut[p3+2]; }
  else if(s===2){ px[o]=vd[0]; px[o+1]=vd[1]; px[o+2]=vd[2]; }
  else { const tx=0.72+0.5*thr[i]; px[o]=med[0]*tx; px[o+1]=med[1]*tx; px[o+2]=med[2]*tx; }
  px[o+3]=255; }
S.g.updatePixels();

// --- draw buffer with slow K.t advection drift (never re-phases -> motion floor) ---
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
const dx=Math.sin(K.t*0.13)*width*0.014, dy=Math.cos(K.t*0.11)*height*0.014;
image(S.g, -width*0.03+dx, -height*0.03+dy, width*1.06, height*1.06);
pop();

// --- live frontier glow: invasion tips shimmer (audio sparkle on top) ---
push(); blendMode(ADD); noStroke();
const tips=S.tips, sxp=width/GW, syp=height/GH, acc=S.acc, eAmp=(0.45+P.energy);
for(let k=0;k<tips.length;k++){ const ci=tips[k]; const gx=ci%GW, gy=(ci/GW)|0;
  const pulse=0.5+0.5*Math.sin(K.t*2.6 - k*0.09);
  const gl=(3.5+pulse*8)*eAmp + A.treble*24 + K.pulse*5;
  fill(acc[0], acc[1], acc[2], Math.min(58,gl));
  circle(gx*sxp+sxp*0.5+dx, gy*syp+syp*0.5+dy, sxp*(1.5+pulse*1.4)); }
blendMode(BLEND); pop();
drawingContext.shadowBlur = 0;

const D = { energy:.6, density:.5, scale:1, speed:1, hue:342, petals:8, x:.5, y:.56, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Flowers opening by differential growth rather than by keyframe: the adaxial surface
// outgrows the abaxial until each petal's curvature reverses through zero and the bud reflexes
// itself open. A DENSE PLATE of 16 staggered blooms on a ~40s cycle — bud, anthesis, turgor loss,
// abscission, bare receptacle, new bud — so something is always opening and something always
// shedding; the sheet never converges and never empties. Herbarium rigour, not a cartoon flower:
// ink line, stipple modelling, sepals, androecium, cauline leaves, a ruled specimen sheet.
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.35,2.2);
const NP = Math.round(cl(P.petals,3,13)), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43+1.7) + .32*Math.sin(T*2.29) + .35*Math.sin(T*.163);
const breeze = (.25 + .85*EN)*gust + A.lowmid*.75 + K.pulse*.2*K.intensity;

// ---- style ---------------------------------------------------------------
const H = P.hue;
let papH, papS, papB, inkH, inkS, inkB, mode;
if (sty === 'cyanotype') { papH = (213 + (H-213)*.16 + 360)%360; papS = 84; papB = 26; inkH = papH; inkS = 4; inkB = 98; mode = 1; }
else if (sty === 'xray') { papH = 198; papS = 44; papB = 15; inkH = H; inkS = 42; inkB = 96; mode = 2; }
else if (sty === 'chiaroscuro') { papH = 26; papS = 48; papB = 13; inkH = H; inkS = 30; inkB = 90; mode = 3; }
else { papH = 40; papS = 16; papB = 54; inkH = 24; inkS = 55; inkB = 17; mode = 0; }

// ---- ground: a ruled specimen sheet --------------------------------------
const bgKey = [width,height,sd,sty,H].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(620, Math.max(240, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke(); g.background(papH, papS, papB);
  if (mode === 1) {
    for (let i=0;i<190;i++){ const w2 = bw*(.25+fr(i*2.9)*.95);
      g.fill(papH, papS-fr(i*4.4)*26, papB + (fr(i*6.6)-.44)*19, 25);
      g.rect(fr(i*8.1)*bw-w2*.3, fr(i*5.3)*bh, w2, bh*.014 + fr(i*9.9)*bh*.022); }
  } else if (mode === 2) {
    for (let i=0;i<2400;i++){ g.fill(196, 30, 44+fr(i*4.4)*46, 8); g.rect(fr(i*3.9)*bw, fr(i*6.1+3)*bh, 1.3, 1.3); }
  } else if (mode === 3) {
    const dc0 = g.drawingContext;                          // a single pool of light
    const lg = dc0.createRadialGradient(bw*.42, bh*.4, bw*.02, bw*.42, bh*.4, bw*.72);
    lg.addColorStop(0, 'rgba(255,238,214,0.30)'); lg.addColorStop(.5, 'rgba(210,180,150,0.09)');
    lg.addColorStop(1, 'rgba(0,0,0,0)'); dc0.fillStyle = lg; dc0.fillRect(0,0,bw,bh);
    for (let i=0;i<2600;i++){ g.fill(28, 40, 30+fr(i*4.1)*46, 7); g.rect(fr(i*3.7)*bw, fr(i*8.3+2)*bh, 1.4, 1.4); }
  } else {
    for (let i=0;i<2800;i++){ g.fill(papH, papS*(.5+fr(i*2.3)), papB + (fr(i*5.1)-.5)*26, 44);
      g.rect(fr(i*3.1)*bw, fr(i*7.7+9)*bh, 1.4, 1.4); }
    for (let i=0;i<18;i++){ const fx=fr(i*13.3+2)*bw, fy=fr(i*17.1+5)*bh, r=bw*(.015+fr(i*3.7)*.05);
      for (let k=0;k<3;k++){ g.fill(24, 46, 40, 5); g.ellipse(fx, fy, r*(1+k*.7), r*(.85+k*.6)); } }
    g.noFill(); g.stroke(inkH, 30, 40, 20); g.strokeWeight(1);        // sheet rule
    g.rect(bw*.03, bh*.04, bw*.94, bh*.92); g.noStroke();
  }
  const dc = g.drawingContext;
  const rg = dc.createRadialGradient(bw*.5, bh*.5, bw*.12, bw*.5, bh*.5, bw*.82);
  rg.addColorStop(0, 'rgba(0,0,0,0)');
  rg.addColorStop(1, mode===3 ? 'rgba(0,0,0,0.55)' : mode===0 ? 'rgba(0,0,0,0.42)' : 'rgba(0,0,0,0.36)');
  dc.fillStyle = rg; dc.fillRect(0, 0, bw, bh);
  g.pop();
}

// ---- flower pool: staggered bud -> anthesis -> wilt -> shed -> bud -------
// 16 blooms on a jittered 4x4 with depth, cycling in ~40s (the first cut ran 6 blooms on a ~74s
// cycle and drew 4 of them: three sparse flowers that had all finished opening. It converged.)
const NMAX = 16;
const ORD = [5,10,0,15,7,2,12,9,4,14,1,11,6,13,3,8];      // spread the drawn subset over the sheet
const TB = 6, TO = 17, TA = 24, TW = 33, TD = 40, TZ = 44;
const reseed = f => {
  const j = f.id*37.1 + (f.gen = (f.gen||0)+1)*13.3;
  const c0 = ORD[f.id];
  f.ox = (.10 + (c0 % 4)*.27 + (fr(j*1.3)-.5)*.15);
  f.oy = (.20 + ((c0/4)|0)*.24 + (fr(j*2.1)-.5)*.13);
  f.dep = .55 + fr(j*1.9)*.85;                 // depth: near blooms bigger, far ones smaller
  f.sz = (.72 + fr(j*3.3)*.62)*f.dep;
  f.tilt = .42 + fr(j*4.7)*.7;                 // view tilt: 0 = face-on, 1.1 = three-quarter
  f.spin = fr(j*5.9)*6.28;
  f.hj = (fr(j*6.3)-.5)*44;
  f.ph = fr(j*7.1)*6.28;
  f.rate = .82 + fr(j*8.9)*.42;
  f.spr = (.07 + fr(j*10.3)*.06)*(f.id%2 ? 1 : -1);        // head rotation, two senses
  f.shed = [];
  for (let k=0;k<13;k++) f.shed.push(fr(j*9.7 + k*3.1));   // per-petal abscission order
  f.age = 0;
};
if (!S.fl || S.fl.length !== NMAX || S.szKey !== width+'x'+height+sd) {
  S.szKey = width+'x'+height+sd; S.fl = [];
  for (let i=0;i<NMAX;i++){ const f = { id:i }; reseed(f); f.age = fr(i*21.3)*TZ; S.fl.push(f); }
}
for (let i=0;i<NMAX;i++){ const f = S.fl[i];
  f.age += dt*SP*f.rate*(.6 + .85*EN)*(.7 + .6*K.intensity);
  if (f.age > TZ) reseed(f); }

// ---- draw ----------------------------------------------------------------
image(S.g, 0, 0, width, height);
const nDraw = cl(Math.round(4 + DN*10), 2, NMAX);
const NSG = 15;                                  // integration steps along the petal
if (mode === 2) blendMode(ADD);
strokeJoin(ROUND); strokeCap(ROUND);
const wprof = s => Math.pow(Math.sin(Math.PI*Math.pow(cl(s,0,1), .72)), .6);
const order2 = [];
for (let n=0;n<nDraw;n++) order2.push(n);
order2.sort((a,b) => S.fl[a].dep - S.fl[b].dep);           // far blooms behind near ones

for (let oi=0;oi<order2.length;oi++) {
  const f = S.fl[order2[oi]]; if (!f) continue;
  const a = f.age;
  const swell = cl(a/TB, 0, 1);
  const opn = cl((a - TB)/(TO - TB), 0, 1);                // 0 = bud, 1 = fully reflexed
  const o = opn*opn*(3 - 2*opn);
  const wilt = cl((a - TA)/(TW - TA), 0, 1);
  const shedP = cl((a - TW)/(TD - TW), 0, 1);
  const R = u*.155*SC*f.sz;                                // petal length at anthesis
  const cx = (f.ox + (P.x-.5))*width, cyy = (f.oy + (P.y-.56))*height;
  const sway = breeze*u*.030*f.sz*(.6 + .7*Math.sin(T*.87 + f.ph));
  const bob = Math.sin(T*1.13 + f.ph*1.9)*u*.008*(.4+EN);
  // the head rotates on its own sense and rate: over 8s this walks each corolla by roughly a
  // whole petal index, which decorrelates the frame without anything jumping.
  const spin = f.spin + T*f.spr;
