const NMAX = 1500;
const N = Math.round(300 + clp(P.density,0,1)*1200);
if (!S.tx || S.tx.length!==NMAX){ S.tx=new Float32Array(NMAX); S.ty=new Float32Array(NMAX); S.age=new Float32Array(NMAX); S.seedUsed=null; }

// ---- ODE system registry (topology cycles on K.section) ----
// each: fn(x,y,pr)->[dx,dy]; view center cx,cy + radius R; fixed points [x,y,type]
const SYS = [
  { name:'PENDULUM',      cx:0, cy:0, R:3.5,  vs:2.2,
    fn:(x,y,d)=>[y, -Math.sin(x) - d*y],
    fx:[[0,0,'center'],[Math.PI,0,'saddle'],[-Math.PI,0,'saddle']] },
  { name:'VAN DER POL',   cx:0, cy:0, R:3.4,  vs:2.6,
    fn:(x,y,m)=>[y, m*(1-x*x)*y - x],
    fx:[[0,0,'source']] },
  { name:'DUFFING',       cx:0, cy:0, R:1.95, vs:1.6,
    fn:(x,y,d)=>[y, x - x*x*x - d*y],
    fx:[[0,0,'saddle'],[1,0,'sink'],[-1,0,'sink']] },
  { name:'LOTKA-VOLTERRA',cx:1, cy:1, R:0.98, vs:0.9,
    fn:(x,y)=>{ const xx=Math.max(0.02,x), yy=Math.max(0.02,y); return [xx*(1.1-yy), -yy*(1.1-xx)]; },
    fx:[[1.1,1.1,'center'],[0,0,'saddle']] }
];
const sec = K.section|0;
const sys = SYS[((sec % SYS.length)+SYS.length)%SYS.length];
// slow drift of the system's control parameter on K.t (never re-phases)
let pr;
if (sys.name==='PENDULUM')      pr = 0.06 + 0.10*(0.5+0.5*Math.sin(K.t*0.11));
else if (sys.name==='VAN DER POL') pr = 1.6 + 1.1*(0.5+0.5*Math.sin(K.t*0.09));
else if (sys.name==='DUFFING')  pr = 0.12 + 0.16*(0.5+0.5*Math.sin(K.t*0.13));
else pr = 0;

const R = sys.R, cx = sys.cx, cy = sys.cy;

// ---- world<->buffer mapping ----
const bcx = clp(P.x,0,1)*BW, bcy = clp(P.y,0,1)*BH;
const bs = Math.min(BW,BH) * clp(P.scale,0.3,3) * 0.44 / R;
const toBX = x => bcx + (x-cx)*bs;
const toBY = y => bcy - (y-cy)*bs;

// ---- (re)seed all tracers on seed change ----
function spawn(i, salt){
  const a = fr(i*2+salt*7.13), b = fr(i*2+1+salt*3.71);
  S.tx[i] = cx + (a*2-1)*R*0.98;
  S.ty[i] = cy + (b*2-1)*R*0.98;
  S.age[i] = fr(i+salt*17.7)*140;
}
if (S.seedUsed !== (P.seed|0)){ S.seedUsed = (P.seed|0); S.spawn=0; for (let i=0;i<NMAX;i++) spawn(i,1); }

// ---- ground / fade tone per style ----
const g = S.buf;
let gH,gS,gB;
if (style==='streamflow'){ gH=255; gS=54; gB=12; }
else if (style==='aurora'){ gH=235; gS=50; gB=11; }
else if (style==='ember'){  gH=16;  gS=68; gB=11; }
else if (style==='blueprint'){ gH=214; gS=78; gB=26; }
else { gH=42; gS=9; gB=86; } // ink cream

if (S.freshBuf){ g.push(); g.noStroke(); g.fill(gH,gS,gB,100); g.rect(0,0,BW,BH); g.pop(); S.freshBuf=false; }

// trail persistence: higher trail -> lower fade alpha -> longer streaks
const fadeA = light ? (7 + (1-clp(P.trail,0,1))*20) : (5 + (1-clp(P.trail,0,1))*16);
g.push();
g.noStroke(); g.blendMode(BLEND);
g.fill(gH,gS,gB, fadeA);
g.rect(0,0,BW,BH);

// ---- advect tracers, draw hued-by-speed segments ----
const dt = 0.028 * clp(P.speed,0.15,3) * (sys.name==='LOTKA-VOLTERRA'?1.4:1.0);
const vs = sys.vs;
const bri = 55 + clp(P.energy,0,1)*45 + A.rms*30 + K.intensity*8;
const aBoost = 1 + A.bass*0.7 + K.pulse*0.25*clp(P.energy,0,1);
const maxStep = R*0.11; // clamp world step so stiff fields never explode

if (!light) g.blendMode(ADD);
const salt = 2 + (sec*0.37);
for (let i=0;i<N;i++){
  let x=S.tx[i], y=S.ty[i];
  const ox=toBX(x), oy=toBY(y);
  // RK2 midpoint
  let k1=sys.fn(x,y,pr);
  let mx=x+k1[0]*dt*0.5, my=y+k1[1]*dt*0.5;
  let k2=sys.fn(mx,my,pr);
  let vx=k2[0], vy=k2[1];
  const sp=Math.hypot(vx,vy);
  // clamp step length
  let stepL=sp*dt; let sc=1; if (stepL>maxStep) sc=maxStep/stepL;
  x += vx*dt*sc; y += vy*dt*sc;
  S.age[i]++;
  const bad = !isFinite(x)||!isFinite(y)|| Math.abs(x-cx)>R*2.2 || Math.abs(y-cy)>R*2.2;
  const old = S.age[i] > (150 + fr(i)*120);
  if (bad || old || (fr(i+ (S.spawn|0)) < (0.010+clp(P.density,0,1)*0.018))){
    spawn(i, salt + (S.spawn||0)*0.019); S.spawn=(S.spawn||0)+1;
    continue;
  }
  S.tx[i]=x; S.ty[i]=y;
  const nx=toBX(x), ny=toBY(y);
  // hue by normalized speed
  const sn = clp(sp/vs, 0, 1);
  let hh, ss, bb, wa, wt;
  if (style==='streamflow'){ hh=(P.hue + 150 - sn*150 + 360)%360; ss=88; bb=bri; wa=32*aBoost; wt=1.05; }
  else if (style==='aurora'){ hh=(120 + sn*160 + P.hue*0.15)%360; ss=70; bb=bri*0.95; wa=22*aBoost; wt=1.9; }
  else if (style==='ember'){ hh=(6 + sn*46)%360; ss=90-sn*18; bb=bri; wa=30*aBoost; wt=1.15; }
  else if (style==='blueprint'){ hh=195; ss=14+sn*20; bb=100; wa=46; wt=1.0; }
  else { hh=(P.hue*0.1+28)%360; ss=16; bb=14; wa=40; wt=1.1; } // ink dark stroke
  g.stroke(hh,ss,bb,wa);
  g.strokeWeight(wt);
  g.line(ox,oy,nx,ny);
}
g.blendMode(BLEND);
g.pop();

// ---- composite buffer to full canvas ----
push();
if (P.alpha < 100){ tint(0,0,100,P.alpha); }
image(g, 0, 0, W, H);
pop();

// ================= main-canvas overlay: nullclines + fixed pts =================
const scX = x => clp(P.x,0,1)*W + (x-cx)*(u*clp(P.scale,0.3,3)*0.44/R);
const scY = y => clp(P.y,0,1)*H - (y-cy)*(u*clp(P.scale,0.3,3)*0.44/R);

// nullclines: generic zero-crossing scan of dx (x-null) and dy (y-null)
push();
noStroke();
const GX=44, GY=30;
const nA = 12 + P.energy*16;
for (let gy=0; gy<GY; gy++){
  for (let gx=0; gx<GX; gx++){
    const wx = cx + ((gx+0.5)/GX*2-1)*R*1.02;
    const wy = cy + ((gy+0.5)/GY*2-1)*R*1.02;
    const wx2 = cx + ((gx+1.5)/GX*2-1)*R*1.02;
    const wy2 = cy + ((gy+1.5)/GY*2-1)*R*1.02;
    const f00=sys.fn(wx,wy,pr), f10=sys.fn(wx2,wy,pr), f01=sys.fn(wx,wy2,pr);
    // dx = 0 crossing (horizontal neighbor)
    if (f00[0]*f10[0] < 0){
      const px=scX((wx+wx2)*0.5), py=scY(wy);
      if (px>-5&&px<W+5&&py>-5&&py<H+5){
        fill(light?(214):(P.hue+150)%360, light?70:70, light?100:96, nA);
        circle(px,py, light?2.2:2.6);
      }
    }
    // dy = 0 crossing (vertical neighbor)
    if (f00[1]*f01[1] < 0){
      const px=scX(wx), py=scY((wy+wy2)*0.5);
      if (px>-5&&px<W+5&&py>-5&&py<H+5){
        fill(light?(28):(P.hue+30)%360, light?60:80, light?24:100, nA);
        circle(px,py, light?2.2:2.4);
      }
    }
  }
}
pop();

// fixed points: glowing markers (shadowBlur on few shapes only)
push();
const spark = 1 + A.treble*0.9 + K.pulse*0.5;
for (let f=0; f<sys.fx.length; f++){
  const fp=sys.fx[f], px=scX(fp[0]), py=scY(fp[1]);
  if (px<-20||px>W+20||py<-20||py>H+20) continue;
  let mh, ms, mb;
  const ty=fp[2];
  if (ty==='center'){ mh=light?214:0; ms=light?30:0; mb=100; }
  else if (ty==='sink'){ mh=light?214:38; ms=light?70:90; mb=100; }
  else if (ty==='source'){ mh=light?214:320; ms=light?70:85; mb=100; }
  else { mh=light?24:190; ms=light?70:80; mb=100; } // saddle
  const rr = u*0.012*(0.8+0.4*Math.sin(K.t*1.3+f));
  drawingContext.shadowBlur = light?0:18*spark;
  drawingContext.shadowColor = 'rgba(255,255,255,0.7)';
  noFill(); stroke(mh,ms,mb, light?90:80); strokeWeight(1.6);
  circle(px,py, rr*2.4);
  drawingContext.shadowBlur = 0;
  noStroke(); fill(mh,ms,light?30:100, 95);
  circle(px,py, rr);
  if (ty==='saddle'){ // cross-hair separatrix hint
    stroke(mh,ms,mb, light?55:45); strokeWeight(1); noFill();
    line(px-rr*2.2,py, px+rr*2.2,py); line(px,py-rr*2.2, px,py+rr*2.2);
  }
}
drawingContext.shadowBlur=0;
pop();

// faint system label (the "map of a differential equation" flavor; evolves w/ section)
push();
noStroke();
textFont('monospace');
textSize(u*0.026);
textAlign(LEFT,TOP);
fill(light?214:0, light?60:0, light?30:100, light?55:40);
text(sys.name, u*0.03, u*0.03);
textSize(u*0.016);
fill(light?214:0, light?50:0, light?35:100, light?45:30);
text("phase portrait / sec "+sec, u*0.03, u*0.03 + u*0.034);
pop();

blendMode(BLEND);

const D = { energy:.6, scale:1, density:.5, speed:1, hue:34, fold:6, phason:.5, front:.55, x:.5, y:.5, style:'plaster', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const trb  = (S.tb = (S.tb||0)*.87 + (A.treble||0)*.13);

// ---- de Bruijn multigrid -> dual rhombic quasilattice ---------------------
// N line families at pi/N apart give 2N-fold symmetry: N=6 -> the 12-fold
// dodecagonal tiling (30/60/90 rhombi), N=5 -> 10-fold, N=4 -> 8-fold.
const N = cl(Math.round(P.fold), 4, 7)|0;

// gamma_j is the perpendicular-space coordinate. Drifting each family on its
// OWN incommensurate rate is a phason: tiles flip in place. cam is a genuine
// pan across the (infinite, never-repeating) tiling.
S.pz = (S.pz||0) + dt*sp*(.010 + .085*cl(P.phason,0,1));
S.cx = (S.cx||0) + dt*sp*(.20 + .16*Math.sin(K.t*.041));
S.cy = (S.cy||0) + dt*sp*(.11 + .16*Math.cos(K.t*.053+1.4));
const rot = K.t*.0115*sp + .07*Math.sin(K.t*.0637+2.1);

const EX=[], EY=[], G=[];
let vox=0, voy=0;
for (let j=0;j<N;j++){
  const a = Math.PI*j/N;
  EX[j] = Math.cos(a); EY[j] = Math.sin(a);
  G[j] = fr(j*7.13+1.9)*3.1 + S.pz*(1 + .37*fr(j*11.7+.3));
  vox += (G[j]+.5)*EX[j]; voy += (G[j]+.5)*EY[j];
}

const ax = cl(P.x,.15,.85)*width, ay = cl(P.y,.15,.85)*height;
const corner = Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay));
// tile count grows as Rv^2; floor the edge length so the frame is always fully
// covered without blowing past the shape budget (Rv<=11 -> <=~570 rhombi)
const te = Math.max(u*.15*cl(P.scale,.75,2.2), corner/9.4);
const Rv = corner/te + 1.6;
// v ~= (N/2)*p - sum (gamma_m+.5) e_m  ->  invert to find the p-disc we need
const pcx = 2*(S.cx + vox)/N, pcy = 2*(S.cy + voy)/N;
const Rp = 2*(Rv + 3.2)/N;

const TL = [], TLMAX = 3600;                               // 6 slots per tile -> 600 rhombi
for (let j=0;j<N && TL.length<TLMAX;j++){
  for (let jp=j+1;jp<N && TL.length<TLMAX;jp++){
    const cx=EX[j], cy=EY[j], dx=EX[jp], dy=EY[jp];
    const det = cx*dy - cy*dx;
    if (Math.abs(det) < 1e-6) continue;
    const bj = pcx*cx + pcy*cy - G[j], bp = pcx*dx + pcy*dy - G[jp];
    const k0 = Math.ceil(bj-Rp), k1 = Math.floor(bj+Rp);
    const q0 = Math.ceil(bp-Rp), q1 = Math.floor(bp+Rp);
    for (let k=k0;k<=k1 && TL.length<TLMAX;k++){
      const a = k + G[j];
      for (let q=q0;q<=q1 && TL.length<TLMAX;q++){
        const b = q + G[jp];
        const px = (a*dy - b*cy)/det, py = (cx*b - dx*a)/det;
        const rx = px-pcx, ry = py-pcy;
        if (rx*rx + ry*ry > Rp*Rp) continue;
        let ox=0, oy=0;
        for (let m=0;m<N;m++){
          const Km = (m===j) ? k-1 : (m===jp) ? q-1 : Math.floor(px*EX[m] + py*EY[m] - G[m]);
          ox += Km*EX[m]; oy += Km*EY[m];
        }
        const mx = ox + (cx+dx)*.5 - S.cx, my = oy + (cy+dy)*.5 - S.cy;
        if (mx*mx + my*my > (Rv+1)*(Rv+1)) continue;
        let kind = jp-j; if (kind > N-kind) kind = N-kind;
        TL.push(ox - S.cx, oy - S.cy, j, jp, kind, Math.abs(det));
      }
    }
  }
}

// ---- style tables ---------------------------------------------------------
const wire = (sty==='xray');
function grd(){
  if (sty==='lapis')   return [236, 74, 12];
  if (sty==='steel')   return [206, 16, 13];
  if (wire)            return [(H+188)%360, 60, 4];
  if (sty==='pigment') return [46, 12, 92];
  return [(H+8)%360, 26, 12];                                // plaster: shadowed niche
}
// base tone per rhombus kind (1 = thinnest)
function kindTone(kind){
  const q = (kind-1)/Math.max(1, Math.floor(N/2)-1);
  if (sty==='lapis')   return [ (H + 4 + q*16)%360, 30 - q*16, 62 + q*30 ];
  if (sty==='steel')   return [ 206 + q*10, 8 + q*5, 36 + q*24 ];
  if (wire)            return [ (H + 150 + q*70)%360, 40, 96 ];
  if (sty==='pigment') return [ [352, 205, 46][kind % 3], 62, 84 ];
  return [ (H + 2 + q*10)%360, 20 - q*6, 46 + q*24 ];        // plaster
}

// ---- ground ---------------------------------------------------------------
const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);

// ---- orbiting raking light + the annealing front --------------------------
const lang = K.t*.083*sp + .5*Math.sin(K.t*.0311);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const plx = (.5 + .27*Math.sin(K.t*.061+.3))*width, ply = (.5 + .24*Math.cos(K.t*.047+2.2))*height;
const fdir = K.t*.037*sp + 1.1;
const fnx = Math.cos(fdir), fny = Math.sin(fdir);
const fw = cl(P.front,0,1)*(.65+.5*lift);

push(); translate(ax, ay); rotate(rot);
strokeJoin(ROUND);
const jw = (u/900)*(.5 + 2.2*(1-cl(P.density,0,1))*.35 + 1.1*en);
const hatch = cl(P.density,0,1) > .18 && TL.length < 2520;  // budget: hatch only while the rhombi are big enough to read

for (let i=0;i<TL.length;i+=6){
  const ox=TL[i], oy=TL[i+1], j=TL[i+2], jp=TL[i+3], kind=TL[i+4], ar=TL[i+5];
  const e0x=EX[j], e0y=EY[j], e1x=EX[jp], e1y=EY[jp];
  const cxm = ox + (e0x+e1x)*.5, cym = oy + (e0y+e1y)*.5;

  // flat shade: long diagonal against the orbiting light
  let dgx = e0x+e1x, dgy = e0y+e1y;
  const dl = Math.hypot(dgx,dgy) || 1; dgx/=dl; dgy/=dl;
  const lam = Math.abs(dgx*lgx + dgy*lgy);
  // annealing front: a narrow travelling band of relaxation
  const wv = Math.sin((cxm*fnx + cym*fny)*.44 - K.t*1.09*sp) * .5 + .5;
  const fq = fw * Math.pow(wv, 4) * (.6 + .55*bass);
  const t0 = kindTone(kind);
  const sh = (.34 + .60*lam) * (.62 + .5*en) + fq*.85 + .10*Math.sin(cxm*.7+cym*.5);

  const X0=ox*te, Y0=oy*te, X1=(ox+e0x)*te, Y1=(oy+e0y)*te;
  const X2=(ox+e0x+e1x)*te, Y2=(oy+e0y+e1y)*te, X3=(ox+e1x)*te, Y3=(oy+e1y)*te;

  if (wire) {
    noFill();
    stroke(t0[0], t0[1], cl(t0[2]*(.30+.62*sh+.3*trb),0,100), cl(26 + 52*sh, 8, 92));
    strokeWeight(jw*(.7+1.1*sh));
    quad(X0,Y0,X1,Y1,X2,Y2,X3,Y3);
    if (hatch && kind >= 2) {
      stroke(t0[0], t0[1], t0[2], cl(10+26*sh,0,60)); strokeWeight(jw*.5);
      line((X0+X1)*.5, (Y0+Y1)*.5, (X2+X3)*.5, (Y2+Y3)*.5);
    }
  } else {
    fill(t0[0], cl(t0[1]*(1.18-.35*sh),0,100), cl(t0[2]*(.30 + .78*sh), 2, 100));
    stroke(gc[0], cl(gc[1]*1.2,0,100), cl(gc[2]*(.5 + .5*(1-en)), 0, 100), 74);
    strokeWeight(jw);
    quad(X0,Y0,X1,Y1,X2,Y2,X3,Y3);
    if (hatch && kind >= 2 && ar > .45) {           // engraved hatching on the fat tiles
      const nh = 2 + ((kind*7+j)%2);
      stroke(t0[0], cl(t0[1]+16,0,100), cl(t0[2]*(.30+.5*sh)*.62, 0, 100), 30 + 40*cl(P.density,0,1));
      strokeWeight(jw*.55);
      for (let h=1;h<=nh;h++){
        const f = h/(nh+1);
        line(X0 + (X3-X0)*f, Y0 + (Y3-Y0)*f, X1 + (X2-X1)*f, Y1 + (Y2-Y1)*f);
      }
    }
  }
}
pop();

// ---- cached grain / plaster tooth ----------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=440, th=290, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2400;i++){
    const rr = .4 + fr(i*4.77)*1.9;
    t.fill(30, 8, 100 - fr(i*6.31)*46, 52);
    t.ellipse(fr(i*2.11)*tw, fr(i*3.97+4.4)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

// ---- moving chiaroscuro: sink the plate, then relight with a wandering pool.
// (a bare additive pool over the whole frame washes the mean luminance up past
// the 0.5 target and toward the 0.92 ceiling -- darken first, relight second.)
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (24 + 30*en));
L.blendMode(ADD);
const bx2 = plx/width*lw2, by2 = ply/height*lh2;
for (let i=0;i<9;i++){
  const q2=i/8, rr = Math.max(lw2,lh2)*(1.24 - q2*.96);
  L.fill(0, 0, 100, (6 + 7.5*en + 5*bass)*(.26 + .74*q2*q2));
  L.ellipse(bx2, by2, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;

