const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const T2 = Math.PI*2;
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);

function pal(){
  if (sty==='cyanotype') return { g:[213,73,17], line:[200,6,99], dark:[212,66,20], anno:[200,10,92], ctr:[196,36,80], grain:34, add:false, wash:[196,22,80], deck:[210,58,26],
    svc:[[200,10,96],[196,30,80],[204,20,88],[192,40,72]] };
  if (sty==='engraving') return { g:[38,17,72], line:[28,38,11], dark:[34,22,42], anno:[28,42,14], ctr:[8,62,42], grain:32, add:false, wash:[44,26,96], deck:[36,13,62],
    svc:[[28,40,14],[30,26,30],[26,50,22],[34,18,40]] };
  if (sty==='ghost')     return { g:[234,60,7], line:[H,24,98], dark:[H,64,12], anno:[H,16,86], ctr:[12,70,58], grain:16, add:true, wash:[H,44,60], deck:[232,52,12],
    svc:[[H,62,92],[H+40,58,84],[H+150,54,88],[H-40,60,80]] };
  if (sty==='pid')       return { g:[196,36,8], line:[178,62,94], dark:[196,44,12], anno:[52,56,88], ctr:[10,70,66], grain:14, add:false, wash:[184,40,58], deck:[196,42,12],
    svc:[[178,64,92],[52,60,90],[340,66,90],[130,54,84]] };
  return { g:[H,18,17], line:[H,5,93], dark:[H,26,12], anno:[H,6,88], ctr:[10,66,62], grain:28, add:false, wash:[H,12,80], deck:[H,14,26],
    svc:[[8,62,86],[142,44,74],[H,48,84],[38,66,88]] };
}
const C = pal();
const hw = q => ((q%360)+360)%360;
const sc = (c,a) => { stroke(hw(c[0]), c[1], c[2], a*AL); };
const fc = (c,a) => { fill(hw(c[0]), c[1], c[2], a*AL); };
const pid = (sty==='pid');
const SVCN = ['STEAM','CW','INST AIR','LUBE OIL'];

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.ft = (S.ft||0) + dt*P.speed*(.35+.9*NRG)*(.55+.75*K.intensity);      // flow clock, monotonic
const drx = .9*Math.sin(K.t*.137) + .5*Math.sin(K.t*.293+1.7) + .32*Math.sin(K.t*.451);
const dry = .8*Math.sin(K.t*.109+2.1) + .45*Math.sin(K.t*.257+.6) + .28*Math.sin(K.t*.611+1.9);
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.42+.58*NRG)*(.55+.5*K.intensity) + S.bs*.3;

// ---- axonometric sweep on two incommensurate rates (the motion floor) --------
const ROK = cl(P.rock,0,1);
const az = .30*ROK*(Math.sin(K.t*.083) + .58*Math.sin(K.t*.197+1.4)) + .10*ROK*Math.sin(K.t*.041+2.6);
const ca = Math.cos(az), sa = Math.sin(az);
const pr = (x,y,z) => { const x1=x*ca - z*sa, z1=x*sa + z*ca; return [(x1-z1)*.866, (x1+z1)*.5 - y]; };
const dep = (x,y,z) => { const x1=x*ca - z*sa, z1=x*sa + z*ca; return x1 + z1 + y*1.2; };

// ---- the network: a header with branch routes, Manhattan-routed in 3D --------
const NB = Math.round(3 + cl(P.density,0,1)*6);
const nkey = sd+'|'+NB;
if (S.nk !== nkey){
  S.nk = nkey;
  const GX=12, GY=6, GZ=8;
  const hy = 4.2, hz = GZ*.5;
  const lines = [];
  lines.push({ pts:[[0,hy,hz],[GX,hy,hz]], svc:0, dia:1.0, tag:'HDR-'+(100+(sd%90)), rate:.30 });
  for (let i=0;i<NB;i++){
    const bx = 1.1 + fr(i*3.7+2)*(GX-2.2);
    const ex = 0.6 + fr(i*5.3+7)*(GX-1.2);
    const ey = .5 + fr(i*7.1+11)*(GY-1.2);
    const ez = .5 + fr(i*9.7+13)*(GZ-1.0);
    const wx = 0.6 + fr(i*11.3+17)*(GX-1.2);
    const wy = .5 + fr(i*13.1+19)*(GY-1.0);
    const wz = .5 + fr(i*17.9+23)*(GZ-1.0);
    const pts = [[bx,hy,hz]];
    const leg = (from, to) => {
      const ord = [[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]][Math.floor(fr(i*19.3+from[0]+to[1]*2.3)*6)%6];
      let cur = from.slice();
      for (const ax of ord){ if (Math.abs(cur[ax]-to[ax]) > 1e-6){ const n=cur.slice(); n[ax]=to[ax]; pts.push(n); cur=n; } }
      return cur;
    };
    const mid = leg([bx,hy,hz], [wx,wy,wz]);
    leg(mid, [ex,ey,ez]);
    lines.push({ pts, svc: Math.floor(fr(i*23.1+29)*4)%4, dia: .48 + fr(i*29.3+31)*.42,
      tag: (Math.floor(fr(i*31.7+37)*8)+2)+'"-'+SVCN[Math.floor(fr(i*23.1+29)*4)%4].replace(/[^A-Z]/g,'').slice(0,2)+'-'+(100+Math.floor(fr(i*37.1+41)*880)),
      rate: .22 + fr(i*41.3+43)*.55, vpos: .25 + fr(i*43.7+47)*.5, vtype: Math.floor(fr(i*47.1+53)*3)%3 });
  }
  S.lines = lines; S.GX=GX; S.GY=GY; S.GZ=GZ;
}
const lines = S.lines || [];

// ---- fit the model to the frame --------------------------------------------
let bx0=1e9,by0=1e9,bx1=-1e9,by1=-1e9;
for (const L of lines) for (const p of L.pts){ const q=pr(p[0],p[1],p[2]);
  if(q[0]<bx0)bx0=q[0]; if(q[0]>bx1)bx1=q[0]; if(q[1]<by0)by0=q[1]; if(q[1]>by1)by1=q[1]; }
const bw = Math.max(.5, bx1-bx0), bh = Math.max(.5, by1-by0);
const CS = Math.min((width*.80)/bw, (height*.74)/bh) * cl(P.scale,.4,2.2);
const OX = cl(P.x,.2,.8)*width  - (bx0+bw*.5)*CS + u*.010*NRG*drx;
const OY = cl(P.y,.2,.8)*height - (by0+bh*.5)*CS + u*.009*NRG*dry;
const SX = p => OX + pr(p[0],p[1],p[2])[0]*CS;
const SY = p => OY + pr(p[0],p[1],p[2])[1]*CS;

// ---- ground -----------------------------------------------------------------
const gkey = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gkey !== gkey){
  if (S.gr && S.gr.remove) S.gr.remove();
  const gw=170, gh=Math.max(60, Math.round(170*height/Math.max(1,width)));
  const g = createGraphics(gw,gh); g.pixelDensity(1); g.loadPixels();
  for (let y=0;y<gh;y++) for (let x=0;x<gw;x++){
    const v = cl(255*(.44 + .32*fr(Math.floor(x/8)*13.71+Math.floor(y/8)*7.33+3.1) + .16*fr(Math.floor(x/3)*3.17+Math.floor(y/3)*11.9+8.7) + .08*fr(x*1.13+y*3.31+1.7)),0,255);
    const j=(y*gw+x)*4; g.pixels[j]=v; g.pixels[j+1]=v; g.pixels[j+2]=v; g.pixels[j+3]=255;
  }
  g.updatePixels(); S.gr = g; S.gkey = gkey;
}
noStroke(); fill(C.g[0],C.g[1],C.g[2],100); rect(0,0,width,height);
push(); blendMode(MULTIPLY); tint(0,0,100,C.grain); image(S.gr,0,0,width,height); pop();
blendMode(BLEND); noTint();
const wx2 = width*(.5+.26*Math.sin(K.t*.071)), wy2 = height*(.46+.22*Math.sin(K.t*.097+1.2));
push(); blendMode(SCREEN); noStroke();
for (let i=5;i>=1;i--){ fill(C.wash[0],C.wash[1],C.wash[2],(2.2+2.0*glow)*AL); const rw=u*(.30+i*.20); ellipse(wx2,wy2,rw*2,rw*1.7); }
pop(); blendMode(BLEND);

// ---- isometric deck grid: the datum plane the plant stands on ---------------
if (anno > .1){
  sc(C.ctr, 12+16*anno); strokeWeight(Math.max(.4,u*.0007));
  const GX=S.GX||12, GZ=S.GZ||8;
  for (let x=0;x<=GX;x+=2) line(SX([x,0,0]), SY([x,0,0]), SX([x,0,GZ]), SY([x,0,GZ]));
  for (let z=0;z<=GZ;z+=2) line(SX([0,0,z]), SY([0,0,z]), SX([GX,0,z]), SY([GX,0,z]));
}

// ---- build a depth-sorted draw list ----------------------------------------
const items = [];
for (let li=0; li<lines.length; li++){
  const L = lines[li];
  // arc-length parameterisation for the flow packets
  let tot = 0; const seg = [];
  for (let i=0;i<L.pts.length-1;i++){
    const a=L.pts[i], b=L.pts[i+1];
    const len = Math.abs(b[0]-a[0])+Math.abs(b[1]-a[1])+Math.abs(b[2]-a[2]);
    seg.push({a,b,len,s:tot}); tot += len;
  }
  L.tot = tot; L.seg = seg;
  for (const sg of seg) items.push({ k:'pipe', L, sg, d:(dep(sg.a[0],sg.a[1],sg.a[2])+dep(sg.b[0],sg.b[1],sg.b[2]))/2 });
  for (let i=1;i<L.pts.length-1;i++){ const p=L.pts[i]; items.push({ k:'elbow', L, p, d:dep(p[0],p[1],p[2])+.02 }); }
  const tp = L.pts[0], ep = L.pts[L.pts.length-1];
  items.push({ k:'end', L, p:ep, d:dep(ep[0],ep[1],ep[2])+.03 });
  if (li>0) items.push({ k:'tee', L, p:tp, d:dep(tp[0],tp[1],tp[2])+.03 });
  if (li>0 && L.seg.length){
    const si = Math.min(L.seg.length-1, Math.floor(L.vpos*L.seg.length));
    const sg = L.seg[si];
    const p = [ (sg.a[0]+sg.b[0])/2, (sg.a[1]+sg.b[1])/2, (sg.a[2]+sg.b[2])/2 ];
    items.push({ k:'valve', L, p, sg, d:dep(p[0],p[1],p[2])+.05 });
  }
}
items.sort((a,b)=>a.d-b.d);

// ---- tube renderer ----------------------------------------------------------
function tube(ax,ay,bx,by,w,col,dim){
  const dx=bx-ax, dy=by-ay, len=Math.hypot(dx,dy)||1;
  const nx=-dy/len, ny=dx/len;
  if (pid){ sc(col, 88*dim); strokeWeight(Math.max(.8, w*.30)); line(ax,ay,bx,by); return; }
  sc(C.dark, (C.add?26:76)*dim); strokeWeight(w); line(ax,ay,bx,by);
  sc(col, (C.add?46+24*glow:88)*dim); strokeWeight(w*.70); line(ax,ay,bx,by);
  sc([col[0], col[1]*.42, cl(col[2]*1.28,0,100)], (C.add?42:80)*dim); strokeWeight(Math.max(.5,w*.17));
  line(ax + nx*w*.24, ay + ny*w*.24, bx + nx*w*.24, by + ny*w*.24);
}
if (C.add) blendMode(ADD);
const dmin = -bh*.6, dspan = Math.max(1, (bx1-bx0)+bh*2);
for (const it of items){
  const L = it.L, col = C.svc[L.svc % C.svc.length];
  const w = Math.max(1.2, CS*L.dia*.28*(.7+.5*NRG));
  const dim = cl(.52 + .48*((it.d - dmin)/dspan + .35), .42, 1);      // atmospheric depth falloff
  if (it.k==='pipe'){
    tube(SX(it.sg.a), SY(it.sg.a), SX(it.sg.b), SY(it.sg.b), w, col, dim);
    // flanges along the run
    if (!pid && it.sg.len > 1.4){
      for (const f of [.30,.72]){
        const p=[it.sg.a[0]+(it.sg.b[0]-it.sg.a[0])*f, it.sg.a[1]+(it.sg.b[1]-it.sg.a[1])*f, it.sg.a[2]+(it.sg.b[2]-it.sg.a[2])*f];
        const q0=[it.sg.a[0],it.sg.a[1],it.sg.a[2]], q1=[it.sg.b[0],it.sg.b[1],it.sg.b[2]];
        const ax2=SX(q0), ay2=SY(q0), bx2=SX(q1), by2=SY(q1);
        const dx=bx2-ax2, dy=by2-ay2, ln=Math.hypot(dx,dy)||1;
        const nx=-dy/ln*w*.78, ny=dx/ln*w*.78;
        const px2=SX(p), py2=SY(p);
        sc(C.line, 72*dim); strokeWeight(Math.max(.7,w*.24));
        line(px2-nx, py2-ny, px2+nx, py2+ny);
      }
    }
  } else if (it.k==='elbow'){
    if (pid) continue;
    noStroke(); fc(col, (C.add?40:92)*dim); ellipse(SX(it.p), SY(it.p), w*.98, w*.98);
    noFill(); sc(C.dark, 60*dim); strokeWeight(Math.max(.4,w*.14)); ellipse(SX(it.p), SY(it.p), w*.98, w*.98);
  } else if (it.k==='tee' || it.k==='end'){
    const px2=SX(it.p), py2=SY(it.p);
    if (it.k==='end'){
      // the consumer: a small vessel / pump body standing on the deck
      const top=[it.p[0],it.p[1],it.p[2]], bot=[it.p[0],0,it.p[2]];
      sc(C.ctr, 26*dim + 18*anno); strokeWeight(Math.max(.4,u*.0007));
      line(px2,py2, SX(bot), SY(bot));                       // support / hanger drop
      if (!pid){
        noStroke(); fc(C.deck, (C.add?26:94)*dim);
        ellipse(px2, py2, w*2.0, w*2.0);
        noFill(); sc(C.line, 84*dim); strokeWeight(Math.max(.6,u*.0013));
        ellipse(px2, py2, w*2.0, w*2.0);
        sc(C.line, 56*dim); ellipse(px2, py2, w*1.1, w*1.1);
      } else { noFill(); sc(C.line, 86*dim); strokeWeight(Math.max(.7,u*.0015)); ellipse(px2,py2,w*1.6,w*1.6); }
    } else {
      noStroke(); fc(C.line, (C.add?36:80)*dim); ellipse(px2, py2, w*.9, w*.9);
    }
  } else if (it.k==='valve'){
    const px2=SX(it.p), py2=SY(it.p);
    const q0=[it.sg.a[0],it.sg.a[1],it.sg.a[2]], q1=[it.sg.b[0],it.sg.b[1],it.sg.b[2]];
    const dx=SX(q1)-SX(q0), dy=SY(q1)-SY(q0), ln=Math.hypot(dx,dy)||1;
    const ux=dx/ln, uy=dy/ln, nx=-uy, ny=ux;
    const vs = w*1.15;
    // valve travel cycles slowly, per line, on its own incommensurate rate
    const open = .5+.5*Math.sin(K.t*(.037+L.rate*.09) + L.svc*1.7);
    sc(C.line, 92*dim); strokeWeight(Math.max(.7,u*.0014));
    if (L.vtype===0 || pid){   // gate: the P&ID bowtie
      noFill();
      beginShape();
      vertex(px2-ux*vs+nx*vs, py2-uy*vs+ny*vs); vertex(px2-ux*vs-nx*vs, py2-uy*vs-ny*vs);
      vertex(px2+ux*vs+nx*vs, py2+uy*vs+ny*vs); vertex(px2+ux*vs-nx*vs, py2+uy*vs-ny*vs);
      endShape(CLOSE);
    } else if (L.vtype===1){   // globe
      noStroke(); fc(C.line, (C.add?34:88)*dim); ellipse(px2,py2, vs*1.6, vs*1.6);
      noFill(); sc(C.dark, 70*dim); ellipse(px2,py2, vs*1.6, vs*1.6);
    } else {                   // check: a triangle pointing with the flow
      noFill(); sc(C.line, 92*dim);
      triangle(px2-ux*vs-nx*vs*.9, py2-uy*vs-ny*vs*.9, px2-ux*vs+nx*vs*.9, py2-uy*vs+ny*vs*.9, px2+ux*vs, py2+uy*vs);
    }
    // stem + handwheel, turning as the valve travels
    const hx = px2 + nx*vs*2.0, hy2 = py2 + ny*vs*2.0;
    sc(C.line, 84*dim); strokeWeight(Math.max(.5,u*.0011));
    line(px2, py2, hx, hy2);
    noFill(); ellipse(hx, hy2, vs*1.5, vs*.75);
    const spa = open*Math.PI*3;
    line(hx - Math.cos(spa)*vs*.7, hy2 - Math.sin(spa)*vs*.35, hx + Math.cos(spa)*vs*.7, hy2 + Math.sin(spa)*vs*.35);
  }
}
blendMode(BLEND);

// ---- flow packets travelling the lines (real time, per-line rates) ----------
const NPK = Math.round(2 + NRG*3);
push(); blendMode(sty==='engraving' ? BLEND : ADD);
for (const L of lines){
  if (!L.seg || !L.tot) continue;
  const col = C.svc[L.svc % C.svc.length];
  for (let k=0;k<NPK;k++){
    const s = ((S.ft*L.rate*2.2 + k/NPK)%1) * L.tot;
    let acc = 0, sg = L.seg[0];
    for (const g2 of L.seg){ if (s >= g2.s && s < g2.s + g2.len){ sg = g2; acc = (s - g2.s)/Math.max(1e-6,g2.len); break; } }
    const p = [sg.a[0]+(sg.b[0]-sg.a[0])*acc, sg.a[1]+(sg.b[1]-sg.a[1])*acc, sg.a[2]+(sg.b[2]-sg.a[2])*acc];
    const px2 = SX(p), py2 = SY(p);
    const r = Math.max(1.6, CS*L.dia*.16*(.7+.6*NRG));
    noStroke();
    // soft halo: layered translucent discs (no filter(), no shadowBlur)
    for (let i=3;i>=1;i--){
      fc([col[0], cl(col[1]*.5,0,100), cl(col[2]*1.2,0,100)], (11 - i*2.4)*(.4+.7*glow));
      ellipse(px2, py2, r*2*(1+i*.85), r*2*(1+i*.85));
    }
    fc([col[0], cl(col[1]*.35,0,100), cl(col[2]*1.3,0,100)], 92*(.4+.7*glow));
    ellipse(px2, py2, r*2, r*2);
  }
}
pop(); blendMode(BLEND);

// ---- tag bubbles + line numbers --------------------------------------------
if (anno > .25){
  textFont('monospace'); textSize(Math.max(5,u*.0105));
  let n = 0;
  for (const L of lines){
    if (n++ > 8) break;
    if (!L.seg || !L.seg.length) continue;
    const sg = L.seg[Math.floor(L.seg.length*.5)];
    const p = [(sg.a[0]+sg.b[0])/2, (sg.a[1]+sg.b[1])/2, (sg.a[2]+sg.b[2])/2];
    const px2 = SX(p), py2 = SY(p);
    const lx = px2 + u*.045*(fr(n*3.1)<.5?-1:1), ly = py2 - u*.040;
    sc(C.anno, 56+24*anno); strokeWeight(Math.max(.4,u*.0007));
    line(px2, py2, lx, ly);
    noStroke(); fc(C.g, C.add?24:78); const tw = u*.058;
    rect(lx - (lx<px2?tw:0), ly - u*.010, tw, u*.020);
    noFill(); sc(C.anno, 70); strokeWeight(Math.max(.4,u*.0008));
    rect(lx - (lx<px2?tw:0), ly - u*.010, tw, u*.020);
    noStroke(); fc(C.anno, 92); textAlign(CENTER, CENTER);
    text(L.tag, lx - (lx<px2?tw/2:-tw/2), ly);
  }
}

// ---- sheet border + title block + service legend ----------------------------
const mgn = u*.028;
noFill(); sc(C.anno, 46+24*anno); strokeWeight(Math.max(.8,u*.0022));
rect(mgn, mgn, width-mgn*2, height-mgn*2);
sc(C.anno, 22+16*anno); strokeWeight(Math.max(.5,u*.0009));
rect(mgn*1.7, mgn*1.7, width-mgn*3.4, height-mgn*3.4);
if (anno > .08){
  textFont('monospace'); noStroke(); textSize(Math.max(7,u*.0135));
  textAlign(RIGHT,CENTER);
  const bx = width-mgn*2.0, by = height-mgn*2.0;
  fc(C.deck, C.add?28:74); rect(bx-u*.33, by-u*.052, u*.33, u*.052);
  noFill(); sc(C.anno, 62); strokeWeight(Math.max(.5,u*.0012)); rect(bx-u*.33, by-u*.052, u*.33, u*.052);
  line(bx-u*.33, by-u*.026, bx, by-u*.026);
  noStroke(); fc(C.anno, 90);
  text('PIPING ISOMETRIC - UNIT '+(10+(sd%80)), bx-u*.012, by-u*.039);
  text((pid?'P&ID SYMBOLS':'SPOOL VIEW')+'   '+lines.length+' LINES   SEED '+sd, bx-u*.012, by-u*.013);
  // service legend
  textAlign(LEFT,CENTER); textSize(Math.max(5,u*.0105));
  for (let i=0;i<4;i++){
    const ly = mgn*2.3 + i*u*.020;
    sc(C.svc[i], 92); strokeWeight(Math.max(1.4,u*.0035)); line(mgn*2.2, ly, mgn*2.2+u*.030, ly);
    noStroke(); fc(C.anno, 78); text(SVCN[i], mgn*2.2+u*.038, ly);
  }
  // north / orientation arrow for the isometric
  const nx3 = width-mgn*2.6, ny3 = mgn*3.0, nr = u*.020;
  const npt = pr(1,0,0);
  const na = Math.atan2(npt[1], npt[0]);
  sc(C.anno, 80); strokeWeight(Math.max(.6,u*.0013));
