// burn-in: arrive already grown
if (!S.burned) { S.burned = 1; for (let q = 0; q < 300; q++) growStep(); }
growStep();

// ---- moisture wash: wet soil darkens; the wetting front is visible ---------
wg.loadPixels(); const wp = wg.pixels;
const wetK = 52 + P.density * 62;
for (let i = 0; i < GW * GH; i++) {
