wg.updatePixels();

const drift = .5 + .5 * Math.sin(K.t * .071 + .55 * Math.sin(K.t * .0263 + 1.2));
const expo = 64 + P.energy * 28 + K.intensity * 7 + A.rms * 16 + drift * 8;
push();
tint(P.hue + hOff, tSat, Math.min(100, expo + 22), P.alpha);
image(rt, 0, 0, width, height);
blendMode(MULTIPLY);
tint(0, 0, 100, P.alpha);
image(wg, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;

const D = { energy:.6, scale:1, density:.5, speed:1, hue:28, flip:.6, hatch:.55, x:.5, y:.5, style:'engrave', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
