const fbm = (x, y) => vn(x, y) * 0.55 + vn(x * 2.03 + 11.3, y * 2.03 + 5.7) * 0.28 + vn(x * 4.11 + 3.9, y * 4.11 + 17.1) * 0.17;

g.loadPixels();
const gpx = g.pixels;
for (let j = 0; j < GH; j++) {
  const fy = (j + 0.5) / GH;
  for (let i = 0; i < GW; i++) {
    const fx = (i + 0.5) / GW;
    const ly2 = limbF(fx);
    // a plage: one stretch of rim is magnetically active and burns brighter
    const act = Math.exp(-Math.pow((fx - actX - 0.05 * dr1) / 0.26, 2)) * (0.28 + en * 0.42);
    let v;
    if (fy > ly2) {
      // below the limb: the disk, combed into fibrils that stream and reform along the field
      const d = (fy - ly2) / Math.max(0.02, 1 - ly2);
      const mott = fbm(fx * 7.0 + ts * 0.030 + dr2 * 0.10, fy * 21.0 - ts * 0.012);
      const fine = fbm(fx * 23.0 - ts * 0.021, fy * 46.0 + ts * 0.017);
      v = 0.40 + d * 0.20 + (mott - 0.5) * (0.64 + en * 0.48) + (fine - 0.5) * 0.26 + act * 0.45;
    } else {
      // above it: the glow the forest itself makes, falling off with height, and breathing
      const hh = ly2 - fy;
      const br = 1 + 0.10 * Math.sin(K.t * 0.071 + 1.2) + 0.06 * Math.sin(K.t * 0.163);
      const wisp = fbm(fx * 5.5 + ts * 0.045, fy * 9.0 - ts * 0.055) - 0.5;
      v = (0.50 + act) * br * Math.exp(-hh / (scaleH * (1 + wisp * 0.45)))
        + 0.072 + 0.038 * Math.exp(-hh / (scaleH * 4.5)) + wisp * 0.030 * Math.exp(-hh / (scaleH * 3));
    }
    v = v < 0 ? 0 : (v > 1 ? 1 : v);
    // gradient map, so even the sky is a tone rather than a flat fill
    let R, G2, B;
    if (fy > ly2 || v > 0.34) { const u = Math.min(1, Math.max(0, (v - 0.20) / 0.80)); R = chrom0[0] + (chrom1[0] - chrom0[0]) * u; G2 = chrom0[1] + (chrom1[1] - chrom0[1]) * u; B = chrom0[2] + (chrom1[2] - chrom0[2]) * u; }
    else { const u = Math.min(1, v / 0.34); R = sky0[0] + (sky1[0] - sky0[0]) * u; G2 = sky0[1] + (sky1[1] - sky0[1]) * u; B = sky0[2] + (sky1[2] - sky0[2]) * u; }
    const gn = fr2(i * 2.7 + 1.3, j * 5.1 + 7.9) - 0.5;
    R += gn * 0.045; G2 += gn * 0.045; B += gn * 0.045;
    const o = 4 * (j * GW + i);
    gpx[o] = R < 0 ? 0 : (R > 1 ? 255 : R * 255);
    gpx[o + 1] = G2 < 0 ? 0 : (G2 > 1 ? 255 : G2 * 255);
    gpx[o + 2] = B < 0 ? 0 : (B > 1 ? 255 : B * 255);
    gpx[o + 3] = 255;
  }
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- the forest ---------------------------------------------------------------------------
const N = Math.round(110 + dens * 340);
const NB = Math.max(3, Math.round(5 + dens * 12));      // supergranular network cells along the rim
const hMax = (0.40 + en * 0.34) * scl * height;
const wBase = (0.0034 + en * 0.0026) * scl * u0;
const leanA = (P.lean - 0.5) * 1.10;
const aMul = (P.alpha / 100);

push();
if (!inv && style !== 'sumi') blendMode(ADD);
noStroke();
const NSEG = 5;
for (let q = 0; q < N; q++) {
  const q1 = fr(q * 1.7 + 3.1), q2 = fr(q * 5.3 + 11.7), q3 = fr(q * 9.1 + 23.3), q4 = fr(q * 13.9 + 41.1), q5 = fr(q * 2.9 + 57.7);
  const rank = q % 3;                                    // 0 far, 1 mid, 2 near
  const rz = 0.42 + rank * 0.29;

  // bushes: jets crowd the network boundaries rather than scattering evenly
  const bi = Math.floor(q2 * NB);
  const bx0 = ((bi + 0.5) / NB + (fr(bi * 7.3 + 5) - 0.5) * 0.34 + 0.030 * Math.sin(ts * 0.031 + bi)) ;
  const bx = (bx0 + (q3 - 0.5) * (0.30 / NB) * 3.4) * width;

  const life = (7.5 + q4 * 9.0) / (0.55 + en * 0.75);    // s — its own period, always
  const ph = (ts / life + q1 * 6.13 + q3 * 2.71) % 1;
  const rise = Math.sin(ph * Math.PI);                   // up, hang, drain — then a new one
  if (rise < 0.02) continue;
  const vel = Math.cos(ph * Math.PI);                    // + climbing (blue), - draining (red)

  const h = hMax * rz * (0.42 + q4 * 0.80) * rise;
  const ang0 = leanA * (0.55 + q5 * 0.9) + (q1 - 0.5) * 0.52 + 0.10 * Math.sin(ts * 0.043 + q2 * TAU);
  const bend = (q5 - 0.5) * 0.62 + leanA * 0.35;
  const wq = wBase * rz * (0.55 + q3 * 0.9);

  // brightest mid-flight, dim at birth and death; far rank washed into the glow
  const lum = (0.28 + 0.72 * Math.sin(ph * Math.PI)) * (0.40 + rz * 0.85) * (0.5 + en * 0.75);

  let R, G2, B, aa;
  if (style === 'doppler') {
    // the real observable: sign of the line-of-sight velocity
    const s2 = vel * (0.5 + q3 * 0.7);
    const pos = s2 > 0 ? s2 : 0, neg = s2 < 0 ? -s2 : 0;
    R = 0.30 + neg * 0.92; G2 = 0.30 + Math.abs(s2) * 0.14; B = 0.32 + pos * 0.92;
    aa = 42 * lum * aMul;
  } else if (style === 'sumi') {
    R = 0.16; G2 = 0.15; B = 0.14; aa = 48 * lum * aMul;
  } else if (inv) {
    R = 0.10; G2 = 0.055; B = 0.05; aa = 46 * lum * aMul;   // dark mottles absorbing the disk
  } else if (style === 'ca_k') {
    const cc = h2rgb(266 - vel * 10, 0.30 - lum * 0.16, 1.0);
    R = cc[0]; G2 = cc[1]; B = cc[2]; aa = 34 * lum * aMul;
  } else {
    const cc = h2rgb(P.hue + 8 - lum * 5, 0.92 - lum * 0.34, 1.0);
    R = cc[0]; G2 = cc[1]; B = cc[2]; aa = 29 * lum * aMul;
  }
  if (aa < 1.2) continue;
  fill(0, 0, 0, 0);
  drawingContext.fillStyle = 'rgba(' + Math.round(Math.min(255, R * 255)) + ',' + Math.round(Math.min(255, G2 * 255)) + ',' + Math.round(Math.min(255, B * 255)) + ',' + Math.min(1, aa / 100).toFixed(3) + ')';

  // integrate the centreline up the field line, and rib it out to a tapered ribbon
  let cx = bx, cy = limbF(bx / width) * height + wq * 2, lx = [], ly = [], hw = [];
  const step = h / NSEG;
  for (let k = 0; k <= NSEG; k++) {
    const uu = k / NSEG;
    const ang = ang0 + bend * uu;
    lx.push(cx); ly.push(cy); hw.push(wq * (1 - uu * 0.78) * (0.6 + 0.4 * Math.sin(uu * 3.1 + q1 * 6)));
    cx += Math.sin(ang) * step; cy -= Math.cos(ang) * step;
  }
  beginShape();
  for (let k = 0; k <= NSEG; k++) {
    const ang = ang0 + bend * (k / NSEG);
    vertex(lx[k] + Math.cos(ang) * hw[k], ly[k] + Math.sin(ang) * hw[k]);
  }
  for (let k = NSEG; k >= 0; k--) {
    const ang = ang0 + bend * (k / NSEG);
    vertex(lx[k] - Math.cos(ang) * hw[k], ly[k] - Math.sin(ang) * hw[k]);
  }
  endShape(CLOSE);
}
pop();

// audio rides on top: a bass gust leans the whole forest, treble sparkles the tips.
// Baseline alone already carries everything above; this only adds.
if (A.rms > 0.01 || K.pulse > 0.01) {
  push();
  blendMode(ADD);
  noStroke();
  const lift = (A.bass * 0.55 + K.pulse * 0.22) * (0.4 + en);
  const cc = style === 'sumi' || inv ? [0.5, 0.48, 0.45] : h2rgb(P.hue + 10, 0.5, 1);
  fill(0, 0, 0, 0);
  drawingContext.fillStyle = 'rgba(' + Math.round(cc[0] * 255) + ',' + Math.round(cc[1] * 255) + ',' + Math.round(cc[2] * 255) + ',' + Math.min(1, lift * 0.10 * aMul).toFixed(3) + ')';
  rect(0, limbY - hMax * 0.5, width, hMax * 0.5 + (height - limbY));
  pop();
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;

const D = { energy: .6, scale: 1, speed: 1, density: .5, temp: .35, relief: .6, hue: 42, x: .5, y: .5, style: 'micrograph', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Cahn-Hilliard spinodal decomposition (CONSERVED order parameter):
//        mu = c^3 - c - eps2 * lap(c) ;  dc/dt = M * lap(mu)
// Two phases unmix out of a homogeneous melt and then coarsen: domains merge, boundaries
// straighten, features grow as ~t^(1/3) over minutes. ----
const BW = 168, BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.C = new Float32Array(N); S.MU = new Float32Array(N); S.init = false;
}

const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> not >> : an arithmetic fold caps the hash at 0.5
}

// ---- quench: seed the melt with small-amplitude fluctuation about the mean composition ----
if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  for (let i = 0; i < N; i++) S.C[i] = (hsh(i % BW, (i / BW) | 0, 1) - 0.5) * 0.28;
  S.tsim = 0;
}

const tt = K.t;
const C = S.C, MU = S.MU;
const eps2 = 1.0;
const dt = 0.014 * (0.25 + P.speed * 0.75);
const steps = 8;
// mean composition marches on incommensurate slow sines: the morphology walks
// droplets -> bicontinuous labyrinth -> inverted droplets and back, over minutes.
const cbar = 0.42 * (0.55 * Math.sin(tt * 0.0187) + 0.31 * Math.sin(tt * 0.0416 + 2.2) + 0.14 * Math.sin(tt * 0.0733 + 0.9))
           + (P.density - 0.5) * 0.5;
// thermal noise: physical, and the reason coarsening never freezes into a static frame
const th = (0.0016 + P.temp * 0.011);
// a wandering "hot spot" re-dissolves a moving patch of the specimen -> perpetual local re-quench
const hx = (0.5 + 0.34 * Math.sin(tt * 0.043) + 0.12 * Math.sin(tt * 0.117 + 1.3)) * BW;
const hy = (0.5 + 0.30 * Math.cos(tt * 0.059) + 0.11 * Math.sin(tt * 0.097 + 0.4)) * BH;
const hr = (0.10 + P.temp * 0.16) * BH;
const hr2 = hr * hr;
const nz = (tt * 601.7) | 0;

for (let st = 0; st < steps; st++) {
  // chemical potential mu = c^3 - c - eps2*lap(c)   (periodic wrap)
  for (let j = 0; j < BH; j++) {
    const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
      const c = C[jc + i];
      const lap = C[jc + im] + C[jc + ip] + C[jm + i] + C[jp + i] - 4 * c;
      MU[jc + i] = c * c * c - c - eps2 * lap;
    }
  }
  // dc/dt = M * lap(mu)  -> conserves total composition exactly (it is a divergence)
  for (let j = 0; j < BH; j++) {
    const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
      const lm = MU[jc + im] + MU[jc + ip] + MU[jm + i] + MU[jp + i] - 4 * MU[jc + i];
      let v = C[jc + i] + dt * lm;
      C[jc + i] = v < -1.6 ? -1.6 : (v > 1.6 ? 1.6 : v);   // guard the explicit scheme
    }
  }
}

// ---- forcing pass (once per frame): thermal fluctuation + the wandering re-quench spot,
// then gently pull the conserved mean toward the marching target composition ----
let sum = 0;
for (let j = 0; j < BH; j++) {
  const dy = j - hy;
  for (let i = 0; i < BW; i++) {
    const p = j * BW + i;
    let v = C[p] + (hsh(i, j, nz) - 0.5) * th * 2;
    const dx = i - hx, d2 = dx * dx + dy * dy;
    if (d2 < hr2) {                              // re-melt: pull this patch back toward the mean
      const w = (1 - d2 / hr2) * 0.05;
      v += (cbar - v) * w;
    }
    C[p] = v; sum += v;
  }
}
{
  const corr = (cbar - sum / N) * 0.06;
  for (let i = 0; i < N; i++) C[i] += corr;
}

// ---- render: metallographic section ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 13 + Math.sin(tt * 0.019) * 16) % 360 + 360) % 360;
const gain = 0.5 + P.energy * 1.3 + A.rms * 0.4;
const rel = P.relief;
function pal(m, sp, off) {
  const hr2b = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr2b)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr2b + sp)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr2b + sp * 2))];
}
for (let j = 0; j < BH; j++) {
  const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
    const c = C[jc + i];
    const gx = C[jc + ip] - C[jc + im], gy = C[jp + i] - C[jm + i];
    const gm = Math.sqrt(gx * gx + gy * gy);
    const phase = 0.5 + 0.5 * Math.max(-1, Math.min(1, c * 1.35));   // 0 = phase A, 1 = phase B
    const rim = Math.min(1, gm * 3.2);                                // interfacial boundary
    let r, gg, b;
    if (style === 'nomarski') {          // differential interference contrast: form from light only
      const sh = 0.40 + (gx * 0.62 - gy * 0.30) * 9.5 * (0.4 + rel);
      const v = Math.max(0, Math.min(1, sh));
      r = v * 0.90 + 0.06; gg = v * 0.88 + 0.07; b = v * 0.97 + 0.10;
    } else if (style === 'duotone') {    // 2-ink riso: hard threshold, plates misregistered
      const a1 = c > 0.02 ? 1 : 0;
      const c2 = C[((j + 1) % BH) * BW + ((i + 2) % BW)];
      const a2 = c2 < -0.02 ? 1 : 0;
      const paper = 0.93;
      r = paper - a1 * 0.10 - a2 * 0.72; gg = paper - a1 * 0.62 - a2 * 0.30; b = paper - a1 * 0.30 - a2 * 0.08;
      r = Math.max(0.03, r); gg = Math.max(0.03, gg); b = Math.max(0.05, b);
    } else if (style === 'thermal') {
      const m = Math.min(1, (phase * 0.62 + rim * 0.14) * (0.5 + P.energy * 0.8));
      r = Math.min(1, m * 2.15); gg = Math.min(1, Math.max(0, m * 2.0 - 0.55)); b = Math.min(1, Math.max(0, m * 3.1 - 2.05) + Math.max(0, 0.4 - m * 1.5));
    } else if (style === 'ink') {        // sumi: one phase inked on cream, boundaries bled
      const ink = Math.min(1, phase * 0.86 * (0.55 + gain * 0.45) + rim * 0.5 * rel);
      const paper = 0.94 - ink * 0.85;
      r = paper * 0.99; gg = paper * 0.96; b = paper * 0.88;
    } else {                             // micrograph (default) — etched section: the attacked phase
      // sits dark and the resistant phase bright, so the section has real tonal spread
      const c1 = pal(0.04, 0.16, 0.0), c2b = pal(0.46, 0.16, 0.0);
      const shade = (0.13 + 0.80 * phase) * (0.55 + gain * 0.45);
      // relief: light the interface as if the section were etched and lit from upper-left
      const lit = 1 + (gx * 0.66 - gy * 0.34) * 7.0 * rel;
      r = Math.min(1, (c1[0] + (c2b[0] - c1[0]) * phase) * shade * lit + rim * 0.26 * gain);
      gg = Math.min(1, (c1[1] + (c2b[1] - c1[1]) * phase) * shade * lit + rim * 0.28 * gain);
      b = Math.min(1, (c1[2] + (c2b[2] - c1[2]) * phase) * shade * lit + rim * 0.32 * gain);
    }
    const o = 4 * (jc + i);
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh2 = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh2) * Math.min(1, Math.max(0, P.y));
